-- Command help text (data-over-code).
--
-- `help <command>` in fierymud-rs shows a one-line summary and a long paragraph that used to
-- exist only as Rust strings. They now live in "Command".help_summary / help_text, editable in
-- Muditor. Command.description / usage are an older, differently worded catalog and are not
-- touched. The game uses, in order: a matching HelpEntry, the Command row's text, then the
-- built-in Rust string (so output is identical with or without this patch).
--
-- This patch:
--   * adds the two columns if missing (same DDL as Prisma `db push`);
--   * inserts a "Command" row for each game command the table lacks (category and
--     immortal_only derived from the registry; description / usage = its summary / usage);
--   * fills help_summary / help_text only while NULL or empty, so Muditor edits win.
--
-- 419 commands. Generated by scripts/gen_command_help_sql.py from
-- data/command_help.json. Idempotent: rerunning changes nothing.

BEGIN;

ALTER TABLE "Command" ADD COLUMN IF NOT EXISTS "help_summary" TEXT;
ALTER TABLE "Command" ADD COLUMN IF NOT EXISTS "help_text" TEXT;

INSERT INTO "Command" ("name", "aliases", "category", "description", "usage",
    "immortal_only", "help_summary", "help_text", "updated_at")
SELECT v.name, v.aliases, v.category, v.description, v.usage, v.immortal_only,
    v.help_summary, v.help_text, now()
FROM (VALUES
    ($cmdhelp$abandon$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Drop an in-progress quest.$cmdhelp$, $cmdhelp$abandon <#>$cmdhelp$, false, $cmdhelp$Drop an in-progress quest.$cmdhelp$, $cmdhelp$Argument is the slot number from the in-progress section of 'quests'. Marks the row ABANDONED rather than deleting it, preserving the audit trail and the (char, zone, id) unique key.$cmdhelp$),
    ($cmdhelp$abort$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Cancel an in-progress cast or queued spell.$cmdhelp$, $cmdhelp$abort$cmdhelp$, false, $cmdhelp$Cancel an in-progress cast or queued spell.$cmdhelp$, $cmdhelp$FieryMUD legacy: aborts the spell you're currently casting and clears any spell queued behind it. Today's runtime resolves casts immediately and has no queue, so abort has nothing to do — kept as a registered command name for muscle memory and to provide a clear message instead of 'Unknown command'. Use 'cancel' to drop a non-permanent buff already on you.$cmdhelp$),
    ($cmdhelp$accept$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Accept a pending group invite.$cmdhelp$, $cmdhelp$accept$cmdhelp$, false, $cmdhelp$Accept a pending group invite.$cmdhelp$, $cmdhelp$Joins the inviter's group and starts you following them. No-op if you have no pending invite.$cmdhelp$),
    ($cmdhelp$account$cmdhelp$, ARRAY[]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Show your account email, role, character roster, and linked Discord/Google.$cmdhelp$, $cmdhelp$account$cmdhelp$, false, $cmdhelp$Show your account email, role, character roster, and linked Discord/Google.$cmdhelp$, $cmdhelp$Read-only summary of who you're logged in as and which character is currently active. Snapshot taken at login — characters created mid-session won't appear until you reconnect. Also reads 'discord_links' and 'google_links' for your Users row and prints whatever's bound; Discord links display as 'verified' / 'unverified' so you can tell whether the bot will honor messages from the linked account. ('whoami' is a separate one-line identity command.)$cmdhelp$),
    ($cmdhelp$account_balance$cmdhelp$, ARRAY[$cmdhelp$abal$cmdhelp$, $cmdhelp$accountbal$cmdhelp$, $cmdhelp$accountbalance$cmdhelp$]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Show the account-shared bank balance.$cmdhelp$, $cmdhelp$account_balance$cmdhelp$, false, $cmdhelp$Show the account-shared bank balance.$cmdhelp$, $cmdhelp$Read-only display of 'Users.account_wealth'. Every character on this account sees the same pool; pair with 'account_deposit' / 'account_withdraw' to transfer between the per-character bank ('balance') and the shared pool.$cmdhelp$),
    ($cmdhelp$account_deposit$cmdhelp$, ARRAY[$cmdhelp$adeposit$cmdhelp$]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Move copper from per-character bank to the shared pool.$cmdhelp$, $cmdhelp$account_deposit <amount>$cmdhelp$, false, $cmdhelp$Move copper from per-character bank to the shared pool.$cmdhelp$, $cmdhelp$Source is your 'bank' balance, not on-hand. Refuses if your per-character bank can't cover the amount. After success every online character on this account sees the new shared pool size.$cmdhelp$),
    ($cmdhelp$account_withdraw$cmdhelp$, ARRAY[$cmdhelp$awithdraw$cmdhelp$]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Move copper from the shared pool to your per-character bank.$cmdhelp$, $cmdhelp$account_withdraw <amount>$cmdhelp$, false, $cmdhelp$Move copper from the shared pool to your per-character bank.$cmdhelp$, $cmdhelp$Inverse of 'account_deposit'. Refuses if the shared pool can't cover the amount. Cross-character sync runs after the transfer — all sibling characters online refresh their view of the pool.$cmdhelp$),
    ($cmdhelp$achievements$cmdhelp$, ARRAY[$cmdhelp$achieve$cmdhelp$]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$List your unlocked achievements (and visible-but-locked ones).$cmdhelp$, $cmdhelp$achievements [<category>]$cmdhelp$, false, $cmdhelp$List your unlocked achievements (and visible-but-locked ones).$cmdhelp$, $cmdhelp$Filter by category: combat, exploration, social, crafting, misc. Unlocked entries show with a tick; locked-but-visible ones with a placeholder. Hidden achievements stay invisible until unlocked — those are the spoiler ones.$cmdhelp$),
    ($cmdhelp$advance$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Set a player's level (admin level-up).$cmdhelp$, $cmdhelp$advance <player> <level>$cmdhelp$, true, $cmdhelp$Set a player's level (admin level-up).$cmdhelp$, $cmdhelp$Coder+ (level 104+) only. Bumps the target's XP to the threshold for <level> and runs the standard level-up loop, so HP/stamina max + practice points scale through the normal path. Refuses level decreases (those need a separate 'delevel' path).$cmdhelp$),
    ($cmdhelp$afk$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Flip your away-from-keyboard flag.$cmdhelp$, $cmdhelp$afk$cmdhelp$, false, $cmdhelp$Flip your away-from-keyboard flag.$cmdhelp$, $cmdhelp$Marks you AFK so others see the indicator on 'who' and on incoming tells. Run again to come back.$cmdhelp$),
    ($cmdhelp$aggr$cmdhelp$, ARRAY[$cmdhelp$aggro$cmdhelp$]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Show what's hostile to you right now.$cmdhelp$, $cmdhelp$aggr$cmdhelp$, false, $cmdhelp$Show what's hostile to you right now.$cmdhelp$, $cmdhelp$Lists every mob anywhere in the world that has you in its hate list (most recent swing first) or its memory (mobs you've fled from that will re-engage on sight). Mobs in your current room are flagged so you know what's about to swing. Mirrored as a 'Char.Aggro' GMCP frame on each prompt for HUD-style clients.$cmdhelp$),
    ($cmdhelp$aggrodebug$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Analyse aggression in this room, or toggle aggro logging.$cmdhelp$, $cmdhelp$aggrodebug [on|off]$cmdhelp$, true, $cmdhelp$Analyse aggression in this room, or toggle aggro logging.$cmdhelp$, $cmdhelp$Immortal+. With no argument, lists every mob in the room with its alignment and aggression formula and reports whether it would attack you. 'aggrodebug on' makes the server log every aggression check (target 'aggression', level info) until 'aggrodebug off'.$cmdhelp$),
    ($cmdhelp$alert$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Stop resting and pay attention, without standing up.$cmdhelp$, $cmdhelp$alert$cmdhelp$, false, $cmdhelp$Stop resting and pay attention, without standing up.$cmdhelp$, $cmdhelp$The opposite of 'rest': you drop the resting stance and sit at attention. Does nothing if you are already alert.$cmdhelp$),
    ($cmdhelp$alias$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Define a command shortcut.$cmdhelp$, $cmdhelp$alias [<name> [<command>]]$cmdhelp$, false, $cmdhelp$Define a command shortcut.$cmdhelp$, $cmdhelp$With no args, lists every alias you've defined. With 'alias <name>', shows that alias's expansion. With 'alias <name> <command>', sets the alias ('unalias <name>' removes it). A plain alias replaces whatever you type (extra words are dropped). Put '$*' where the rest of your line should go, '$1'..'$9' for single words, and ';' between commands to chain them: 'alias gg get all corpse;put all bag' or 'alias k kill $1;kill $2'. An alias never re-triggers itself, so 'alias look look $*' wraps the real command. Aliases persist across sessions.$cmdhelp$),
    ($cmdhelp$alist$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$List loaded abilities with optional filters.$cmdhelp$, $cmdhelp$alist [--type spell|skill|chant|song] [--circle N] [--effect type] [--limit N]$cmdhelp$, true, $cmdhelp$List loaded abilities with optional filters.$cmdhelp$, $cmdhelp$Builder+. Lists abilities from the ability catalog. Abilities with no effects are flagged (NO EFFECTS). Default limit 50.$cmdhelp$),
    ($cmdhelp$apply$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Spawn an effect on a player.$cmdhelp$, $cmdhelp$apply <player> <effect> [duration_secs]$cmdhelp$, true, $cmdhelp$Spawn an effect on a player.$cmdhelp$, $cmdhelp$Implementor-only. Effect name is matched against the EffectCatalog. Default duration 60s.$cmdhelp$),
    ($cmdhelp$approve_name$cmdhelp$, ARRAY[$cmdhelp$approvename$cmdhelp$]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Approve a pending character name (keep the name).$cmdhelp$, $cmdhelp$approve_name <character>$cmdhelp$, true, $cmdhelp$Approve a pending character name (keep the name).$cmdhelp$, $cmdhelp$Immortal+. Flips Characters.name_approved to true for the named character. Removes the NameApprovalPending marker on the live entity if they're online and DMs them. No-op against an already-approved character. Pair with 'reject_name <char> <new>' if the name needs to change.$cmdhelp$),
    ($cmdhelp$areas$cmdhelp$, ARRAY[]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$List the areas of the realm.$cmdhelp$, $cmdhelp$areas [<text>]$cmdhelp$, false, $cmdhelp$List the areas of the realm.$cmdhelp$, $cmdhelp$Lists every area open to players, with its zone number. Give some text to list only the areas whose name contains it, e.g. 'areas forest'.$cmdhelp$),
    ($cmdhelp$areload$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Reload the ability and effect catalogs from the DB.$cmdhelp$, $cmdhelp$areload$cmdhelp$, true, $cmdhelp$Reload the ability and effect catalogs from the DB.$cmdhelp$, $cmdhelp$Coder+. Re-reads every ability (with restrictions, effects, targeting, saves, components, damage components and messages) and the effect catalog, then swaps them into the running server.$cmdhelp$),
    ($cmdhelp$asearch$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Search abilities by name, effect type, or find broken ones.$cmdhelp$, $cmdhelp$asearch <name> | --effect <type> | --no-effects$cmdhelp$, true, $cmdhelp$Search abilities by name, effect type, or find broken ones.$cmdhelp$, $cmdhelp$Builder+. 'asearch fire' matches ability names; '--effect heal' finds abilities applying an effect of that type; '--no-effects' finds abilities that would cast but do nothing.$cmdhelp$),
    ($cmdhelp$ask$cmdhelp$, ARRAY[]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Ask a mob about a topic — fires SPEECH triggers.$cmdhelp$, $cmdhelp$ask <mob> <topic>$cmdhelp$, false, $cmdhelp$Ask a mob about a topic — fires SPEECH triggers.$cmdhelp$, $cmdhelp$Targets a single mob in the room and fires its SPEECH-flagged Lua bodies with the topic in the 'speech' Lua global. Bystanders see that you asked something but not what.$cmdhelp$),
    ($cmdhelp$assist$cmdhelp$, ARRAY[$cmdhelp$ass$cmdhelp$]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Engage your ally's current target.$cmdhelp$, $cmdhelp$assist <player>$cmdhelp$, false, $cmdhelp$Engage your ally's current target.$cmdhelp$, $cmdhelp$Looks up <player> in your current room, finds whom they're fighting, and engages that target — same stamina cost and rules as 'attack'. Refused if they're not fighting, if their target is gone, or if you're already fighting someone else.$cmdhelp$),
    ($cmdhelp$astat$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Dump an ability's metadata.$cmdhelp$, $cmdhelp$astat <ability>$cmdhelp$, true, $cmdhelp$Dump an ability's metadata.$cmdhelp$, $cmdhelp$Builder+. Looks up the ability by name (or id) and shows its school, cost, duration, restrictions, linked effects.$cmdhelp$),
    ($cmdhelp$at$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Run a command as if you were standing somewhere else.$cmdhelp$, $cmdhelp$at <location> <command>$cmdhelp$, true, $cmdhelp$Run a command as if you were standing somewhere else.$cmdhelp$, $cmdhelp$Builder+. The location takes the same forms as 'goto': a room id in your zone, '<zone> <id>' or '<zone>:<id>', 'home', or the name of a player or mob (their room). You are moved there for the one command and put back afterwards, with no poof messages. If the command moves you (goto, a teleport) you stay where it left you; if you die you stay where you died. Moving ends any fight you are in, as it did in the legacy 'at'.$cmdhelp$),
    ($cmdhelp$attach$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Attach a trigger to a live mob, object or room.$cmdhelp$, $cmdhelp$attach { mtr | otr | wtr } { zone:id } { name | room } [ position ]$cmdhelp$, true, $cmdhelp$Attach a trigger to a live mob, object or room.$cmdhelp$, $cmdhelp$Implementor only. 'attach mtr 30:5 guard' bolts trigger 30:5 onto the mob 'guard'; otr takes an object name, wtr a room as 'zone:id'. The change is live only: it is not saved, and a respawned mob starts over with its prototype's triggers. <position> is 0 for the front of the list, otherwise the index to insert at (default: the end). The trigger's own type has to match: mtr for a mob trigger, otr for an object trigger, wtr for a world trigger.$cmdhelp$),
    ($cmdhelp$attack$cmdhelp$, ARRAY[$cmdhelp$hit$cmdhelp$, $cmdhelp$murder$cmdhelp$]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Engage a target in melee combat.$cmdhelp$, $cmdhelp$attack <target>$cmdhelp$, false, $cmdhelp$Engage a target in melee combat.$cmdhelp$, $cmdhelp$Match is by case-insensitive substring on visible names. Targets with combat stats will fight back. Combat resolves once per second on the world tick.$cmdhelp$),
    ($cmdhelp$autoassist$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Toggle automatically joining fights against the one you follow.$cmdhelp$, $cmdhelp$autoassist$cmdhelp$, false, $cmdhelp$Toggle automatically joining fights against the one you follow.$cmdhelp$, $cmdhelp$Sets AUTO_ASSIST. While you stand in the same room as someone you follow, or a member of your group, you automatically engage anyone who attacks them, whether a player or a monster starts the fight. You do not join when you are already fighting, are asleep or resting, or the attacker is not in your room.$cmdhelp$),
    ($cmdhelp$autoexit$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Toggle automatic exit listing on 'look'.$cmdhelp$, $cmdhelp$autoexit$cmdhelp$, false, $cmdhelp$Toggle automatic exit listing on 'look'.$cmdhelp$, $cmdhelp$When set, the room description is followed by the same line 'exits' would print. Already consumed by the look path.$cmdhelp$),
    ($cmdhelp$autogold$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Toggle automatic collection of coins from kills.$cmdhelp$, $cmdhelp$autogold$cmdhelp$, false, $cmdhelp$Toggle automatic collection of coins from kills.$cmdhelp$, $cmdhelp$Sets AUTO_GOLD. Coins from mobs you kill jump straight to your purse without taking the items (autoloot already collects coins too).$cmdhelp$),
    ($cmdhelp$autoloot$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Toggle automatic looting of kills (items and coins).$cmdhelp$, $cmdhelp$autoloot$cmdhelp$, false, $cmdhelp$Toggle automatic looting of kills (items and coins).$cmdhelp$, $cmdhelp$Sets AUTO_LOOT. Items and coins from mobs you kill jump straight to you. Coins respect autosplit.$cmdhelp$),
    ($cmdhelp$autosplit$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Toggle automatic splitting of coins you pick up.$cmdhelp$, $cmdhelp$autosplit$cmdhelp$, false, $cmdhelp$Toggle automatic splitting of coins you pick up.$cmdhelp$, $cmdhelp$Sets AUTO_SPLIT. Coins you take from a corpse, the floor or an autolooted kill are split evenly with the groupmates standing in the room; you keep the remainder. Use 'split <amount>' to divide coins by hand.$cmdhelp$),
    ($cmdhelp$backstab$cmdhelp$, ARRAY[$cmdhelp$bs$cmdhelp$]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Surprise opener for double damage; out-of-combat only.$cmdhelp$, $cmdhelp$backstab <target>$cmdhelp$, false, $cmdhelp$Surprise opener for double damage; out-of-combat only.$cmdhelp$, $cmdhelp$Deals 2x your damage on the opening swing and engages the target. Refused if you're already fighting (the target sees you coming) or if your target is already in combat with someone else.$cmdhelp$),
    ($cmdhelp$balance$cmdhelp$, ARRAY[$cmdhelp$bal$cmdhelp$]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Show your bank-stored coin.$cmdhelp$, $cmdhelp$balance$cmdhelp$, false, $cmdhelp$Show your bank-stored coin.$cmdhelp$, $cmdhelp$Read-only display of the 'bank_wealth' column from your character row. Pair with 'deposit' / 'withdraw' to move coin to / from the bank.$cmdhelp$),
    ($cmdhelp$ban$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Ban a player's account.$cmdhelp$, $cmdhelp$ban <player> <reason>$cmdhelp$, true, $cmdhelp$Ban a player's account.$cmdhelp$, $cmdhelp$Implementor-only. Looks up the player by name, resolves the owning Users row, inserts a BanRecords row. The login flow refuses any of that account's characters until 'unban' lifts.$cmdhelp$),
    ($cmdhelp$bandage$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Apply first aid for a small heal (out of combat).$cmdhelp$, $cmdhelp$bandage [<target>]$cmdhelp$, false, $cmdhelp$Apply first aid for a small heal (out of combat).$cmdhelp$, $cmdhelp$Heals 10 HP at a cost of 4 stamina. With no arg or 'me'/'self', bandages yourself. Otherwise tries to find the target in your room. Refused while fighting and refused on full-HP targets.$cmdhelp$),
    ($cmdhelp$bash$cmdhelp$, ARRAY[$cmdhelp$bodyslam$cmdhelp$, $cmdhelp$maul$cmdhelp$]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Slam a target, knocking them off their feet.$cmdhelp$, $cmdhelp$bash <target>$cmdhelp$, false, $cmdhelp$Slam a target, knocking them off their feet.$cmdhelp$, $cmdhelp$Deals weapon damage + 3 and forces the target into a sitting posture. Targets without combat stats simply take the damage.$cmdhelp$),
    ($cmdhelp$berserk$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Self-buff: rage state for 60s.$cmdhelp$, $cmdhelp$berserk$cmdhelp$, false, $cmdhelp$Self-buff: rage state for 60s.$cmdhelp$, $cmdhelp$Costs 8 stamina, spawns a 'berserk' EffectInstance on yourself for 60s. Refused if already berserk. Combat damage scaling is a follow-up — for now this is the visible buff state.$cmdhelp$),
    ($cmdhelp$board$cmdhelp$, ARRAY[]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$List or read messages on a board.$cmdhelp$, $cmdhelp$board <alias> [#]$cmdhelp$, false, $cmdhelp$List or read messages on a board.$cmdhelp$, $cmdhelp$With just an alias, lists messages newest first (sticky-marked entries float to the top). Append a slot number to read that message's body.$cmdhelp$),
    ($cmdhelp$boards$cmdhelp$, ARRAY[]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$List every public message board.$cmdhelp$, $cmdhelp$boards$cmdhelp$, false, $cmdhelp$List every public message board.$cmdhelp$, $cmdhelp$Each board has an alias ('mortal', 'god', 'quest', etc.) and a title. Use 'board <alias>' to list messages on one.$cmdhelp$),
    ($cmdhelp$breathe$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Dragonborn breath weapon — race-typed.$cmdhelp$, $cmdhelp$breathe [<target>]$cmdhelp$, false, $cmdhelp$Dragonborn breath weapon — race-typed.$cmdhelp$, $cmdhelp$Dispatches the BREATHE_* ability your race grants (the DRAGONBORN_* races carry one, per the RaceAbilities table; 'innate breathe fire' works too). Refuses for races with no breath weapon. Drains 6 stamina; the actual damage / target gating runs through the data path.$cmdhelp$),
    ($cmdhelp$bribe$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Hand a sum of copper to a mob — fires BRIBE triggers.$cmdhelp$, $cmdhelp$bribe <amount> <target>$cmdhelp$, false, $cmdhelp$Hand a sum of copper to a mob — fires BRIBE triggers.$cmdhelp$, $cmdhelp$Decrements your on-hand coin by 'amount' (copper units) and pads the target mob's coin by the same. Fires the target's BRIBE-flagged Lua triggers with 'actor' = you and 'amount' as a Lua global so bodies can react proportionally.$cmdhelp$),
    ($cmdhelp$brief$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Toggle terse room descriptions.$cmdhelp$, $cmdhelp$brief$cmdhelp$, false, $cmdhelp$Toggle terse room descriptions.$cmdhelp$, $cmdhelp$When on, 'look' skips the full room description and shows just the title + exits + occupants.$cmdhelp$),
    ($cmdhelp$buck$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Throw a rider — dismount + knockdown.$cmdhelp$, $cmdhelp$buck <target>$cmdhelp$, false, $cmdhelp$Throw a rider — dismount + knockdown.$cmdhelp$, $cmdhelp$Drains 5 stamina and dispatches the BUCK skill at the named target. The schema's data path runs 'dismount' (forced=true) → clears Mounted/RiddenBy, then 'knockdown' (duration=1) → drops the target's posture. v1 dispatches as a player skill so characters with BUCK trained (Sorcerer/Druid/etc.) can fire it; mob-AI usage waits for an autonomous ability scheduler.$cmdhelp$),
    ($cmdhelp$bug$cmdhelp$, ARRAY[]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Report a bug to the staff.$cmdhelp$, $cmdhelp$bug <message>$cmdhelp$, false, $cmdhelp$Report a bug to the staff.$cmdhelp$, $cmdhelp$Logs a feedback row to the 'Reports' table. Body captures your name + character_id + room + the text. Empty messages refuse so we don't fill the table with noise.$cmdhelp$),
    ($cmdhelp$buy$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Buy an item from the shopkeeper here.$cmdhelp$, $cmdhelp$buy <#|name>$cmdhelp$, false, $cmdhelp$Buy an item from the shopkeeper here.$cmdhelp$, $cmdhelp$Argument is either the catalog index from 'list' or a substring of the item's name. Coin is deducted from your 'wealth'; the item lands in your inventory. Stock is advisory until per-shop instance state lands.$cmdhelp$),
    ($cmdhelp$call$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Call your followers to your location.$cmdhelp$, $cmdhelp$call$cmdhelp$, false, $cmdhelp$Call your followers to your location.$cmdhelp$, $cmdhelp$Every mob following you (pets, hirelings, charmed creatures) that isn't already in your room leaves whatever it was doing and joins you. A mount you are riding is left alone.$cmdhelp$),
    ($cmdhelp$camp$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Pitch camp, then save and leave the game.$cmdhelp$, $cmdhelp$camp$cmdhelp$, false, $cmdhelp$Pitch camp, then save and leave the game.$cmdhelp$, $cmdhelp$Refuses indoors, in cities, on water, in the air, while mounted, or while in combat. Once setup completes (~35 seconds), you're saved and leave the game, to return right here. Walking away or being attacked aborts the camp.$cmdhelp$),
    ($cmdhelp$cancel$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Drop one of your own timed beneficial spells.$cmdhelp$, $cmdhelp$cancel [<effect>]$cmdhelp$, false, $cmdhelp$Drop one of your own timed beneficial spells.$cmdhelp$, $cmdhelp$With no arg, lists the effects you can cancel. With an effect name (a prefix works; quote multi-word names), ends that beneficial spell on you right away, exactly as if it had worn off. Permanent effects (racial or from gear) and harmful ones cannot be cancelled, and you cannot cancel while fighting.$cmdhelp$),
    ($cmdhelp$cartwheel$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Tumble past your foe with an acrobatic strike.$cmdhelp$, $cmdhelp$cartwheel$cmdhelp$, false, $cmdhelp$Tumble past your foe with an acrobatic strike.$cmdhelp$, $cmdhelp$Acrobatic attack that evades while striking. Requires an active fight; strikes your current opponent using the CARTWHEEL ability from the database.$cmdhelp$),
    ($cmdhelp$cast$cmdhelp$, ARRAY[$cmdhelp$c$cmdhelp$]::text[], 'MAGIC'::"CommandCategory", $cmdhelp$Cast a spell from the loaded catalog.$cmdhelp$, $cmdhelp$cast <spell> [target]$cmdhelp$, false, $cmdhelp$Cast a spell from the loaded catalog.$cmdhelp$, $cmdhelp$Looks up a SPELL by case-insensitive name (partial match accepted). For now this is a stub: prints the ability's metadata so you can see what's in the catalog. Real effect application — slot consumption, restriction checks, damage/heal/buff resolution — lands when CharacterAbilities and the effect pipeline are wired. Only matches abilityType = SPELL; for chants and songs use 'chant' / 'perform'.$cmdhelp$),
    ($cmdhelp$cclan$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Manage clans (create / assign / kick / MOTD).$cmdhelp$, $cmdhelp$cclan create <name> <abbrev>
       cclan assign <player> <abbrev> [rank]
       cclan kick <player>
       cclan motd <abbrev> <text>
       cclan disband <abbrev>$cmdhelp$, true, $cmdhelp$Manage clans (create / assign / kick / MOTD).$cmdhelp$, $cmdhelp$Implementor-only.
- 'create' opens a new clan; name + abbrev must both be unique.
- 'assign' puts a character into a clan, defaulting to MEMBER. Rank can be LEADER / OFFICER / MEMBER / APPLICANT.
- 'kick' removes their clan_member row entirely.
- 'motd' sets a clan's message-of-the-day; empty text clears it.$cmdhelp$),
    ($cmdhelp$chant$cmdhelp$, ARRAY[]::text[], 'MAGIC'::"CommandCategory", $cmdhelp$Invoke a chant from the catalog (cleric-side spells).$cmdhelp$, $cmdhelp$chant <chant> [target]$cmdhelp$, false, $cmdhelp$Invoke a chant from the catalog (cleric-side spells).$cmdhelp$, $cmdhelp$Same shape as 'cast' but filters to abilityType = CHANT. Stub: prints metadata and gates on KnownAbilities, no effect application yet.$cmdhelp$),
    ($cmdhelp$chants$cmdhelp$, ARRAY[]::text[], 'MAGIC'::"CommandCategory", $cmdhelp$List chants you know (or the full catalog).$cmdhelp$, $cmdhelp$chants [all] [filter]$cmdhelp$, false, $cmdhelp$List chants you know (or the full catalog).$cmdhelp$, $cmdhelp$Like 'spells' but filtered to kind=Chant. Default shows only chants you've learned; 'chants all' dumps the catalog. Use 'chant <name>' to invoke.$cmdhelp$),
    ($cmdhelp$charset$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Choose plain ASCII or UTF-8 output.$cmdhelp$, $cmdhelp$charset [ascii|utf8|auto]$cmdhelp$, false, $cmdhelp$Choose plain ASCII or UTF-8 output.$cmdhelp$, $cmdhelp$Clients that don't announce UTF-8 support get plain ASCII: dashes, arrows, stars and box-drawing characters are replaced by look-alikes (-- -> * + - |). If your client does display UTF-8, 'charset utf8' turns the real symbols on; 'charset ascii' forces plain text; 'charset auto' follows what your client reports. Saved with your character. 'charset' alone shows the current setting.$cmdhelp$),
    ($cmdhelp$chest$cmdhelp$, ARRAY[$cmdhelp$accountchest$cmdhelp$, $cmdhelp$achest$cmdhelp$, $cmdhelp$storage$cmdhelp$, $cmdhelp$vault$cmdhelp$]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$List items in your account-shared chest.$cmdhelp$, $cmdhelp$chest [deposit <item> | withdraw <number>]$cmdhelp$, false, $cmdhelp$List items in your account-shared chest.$cmdhelp$, $cmdhelp$Shows every item any character on this account has stored. 'chest deposit <item>' stores an item (same as 'chest_deposit'); 'chest withdraw <number>' takes the numbered item back (same as 'chest_withdraw').$cmdhelp$),
    ($cmdhelp$chest_deposit$cmdhelp$, ARRAY[$cmdhelp$chestdeposit$cmdhelp$]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Store an inventory item in the account chest.$cmdhelp$, $cmdhelp$chest_deposit <item>   (or: chest deposit <item>)$cmdhelp$, false, $cmdhelp$Store an inventory item in the account chest.$cmdhelp$, $cmdhelp$Moves the named item from your inventory into the account-shared chest, where any character on this account can take it back via 'chest_withdraw'. Refuses SOULBOUND and NO_DROP items.$cmdhelp$),
    ($cmdhelp$chest_withdraw$cmdhelp$, ARRAY[$cmdhelp$chestwithdraw$cmdhelp$]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Take an item back from the account chest.$cmdhelp$, $cmdhelp$chest_withdraw <number>   (or: chest withdraw <number>)$cmdhelp$, false, $cmdhelp$Take an item back from the account chest.$cmdhelp$, $cmdhelp$Withdraws the item with the given number (see 'chest' for the listing; numbering starts at 1). The item is spawned back into your inventory with its per-instance state (charges, liquid level) restored.$cmdhelp$),
    ($cmdhelp$clan$cmdhelp$, ARRAY[$cmdhelp$cl$cmdhelp$]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Show your clan's info, MOTD, and roster.$cmdhelp$, $cmdhelp$clan$cmdhelp$, false, $cmdhelp$Show your clan's info, MOTD, and roster.$cmdhelp$, $cmdhelp$Prints clan name + abbreviation + MOTD plus the roster (sorted leader→officer→member, then by level desc, then name). Online members are marked with a '*'. Refused for players not in a clan. Subcommands: 'clan motd <text>' (LEADER / OFFICER), 'clan kick <player>' (LEADER).$cmdhelp$),
    ($cmdhelp$claw$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Slash with bestial claws.$cmdhelp$, $cmdhelp$claw <target>$cmdhelp$, false, $cmdhelp$Slash with bestial claws.$cmdhelp$, $cmdhelp$Gated on knowing the Claw skill (legacy grants it to animal shapechange forms). Counts as a violent opening — engages the target if you're not already fighting them. Random damage scaled by your level.$cmdhelp$),
    ($cmdhelp$clientinfo$cmdhelp$, ARRAY[]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Show this session's connection info.$cmdhelp$, $cmdhelp$clientinfo$cmdhelp$, false, $cmdhelp$Show this session's connection info.$cmdhelp$, $cmdhelp$Reports your active character, role, session uptime (since login), and idle time (since the last command typed). Terminal capabilities — color depth, dimensions, MCCP — aren't tracked in the runtime today; the full RFC-1408 telnet negotiation would lift them off the wire.$cmdhelp$),
    ($cmdhelp$clist$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$List every class with its catalog id.$cmdhelp$, $cmdhelp$clist$cmdhelp$, true, $cmdhelp$List every class with its catalog id.$cmdhelp$, $cmdhelp$Builder+. Pairs the class plain name with its numeric id (the value 'Profile.class_id' carries) so you can plug it into 'set' / 'skillset' / 'advance' paths.$cmdhelp$),
    ($cmdhelp$close$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Close an open door in the given direction.$cmdhelp$, $cmdhelp$close <direction>$cmdhelp$, false, $cmdhelp$Close an open door in the given direction.$cmdhelp$, $cmdhelp$Refused if the exit has no door, is already closed, or doesn't exist.$cmdhelp$),
    ($cmdhelp$cls$cmdhelp$, ARRAY[$cmdhelp$clear$cmdhelp$]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Clear the terminal screen.$cmdhelp$, $cmdhelp$cls$cmdhelp$, false, $cmdhelp$Clear the terminal screen.$cmdhelp$, $cmdhelp$Sends the ANSI clear-screen + cursor-home escape sequence. Cosmetic only; no game state changes.$cmdhelp$),
    ($cmdhelp$color$cmdhelp$, ARRAY[$cmdhelp$colour$cmdhelp$]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Choose how much color you see.$cmdhelp$, $cmdhelp$color [off|16|256|truecolor|auto]$cmdhelp$, false, $cmdhelp$Choose how much color you see.$cmdhelp$, $cmdhelp$The server asks your client what it can display and adapts: 256-color and truecolor shades are mapped to the nearest of the 16 basic colors for clients that only do 16. 'color off' removes color entirely, 'color 16' / 'color 256' / 'color truecolor' pin a depth if your client misreports itself, and 'color auto' goes back to following the client. Saved with your character. 'color' alone shows the current setting.$cmdhelp$),
    ($cmdhelp$columns$cmdhelp$, ARRAY[$cmdhelp$wrap$cmdhelp$]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Set the width long text is word-wrapped to.$cmdhelp$, $cmdhelp$columns [<40-250>|auto]$cmdhelp$, false, $cmdhelp$Set the width long text is word-wrapped to.$cmdhelp$, $cmdhelp$The server wraps room descriptions, help and other prose to your client's reported window width (80 if it doesn't report one). 'columns 100' wraps narrower than the window, which reads better on very wide windows (a value wider than your window is capped to it); 'columns auto' goes back to following the client. The setting is saved with your character. 'toggle columns <n>' works too.$cmdhelp$),
    ($cmdhelp$commands$cmdhelp$, ARRAY[$cmdhelp$comm$cmdhelp$]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Flat alphabetical list of every command you can use.$cmdhelp$, $cmdhelp$commands [<category>]$cmdhelp$, false, $cmdhelp$Flat alphabetical list of every command you can use.$cmdhelp$, $cmdhelp$Shows just the names you have access to, without the per-category framing 'help' uses. Aliases share their primary name's slot. With a category arg (info / movement / communication / combat / admin) the list is filtered to that category, useful when the full 200+ command roster is overwhelming.$cmdhelp$),
    ($cmdhelp$compact$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Toggle compact output (suppresses leading blank lines).$cmdhelp$, $cmdhelp$compact$cmdhelp$, false, $cmdhelp$Toggle compact output (suppresses leading blank lines).$cmdhelp$, $cmdhelp$Sets COMPACT. Renderers that respect it tighten their leading whitespace.$cmdhelp$),
    ($cmdhelp$compare$cmdhelp$, ARRAY[$cmdhelp$comp$cmdhelp$]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Compare two carried/worn items by weight, level, and weapon damage.$cmdhelp$, $cmdhelp$compare <item-a> [<item-b>]$cmdhelp$, false, $cmdhelp$Compare two carried/worn items by weight, level, and weapon damage.$cmdhelp$, $cmdhelp$Each item is matched by keyword the same way 'wear' matches. Both items must be on you (inventory or equipped). With a single arg, the second item is inferred from whatever you're currently wearing in that item's wearable slot — handy for the "should I switch?" decision. Prints weight + level deltas, plus a weapon-damage row when both sides have non-zero average damage.$cmdhelp$),
    ($cmdhelp$conceal$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Magical concealment — improved hiding.$cmdhelp$, $cmdhelp$conceal$cmdhelp$, false, $cmdhelp$Magical concealment — improved hiding.$cmdhelp$, $cmdhelp$Drains 4 stamina and dispatches the CONCEAL skill via the data path. Spawns a 'hidden' status effect and installs the Stealth marker, which earns the opening-strike bonus. It does not raise your hiding: use 'hide' for that.$cmdhelp$),
    ($cmdhelp$concentrate$cmdhelp$, ARRAY[]::text[], 'MAGIC'::"CommandCategory", $cmdhelp$Concentrate deeply to speed up spell memorization.$cmdhelp$, $cmdhelp$concentrate$cmdhelp$, false, $cmdhelp$Concentrate deeply to speed up spell memorization.$cmdhelp$, $cmdhelp$Like 'meditate', but also grants a temporary Focus bonus (Intelligence / 4, at least 1) while it lasts. You sit down if standing. Cannot be used while fighting. Re-running 'concentrate' (or standing, or being drawn into combat) breaks your concentration.$cmdhelp$),
    ($cmdhelp$consent$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Toggle consent for group/share interactions.$cmdhelp$, $cmdhelp$consent$cmdhelp$, false, $cmdhelp$Toggle consent for group/share interactions.$cmdhelp$, $cmdhelp$Sets CONSENT. Group invites and certain shared-effect spells will check this flag once those systems land.$cmdhelp$),
    ($cmdhelp$consider$cmdhelp$, ARRAY[$cmdhelp$con$cmdhelp$]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Size up a potential opponent.$cmdhelp$, $cmdhelp$consider <target>$cmdhelp$, false, $cmdhelp$Size up a potential opponent.$cmdhelp$, $cmdhelp$Sizes up the target — compares their HP, accuracy, evasion, and attack power against yours and reports a rough difficulty band. Doesn't engage the target; purely informational.$cmdhelp$),
    ($cmdhelp$cooldowns$cmdhelp$, ARRAY[$cmdhelp$cd$cmdhelp$]::text[], 'MAGIC'::"CommandCategory", $cmdhelp$List abilities currently on cooldown.$cmdhelp$, $cmdhelp$cooldowns$cmdhelp$, false, $cmdhelp$List abilities currently on cooldown.$cmdhelp$, $cmdhelp$Each line shows an ability name and its remaining cooldown in seconds, sorted longest-first. Empty when nothing is on cooldown.$cmdhelp$),
    ($cmdhelp$corner$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Pin a mob with a hard hit to keep them in melee.$cmdhelp$, $cmdhelp$corner <target>$cmdhelp$, false, $cmdhelp$Pin a mob with a hard hit to keep them in melee.$cmdhelp$, $cmdhelp$Drains 4 stamina and dispatches the CORNER skill at the named target. Effect is a level-scaling physical-damage application like LURE; pin-in-place mechanics aren't modeled in the schema, so v1 is the damage hit and the engage.$cmdhelp$),
    ($cmdhelp$create$cmdhelp$, ARRAY[]::text[], 'MAGIC'::"CommandCategory", $cmdhelp$Gnomes: tinker an item together without a spell.$cmdhelp$, $cmdhelp$create <item>$cmdhelp$, false, $cmdhelp$Gnomes: tinker an item together without a spell.$cmdhelp$, $cmdhelp$The gnomish racial Minor Creation, as its own command: 'create <item>' is 'innate minor creation <item>'. The same one-hour racial cooldown applies. Only races whose innate abilities include Minor Creation can use it.$cmdhelp$),
    ($cmdhelp$credits$cmdhelp$, ARRAY[]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Show contributors and credits.$cmdhelp$, $cmdhelp$credits$cmdhelp$, false, $cmdhelp$Show contributors and credits.$cmdhelp$, $cmdhelp$Acknowledges the project's antecedents.$cmdhelp$),
    ($cmdhelp$csearch$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Find classes by name substring.$cmdhelp$, $cmdhelp$csearch <substring>$cmdhelp$, true, $cmdhelp$Find classes by name substring.$cmdhelp$, $cmdhelp$Builder+. Case-insensitive substring against the class's 'plain_name'. Subclass rows are flagged.$cmdhelp$),
    ($cmdhelp$ctell$cmdhelp$, ARRAY[$cmdhelp$ct$cmdhelp$]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Chat on your clan's private channel.$cmdhelp$, $cmdhelp$ctell <message>$cmdhelp$, false, $cmdhelp$Chat on your clan's private channel.$cmdhelp$, $cmdhelp$Broadcasts to every online clan member sharing your 'clan_id'. Refused for players not in a clan. Each line is rendered with the clan abbreviation prefix so cross-clan staff can tell the channels apart in 'wiznet' cross-traffic.$cmdhelp$),
    ($cmdhelp$date$cmdhelp$, ARRAY[]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Show the real-world server date and the in-game date.$cmdhelp$, $cmdhelp$date$cmdhelp$, false, $cmdhelp$Show the real-world server date and the in-game date.$cmdhelp$, $cmdhelp$Real-world server time (UTC) and the in-game calendar date.$cmdhelp$),
    ($cmdhelp$dc$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Disconnect a player by name.$cmdhelp$, $cmdhelp$dc <player>$cmdhelp$, true, $cmdhelp$Disconnect a player by name.$cmdhelp$, $cmdhelp$Builder+ (level 101+) only. Drops the player's Connection so the network task closes the socket cleanly. The autosave path runs on disconnect, so progress is preserved.$cmdhelp$),
    ($cmdhelp$deaf$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Stop hearing room-wide channels (gossip, shout).$cmdhelp$, $cmdhelp$deaf$cmdhelp$, false, $cmdhelp$Stop hearing room-wide channels (gossip, shout).$cmdhelp$, $cmdhelp$When set, you no longer receive 'gossip' or 'shout' from other players. Run again to hear them.$cmdhelp$),
    ($cmdhelp$decline$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Decline a pending group invite.$cmdhelp$, $cmdhelp$decline$cmdhelp$, false, $cmdhelp$Decline a pending group invite.$cmdhelp$, $cmdhelp$Clears the pending invite without joining. No-op if you have no pending invite.$cmdhelp$),
    ($cmdhelp$delmail$cmdhelp$, ARRAY[]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Delete a mail message by slot.$cmdhelp$, $cmdhelp$delmail <#>$cmdhelp$, false, $cmdhelp$Delete a mail message by slot.$cmdhelp$, $cmdhelp$Hard-deletes the row. Slot number is the '#' from 'mailbox'.$cmdhelp$),
    ($cmdhelp$delpost$cmdhelp$, ARRAY[]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Delete a board message (yours, or any if Builder+).$cmdhelp$, $cmdhelp$delpost <board-alias> <#>$cmdhelp$, false, $cmdhelp$Delete a board message (yours, or any if Builder+).$cmdhelp$, $cmdhelp$Hard-deletes the row at the given slot. Players can only delete posts they made (case-insensitive poster-name match); Builder-and-above can delete anyone's. Edit history ('BoardMessageEdit') cascades.$cmdhelp$),
    ($cmdhelp$deposit$cmdhelp$, ARRAY[$cmdhelp$dep$cmdhelp$]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Move coin into the bank.$cmdhelp$, $cmdhelp$deposit <amount> [copper|silver|gold|platinum] | deposit all$cmdhelp$, false, $cmdhelp$Move coin into the bank.$cmdhelp$, $cmdhelp$A bare number is copper ('deposit 100' is 100 copper); add a unit for more ('deposit 5 gold'), or say 'all'. Refuses if you don't have that much on hand. v1 is location-agnostic; banker-mob gating arrives once 'MobProfession::Banker' is hydrated.$cmdhelp$),
    ($cmdhelp$description$cmdhelp$, ARRAY[$cmdhelp$desc$cmdhelp$]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Show or set the prose 'examine' shows for you.$cmdhelp$, $cmdhelp$description [<new prose> | clear]$cmdhelp$, false, $cmdhelp$Show or set the prose 'examine' shows for you.$cmdhelp$, $cmdhelp$With no argument, prints your current description. With new text, replaces it (max 500 chars). With 'clear' / 'none' / '-', removes it. XML-Lite color tags render the same as room descriptions. Persists on disconnect.$cmdhelp$),
    ($cmdhelp$detach$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Remove a trigger from a live mob, object or room.$cmdhelp$, $cmdhelp$detach [ mob | object ] { target } { trigger | all }  |  detach room { trigger | all }$cmdhelp$, true, $cmdhelp$Remove a trigger from a live mob, object or room.$cmdhelp$, $cmdhelp$Implementor only. The trigger is 'zone:id', its place in the list (1 is the first), or a word of its name ('2.beggar' for the second match). 'all' removes every trigger. 'detach <target> <trigger>' finds the target itself, preferring what you wear or carry. Live only; nothing is saved.$cmdhelp$),
    ($cmdhelp$devmode$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Toggle server-wide dev mode (open playtest).$cmdhelp$, $cmdhelp$devmode [on|off]$cmdhelp$, true, $cmdhelp$Toggle server-wide dev mode (open playtest).$cmdhelp$, $cmdhelp$Implementor-only. With no argument, prints current state. With 'on' or 'off', flips the server-wide ''DevMode'' resource AND persists the new state to the ''GameConfig'' row ''server.dev_mode'' so it survives restarts. When ON, every connected player is treated as Implementor for permission checks AND dice rolls are visible regardless of the per-player SHOW_DICE_ROLLS flag. NEVER leave this on in prod. Each toggle logs a loud syslog warning.$cmdhelp$),
    ($cmdhelp$diagnose$cmdhelp$, ARRAY[$cmdhelp$diag$cmdhelp$]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Verbose health readout for self or a target in your room.$cmdhelp$, $cmdhelp$diagnose [<target>]$cmdhelp$, false, $cmdhelp$Verbose health readout for self or a target in your room.$cmdhelp$, $cmdhelp$With no arg, reports your own condition band (e.g. 'mortally wounded'), your raw HP / Stamina, and your posture. With a target, reports their condition band and posture only — exact numbers are private. Pair with 'glance' for a one-line summary or 'score' for the full sheet.$cmdhelp$),
    ($cmdhelp$dice$cmdhelp$, ARRAY[$cmdhelp$showdicerolls$cmdhelp$]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Toggle showing per-swing dice rolls in combat.$cmdhelp$, $cmdhelp$dice$cmdhelp$, false, $cmdhelp$Toggle showing per-swing dice rolls in combat.$cmdhelp$, $cmdhelp$Sets SHOW_DICE_ROLLS. Combat output surfaces hit/dmg rolls when the flag is set.$cmdhelp$),
    ($cmdhelp$disarm$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Knock your opponent's weapon to the ground.$cmdhelp$, $cmdhelp$disarm [<target>]$cmdhelp$, false, $cmdhelp$Knock your opponent's weapon to the ground.$cmdhelp$, $cmdhelp$Removes the target's wielded item; the weapon drops to the floor where any combatant can pick it up. Default target is your current Fighting target. Costs 5 stamina. Refused if the target isn't wielding anything.$cmdhelp$),
    ($cmdhelp$disband$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Dismiss your group and everyone following you.$cmdhelp$, $cmdhelp$disband$cmdhelp$, false, $cmdhelp$Dismiss your group and everyone following you.$cmdhelp$, $cmdhelp$Breaks your group apart and drops everyone directly following you.$cmdhelp$),
    ($cmdhelp$discord$cmdhelp$, ARRAY[$cmdhelp$discord_link$cmdhelp$, $cmdhelp$discordlink$cmdhelp$]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Bind a Discord account to this user.$cmdhelp$, $cmdhelp$discord link <discord-id>  |  discord unlink$cmdhelp$, false, $cmdhelp$Bind a Discord account to this user.$cmdhelp$, $cmdhelp$Two-step verification: 'discord link <id>' mints a one-time code; you then echo '/verify <code>' into the configured gossip channel within 10 minutes. 'discord unlink' clears the binding immediately. 'account' shows the current state.$cmdhelp$),
    ($cmdhelp$disengage$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Stop fighting your current target.$cmdhelp$, $cmdhelp$disengage$cmdhelp$, false, $cmdhelp$Stop fighting your current target.$cmdhelp$, $cmdhelp$Removes your Fighting state — you stop swinging. Opponents may keep attacking until they auto-disengage or you leave the room.$cmdhelp$),
    ($cmdhelp$dismiss$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Drop a single direct follower from your group.$cmdhelp$, $cmdhelp$dismiss <player>$cmdhelp$, false, $cmdhelp$Drop a single direct follower from your group.$cmdhelp$, $cmdhelp$Equivalent to 'group dismiss <player>' — removes the target from your group and ends their follow link to you. 'disband' clears everyone at once.$cmdhelp$),
    ($cmdhelp$dismount$cmdhelp$, ARRAY[]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Get off your current mount.$cmdhelp$, $cmdhelp$dismount$cmdhelp$, false, $cmdhelp$Get off your current mount.$cmdhelp$, $cmdhelp$Clears the 'Mounted' link on you and the 'RiddenBy' link on the mount. No-op when not mounted.$cmdhelp$),
    ($cmdhelp$donate$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Charitably leave an item for someone else.$cmdhelp$, $cmdhelp$donate <item>$cmdhelp$, false, $cmdhelp$Charitably leave an item for someone else.$cmdhelp$, $cmdhelp$Drops the item in the current room with a giving message. A real donation-room flag lands later — for now, donated items sit on the floor.$cmdhelp$),
    ($cmdhelp$doorbash$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Force-open a closed or locked door.$cmdhelp$, $cmdhelp$doorbash <direction>$cmdhelp$, false, $cmdhelp$Force-open a closed or locked door.$cmdhelp$, $cmdhelp$Costs 10 stamina. Flips closed/locked exits to Open on both sides — useful when you don't have the key. Refused on already-open exits and when no exit exists in the named direction.$cmdhelp$),
    ($cmdhelp$down$cmdhelp$, ARRAY[$cmdhelp$d$cmdhelp$]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Walk through an exit.$cmdhelp$, $cmdhelp$<direction>$cmdhelp$, false, $cmdhelp$Walk through an exit.$cmdhelp$, $cmdhelp$Moves you through the named exit if one is open. Standard directions: n/s/e/w/u/d/ne/nw/se/sw/in/out.$cmdhelp$),
    ($cmdhelp$drag$cmdhelp$, ARRAY[]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Drag a corpse, object or consenting body with you.$cmdhelp$, $cmdhelp$drag <target> <direction>$cmdhelp$, false, $cmdhelp$Drag a corpse, object or consenting body with you.$cmdhelp$, $cmdhelp$Takes the target (an object or corpse in the room, or a sitting/resting player who has used 'consent') along when you walk in the given direction. You must be standing. Anything you could pick up (or any corpse) can be dragged, up to three times what you can carry, and heavy loads cost extra stamina. Only staff can drag mobs. Player corpses are only draggable by their owner.$cmdhelp$),
    ($cmdhelp$drink$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Take a swig from a drink container.$cmdhelp$, $cmdhelp$drink <container>$cmdhelp$, false, $cmdhelp$Take a swig from a drink container.$cmdhelp$, $cmdhelp$Decrements the container's 'remaining' liquid by 4 units. Empty containers refuse. Use 'quaff' for potions, 'sip' for a smaller swig (1 unit), 'taste' to identify the liquid without drinking.$cmdhelp$),
    ($cmdhelp$drop$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Drop an item from your inventory onto the floor.$cmdhelp$, $cmdhelp$drop <item>$cmdhelp$, false, $cmdhelp$Drop an item from your inventory onto the floor.$cmdhelp$, $cmdhelp$Match is by case-insensitive substring on keywords. The item is left in the current room; bystanders see you drop it.$cmdhelp$),
    ($cmdhelp$dtrig$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Debug triggers: list, inspect with errors, or fire.$cmdhelp$, $cmdhelp$dtrig <list|info|fire> <args>$cmdhelp$, true, $cmdhelp$Debug triggers: list, inspect with errors, or fire.$cmdhelp$, $cmdhelp$Builder+.
  dtrig list <target>       - triggers attached to a mob/object
  dtrig info <zone:id>      - details, fire stats and recent errors
  dtrig fire <target> <id>  - run a trigger body with <target> as self
Trigger ids are 'zone:id' or a bare id in your current zone.$cmdhelp$),
    ($cmdhelp$dumpworld$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Snapshot the entire entity store as JSON.$cmdhelp$, $cmdhelp$dumpworld [path]$cmdhelp$, true, $cmdhelp$Snapshot the entire entity store as JSON.$cmdhelp$, $cmdhelp$Implementor-only. Useful for offline analysis. Path defaults to /tmp/world-dump-<ts>.json.$cmdhelp$),
    ($cmdhelp$east$cmdhelp$, ARRAY[$cmdhelp$e$cmdhelp$]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Walk through an exit.$cmdhelp$, $cmdhelp$<direction>$cmdhelp$, false, $cmdhelp$Walk through an exit.$cmdhelp$, $cmdhelp$Moves you through the named exit if one is open. Standard directions: n/s/e/w/u/d/ne/nw/se/sw/in/out.$cmdhelp$),
    ($cmdhelp$eat$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Consume a food item from your inventory.$cmdhelp$, $cmdhelp$eat <item>$cmdhelp$, false, $cmdhelp$Consume a food item from your inventory.$cmdhelp$, $cmdhelp$Despawns the food. Refused on non-food items. Effects (hunger, ConsumableEffects) are deferred.$cmdhelp$),
    ($cmdhelp$echo$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Speak a god-line into your current room.$cmdhelp$, $cmdhelp$echo <message>$cmdhelp$, true, $cmdhelp$Speak a god-line into your current room.$cmdhelp$, $cmdhelp$Builder+. Broadcasts the message verbatim (no speaker prefix) to everyone in the caster's room — useful for narrative prompts during live events. For a global broadcast, see 'gecho'.$cmdhelp$),
    ($cmdhelp$editpost$cmdhelp$, ARRAY[]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Re-open a board post for editing.$cmdhelp$, $cmdhelp$editpost <board-alias> <#>$cmdhelp$, false, $cmdhelp$Re-open a board post for editing.$cmdhelp$, $cmdhelp$Pre-loads the existing subject and body into a composition session. Add lines to append, or '.clear' to wipe before writing the new body. Players can only edit their own posts; Builder+ bypasses the gate.$cmdhelp$),
    ($cmdhelp$effects$cmdhelp$, ARRAY[$cmdhelp$affects$cmdhelp$, $cmdhelp$aff$cmdhelp$]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$List active effects on yourself.$cmdhelp$, $cmdhelp$effects$cmdhelp$, false, $cmdhelp$List active effects on yourself.$cmdhelp$, $cmdhelp$Each line shows an effect name and its remaining duration in seconds (or 'permanent' if it has no timer).$cmdhelp$),
    ($cmdhelp$electrify$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Channel lightning into a target.$cmdhelp$, $cmdhelp$electrify <target>$cmdhelp$, false, $cmdhelp$Channel lightning into a target.$cmdhelp$, $cmdhelp$Gated on knowing the Electrify skill (legacy grants it to the eel shapechange form). Electric strike — engages combat. Damage scales with level.$cmdhelp$),
    ($cmdhelp$emote$cmdhelp$, ARRAY[$cmdhelp$:$cmdhelp$]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Perform a third-person action visible to the room.$cmdhelp$, $cmdhelp$emote <action>$cmdhelp$, false, $cmdhelp$Perform a third-person action visible to the room.$cmdhelp$, $cmdhelp$Your name is prepended. 'emote smiles broadly.' shows everyone (including you): 'Strider smiles broadly.'$cmdhelp$),
    ($cmdhelp$emote's$cmdhelp$, ARRAY[]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Perform a possessive third-person action visible to the room.$cmdhelp$, $cmdhelp$emote's <action>$cmdhelp$, false, $cmdhelp$Perform a possessive third-person action visible to the room.$cmdhelp$, $cmdhelp$Your name plus 's is prepended. 'emote's eyes widen.' shows everyone (including you): 'Strider's eyes widen.'$cmdhelp$),
    ($cmdhelp$enter$cmdhelp$, ARRAY[]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Step into a portal in the room.$cmdhelp$, $cmdhelp$enter <portal>$cmdhelp$, false, $cmdhelp$Step into a portal in the room.$cmdhelp$, $cmdhelp$Reads the portal's 'Destination' and teleports you to the matching room. Refused while fighting. Portals with a missing or unresolved destination shimmer harmlessly.$cmdhelp$),
    ($cmdhelp$equipment$cmdhelp$, ARRAY[$cmdhelp$eq$cmdhelp$]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$List items you are wearing/wielding.$cmdhelp$, $cmdhelp$equipment$cmdhelp$, false, $cmdhelp$List items you are wearing/wielding.$cmdhelp$, $cmdhelp$Shows each occupied slot and the item filling it.$cmdhelp$),
    ($cmdhelp$esearch$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Search room exits and doors by keyword, description, key or target.$cmdhelp$, $cmdhelp$esearch <field> <query> [in <zone>]$cmdhelp$, true, $cmdhelp$Search room exits and doors by keyword, description, key or target.$cmdhelp$, $cmdhelp$Builder+. Search one table by a field. Run it with only a type (or 'esearch' / 'tsearch' with nothing) to list the fields. Text fields match a substring; 'name' fields match whole-word prefixes of the name and keywords. Number fields take 5, >5, <5, >=5, <=5, !5 or 5..9 (an inclusive range). Add 'in <zone>' at the end to stay in one zone. Flag fields (wear, extraflags, effflags, flags, type, size, sector, ...) take one or more flag names, abbreviations allowed, and match when every one is present. Output is capped at 100 rows. Shops, zones, reset commands and skills are not searchable here.$cmdhelp$),
    ($cmdhelp$examine$cmdhelp$, ARRAY[$cmdhelp$exam$cmdhelp$, $cmdhelp$exa$cmdhelp$]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Look closely at a person or thing in the room.$cmdhelp$, $cmdhelp$examine <target>$cmdhelp$, false, $cmdhelp$Look closely at a person or thing in the room.$cmdhelp$, $cmdhelp$Match by name or keyword (case-insensitive substring) on anything in your current room — mobs, other players, items, or equipped gear. Shows their long description.$cmdhelp$),
    ($cmdhelp$exchange$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Exchange coins at a money changer (banker).$cmdhelp$, $cmdhelp$exchange <amount> <from-type> <to-type>$cmdhelp$, false, $cmdhelp$Exchange coins at a money changer (banker).$cmdhelp$, $cmdhelp$Converts coins between denominations at a banker. Rates: 10 copper = 1 silver, 10 silver = 1 gold, 10 gold = 1 platinum. Wealth is stored as a single copper total, so the exchange re-expresses your coins rather than changing your net worth; any remainder that doesn't fill a whole target coin is returned as change.$cmdhelp$),
    ($cmdhelp$exits$cmdhelp$, ARRAY[$cmdhelp$ex$cmdhelp$]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$List the exits from your current room.$cmdhelp$, $cmdhelp$exits$cmdhelp$, false, $cmdhelp$List the exits from your current room.$cmdhelp$, $cmdhelp$Shows each direction with the destination room's name. Exits whose target room isn't loaded show as '(beyond)'.$cmdhelp$),
    ($cmdhelp$experience$cmdhelp$, ARRAY[$cmdhelp$exp$cmdhelp$, $cmdhelp$xp$cmdhelp$]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Show your current experience and level.$cmdhelp$, $cmdhelp$experience$cmdhelp$, false, $cmdhelp$Show your current experience and level.$cmdhelp$, $cmdhelp$Prints your level and total experience points. The per-level table that turns this into a 'to next' readout will land with the levelling system.$cmdhelp$),
    ($cmdhelp$extinguish$cmdhelp$, ARRAY[$cmdhelp$douse$cmdhelp$]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Put out a lit torch or lantern.$cmdhelp$, $cmdhelp$extinguish <item>$cmdhelp$, false, $cmdhelp$Put out a lit torch or lantern.$cmdhelp$, $cmdhelp$Puts out a held, worn or carried light source. Refused on items that aren't lit and on permanent lights, which cannot be put out.$cmdhelp$),
    ($cmdhelp$filewatch$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Not applicable: world data is database-backed.$cmdhelp$, $cmdhelp$filewatch [on|off]$cmdhelp$, true, $cmdhelp$Not applicable: world data is database-backed.$cmdhelp$, $cmdhelp$Coder+. The C++ server watched zone files for changes. World data now lives in the database, so there are no files to watch; use 'reloadzone' instead.$cmdhelp$),
    ($cmdhelp$fill$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Top up a container from another container.$cmdhelp$, $cmdhelp$fill <container> <source>$cmdhelp$, false, $cmdhelp$Top up a container from another container.$cmdhelp$, $cmdhelp$Inverse-arg 'pour': same liquid-match rules, transfers up to the destination's remaining capacity.$cmdhelp$),
    ($cmdhelp$firetrig$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Manually fire a trigger by id.$cmdhelp$, $cmdhelp$firetrig <zone> <id> [<actor>]$cmdhelp$, true, $cmdhelp$Manually fire a trigger by id.$cmdhelp$, $cmdhelp$Builder+. Useful for testing trigger bodies. The 'actor' defaults to the caster.$cmdhelp$),
    ($cmdhelp$firstaid$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Quick self/ally heal — wisdom-scaling.$cmdhelp$, $cmdhelp$firstaid [<target>]$cmdhelp$, false, $cmdhelp$Quick self/ally heal — wisdom-scaling.$cmdhelp$, $cmdhelp$Drains 4 stamina and dispatches the FIRST_AID skill via the data path. Heal amount comes from the schema formula 'skill / 4' scaled by wisdom. Defaults to self when no target given. The shim gates 'Fighting' since first aid isn't an in-combat action.$cmdhelp$),
    ($cmdhelp$flags$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$List your active player flags.$cmdhelp$, $cmdhelp$flags$cmdhelp$, false, $cmdhelp$List your active player flags.$cmdhelp$, $cmdhelp$Shows every flag currently set on you. Use 'toggle <flag>' to flip one on or off.$cmdhelp$),
    ($cmdhelp$flee$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Run away from combat through a random open exit.$cmdhelp$, $cmdhelp$flee$cmdhelp$, false, $cmdhelp$Run away from combat through a random open exit.$cmdhelp$, $cmdhelp$Picks an open exit at random and moves you through it. You stop fighting; attackers stop on the next combat tick (they auto-disengage when their target leaves the room).$cmdhelp$),
    ($cmdhelp$fly$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Take to the air (sets the Flying marker).$cmdhelp$, $cmdhelp$fly$cmdhelp$, false, $cmdhelp$Take to the air (sets the Flying marker).$cmdhelp$, $cmdhelp$Needs a source of flight (the fly spell, a winged form or a worn item). Movement charges a flat 2 stamina per move while flying — great savings over water/swamp (4-6 normally), slightly pricier on roads (1). Air rooms have no floor: anyone who is not flying falls through them, and so do loose items and corpses. Use 'land' (or 'walk') to come back down.$cmdhelp$),
    ($cmdhelp$follow$cmdhelp$, ARRAY[$cmdhelp$shadow$cmdhelp$, $cmdhelp$fol$cmdhelp$]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Trail another character automatically.$cmdhelp$, $cmdhelp$follow <name>$cmdhelp$, false, $cmdhelp$Trail another character automatically.$cmdhelp$, $cmdhelp$When the target moves, you move with them through the same exit. 'follow self' (or 'unfollow') stops following. Cycles are silently broken — you can't follow someone who is already following you.$cmdhelp$),
    ($cmdhelp$followers$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$List everyone following you.$cmdhelp$, $cmdhelp$followers$cmdhelp$, false, $cmdhelp$List everyone following you.$cmdhelp$, $cmdhelp$Shows the players and creatures currently following you, where each one is, and how healthy it looks. 'pets' narrows the list to creatures.$cmdhelp$),
    ($cmdhelp$force$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Make a player run a command as themselves.$cmdhelp$, $cmdhelp$force <player> <command>$cmdhelp$, true, $cmdhelp$Make a player run a command as themselves.$cmdhelp$, $cmdhelp$Builder+ (level 101+) only. Dispatches <command> with <player> as the actor — exactly as if they had typed it.$cmdhelp$),
    ($cmdhelp$forget$cmdhelp$, ARRAY[]::text[], 'MAGIC'::"CommandCategory", $cmdhelp$(legacy alias) Slots aren't pre-prepared — see 'slots'.$cmdhelp$, $cmdhelp$forget$cmdhelp$, false, $cmdhelp$(legacy alias) Slots aren't pre-prepared — see 'slots'.$cmdhelp$, $cmdhelp$There's no prepared-spell list to forget from. Spell slots are a circle-pool you draw from when casting; a slot you've spent regenerates on its own under resting / sleeping / meditating postures. Redirects to 'slots'.$cmdhelp$),
    ($cmdhelp$freeze$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Toggle a player's frozen state.$cmdhelp$, $cmdhelp$freeze <player>$cmdhelp$, true, $cmdhelp$Toggle a player's frozen state.$cmdhelp$, $cmdhelp$Builder+ (level 101+) only. Frozen players can't input commands.$cmdhelp$),
    ($cmdhelp$game$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$List or flip server-wide rule toggles.$cmdhelp$, $cmdhelp$game [<toggle> [on|off]]$cmdhelp$, true, $cmdhelp$List or flip server-wide rule toggles.$cmdhelp$, $cmdhelp$Without args, prints every toggle the caller is allowed to see along with its current state. With a toggle name, prints just that toggle's state; add 'on' / 'off' to flip it. Implementor-only flips like ''devmode'' upsert the matching ''GameConfig'' row so the choice survives a restart.
Known toggles: devmode, pk, summon, charm, sleep, roomeffect, names, ooc.$cmdhelp$),
    ($cmdhelp$gecho$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Speak a god-line to every online player.$cmdhelp$, $cmdhelp$gecho <message>$cmdhelp$, true, $cmdhelp$Speak a god-line to every online player.$cmdhelp$, $cmdhelp$Builder+. Bypasses Deaf / IgnoreList — gechoes are out-of-character announcements that should always reach the audience.$cmdhelp$),
    ($cmdhelp$get$cmdhelp$, ARRAY[$cmdhelp$take$cmdhelp$, $cmdhelp$g$cmdhelp$]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Pick up an item from the room or a container.$cmdhelp$, $cmdhelp$get <item> | get <item> from <container>$cmdhelp$, false, $cmdhelp$Pick up an item from the room or a container.$cmdhelp$, $cmdhelp$Match is by case-insensitive substring on the item's keywords (or its name). With 'from <container>', pulls from a container the player is carrying or one in the room. The item moves into your inventory; everyone else in the room sees the action.$cmdhelp$),
    ($cmdhelp$give$cmdhelp$, ARRAY[$cmdhelp$gi$cmdhelp$]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Hand an item to another character in the room.$cmdhelp$, $cmdhelp$give <item> <target>$cmdhelp$, false, $cmdhelp$Hand an item to another character in the room.$cmdhelp$, $cmdhelp$Both you and the target must be in the same room. The item must be in your inventory (not equipped — 'remove' first if needed).$cmdhelp$),
    ($cmdhelp$glance$cmdhelp$, ARRAY[]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$One-line condition check on someone in your room.$cmdhelp$, $cmdhelp$glance <target>$cmdhelp$, false, $cmdhelp$One-line condition check on someone in your room.$cmdhelp$, $cmdhelp$Tells you the target's name, posture, condition (e.g. 'bleeding'), and whether they're fighting. Faster than 'examine' for a quick teammate / enemy check.$cmdhelp$),
    ($cmdhelp$gossip$cmdhelp$, ARRAY[$cmdhelp$.$cmdhelp$]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Talk on the global gossip channel.$cmdhelp$, $cmdhelp$gossip <message>$cmdhelp$, false, $cmdhelp$Talk on the global gossip channel.$cmdhelp$, $cmdhelp$Visible to every online player who hasn't toggled their 'deaf' flag and isn't ignoring you. The dot alias ('.') lets seasoned players stack gossips without arrowing back to type the verb. A lone '.send', '.abort', '.preview' or '.clear' is a mail-editor word, not a gossip; use 'gossip <word>' to say one of them on the channel.$cmdhelp$),
    ($cmdhelp$goto$cmdhelp$, ARRAY[$cmdhelp$go$cmdhelp$]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Teleport to a room by id, or to a player/mob by name.$cmdhelp$, $cmdhelp$goto <target>$cmdhelp$, true, $cmdhelp$Teleport to a room by id, or to a player/mob by name.$cmdhelp$, $cmdhelp$Builder+ command. Three forms:

  goto <id>             — room <id> in your current zone
  goto <zone> <id>      — composite (zone, id)
  goto <name>           — teleport to a player or mob's room
  goto home            — your recall (home) room

Bypasses exits, doors, and no-teleport rooms. Rooms restricted to the god ranks stay closed to lower staff. Your 'poofout' / 'poofin' lines are shown to the rooms you leave and arrive in.$cmdhelp$),
    ($cmdhelp$gouge$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Eye gouge — damage plus a temporary blind effect.$cmdhelp$, $cmdhelp$gouge [<target>]$cmdhelp$, false, $cmdhelp$Eye gouge — damage plus a temporary blind effect.$cmdhelp$, $cmdhelp$Costs 7 stamina, deals damage scaled by your skill and blinds the target for one tick (one MUD hour, about 75 seconds), cutting their accuracy. Default target is your current Fighting target. Cure Blind or Heal restores their sight.$cmdhelp$),
    ($cmdhelp$grant$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Let a character use a command above their rank.$cmdhelp$, $cmdhelp$grant <name> [command <command> [level] | list | clear]$cmdhelp$, true, $cmdhelp$Let a character use a command above their rank.$cmdhelp$, $cmdhelp$Coder+. Per-character command access. A grant lets a character use one command above their rank; a revoke takes a command away. Only online players strictly below your level, and only commands you can use yourself. 'grant <name>' lists a character's grants and revokes; 'grant <name> clear' drops the ones at or below your level. A mortal can only be granted commands on the grants.mortal_allowlist config row (empty by default), and never an admin command. Command groups and privilege flags do not exist on this server.$cmdhelp$),
    ($cmdhelp$greport$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Broadcast your hp/stamina to your group.$cmdhelp$, $cmdhelp$greport$cmdhelp$, false, $cmdhelp$Broadcast your hp/stamina to your group.$cmdhelp$, $cmdhelp$Sends a one-line vitals snapshot to every member of your current group regardless of room. Used to coordinate healing / retreat without reading raw 'who' numbers.$cmdhelp$),
    ($cmdhelp$gretreat$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Coordinated group retreat — every group member in your room flees together.$cmdhelp$, $cmdhelp$gretreat$cmdhelp$, false, $cmdhelp$Coordinated group retreat — every group member in your room flees together.$cmdhelp$, $cmdhelp$Picks one open exit at random; every group member in your current room moves through it and drops their Fighting state. Refused if you're not grouped or if the room has no open exits.$cmdhelp$),
    ($cmdhelp$group$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$List your current group.$cmdhelp$, $cmdhelp$group$cmdhelp$, false, $cmdhelp$List your current group.$cmdhelp$, $cmdhelp$Shows the group leader and every member, with HP and same-room indicator. Joining a group takes the leader's 'invite' and your 'accept'; merely following someone does not put you in their group.$cmdhelp$),
    ($cmdhelp$gsay$cmdhelp$, ARRAY[$cmdhelp$gtell$cmdhelp$, $cmdhelp$gt$cmdhelp$]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Speak privately to your group.$cmdhelp$, $cmdhelp$gsay <message>$cmdhelp$, false, $cmdhelp$Speak privately to your group.$cmdhelp$, $cmdhelp$Reaches every member of your current group regardless of room. Players outside the group never see it. Refused when you're not grouped.$cmdhelp$),
    ($cmdhelp$guard$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Stand bodyguard — intercept incoming swings on a target.$cmdhelp$, $cmdhelp$guard <player|off>$cmdhelp$, false, $cmdhelp$Stand bodyguard — intercept incoming swings on a target.$cmdhelp$, $cmdhelp$Sets a 'Guarding' link from you onto the named player; while you're in the same room, attackers targeting them swing at you instead. 'guard off' clears the link. 'guard' with no arg reports the current target.$cmdhelp$),
    ($cmdhelp$help$cmdhelp$, ARRAY[$cmdhelp$h$cmdhelp$]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$List commands or show details on a specific one.$cmdhelp$, $cmdhelp$help [command]$cmdhelp$, false, $cmdhelp$List commands or show details on a specific one.$cmdhelp$, $cmdhelp$With no arguments, shows commands available to you grouped by category. With an argument, shows the usage and details for that command. Admin commands live in 'wizhelp' (Builder+ only). Try 'help newbie' for a starter-pack of practical first goals.$cmdhelp$),
    ($cmdhelp$hgoto$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Teleport into the named player's house foyer.$cmdhelp$, $cmdhelp$hgoto <player>$cmdhelp$, true, $cmdhelp$Teleport into the named player's house foyer.$cmdhelp$, $cmdhelp$Builder+. Looks up the target's PlayerHouse, synthesizes the ECS Room entities for it (if not yet cached in HousingIndex), then warps you to the foyer ('local_index = 0'). Works for offline owners — reads the snapshot straight from the DB. Routed through the async dispatcher; the sync stub only fires on dispatcher misconfig.$cmdhelp$),
    ($cmdhelp$hgrant$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Assign a fresh house to a player.$cmdhelp$, $cmdhelp$hgrant <player>$cmdhelp$, true, $cmdhelp$Assign a fresh house to a player.$cmdhelp$, $cmdhelp$Builder+. Creates a 'PlayerHouse' row for the named character with the entrance set to the room you're currently standing in. Seeds one foyer room ('local_index = 0'). Fails if the character already owns a house — use 'hrevoke' first.$cmdhelp$),
    ($cmdhelp$hide$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Slip into the shadows.$cmdhelp$, $cmdhelp$hide$cmdhelp$, false, $cmdhelp$Slip into the shadows.$cmdhelp$, $cmdhelp$Rolls how well you hide from your hide skill, Dexterity and Intelligence (rogues and DEX help most). Anyone whose perception is below that number cannot see you until you act: any command but looking around, hiding, moving and the like gives you away, as does attacking or being found by 'search'. Walking wears the hiding down; 'sneak' slows that. Hiding leaves you busy for a combat round (half for thieves). Your group always sees you.$cmdhelp$),
    ($cmdhelp$hinfo$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Inspect any player's house from anywhere.$cmdhelp$, $cmdhelp$hinfo <player>$cmdhelp$, true, $cmdhelp$Inspect any player's house from anywhere.$cmdhelp$, $cmdhelp$Builder+. Loads the named player's PlayerHouse row plus rooms / item count / guest list and prints the summary. Doesn't require the target to be online.$cmdhelp$),
    ($cmdhelp$hire$cmdhelp$, ARRAY[]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Hire a pet from a pet-shop keeper.$cmdhelp$, $cmdhelp$hire <#|name>$cmdhelp$, false, $cmdhelp$Hire a pet from a pet-shop keeper.$cmdhelp$, $cmdhelp$Spawns a fresh mob as your follower. Coin from 'wealth'. Pet is renamed to '<you>'s <mob>' so it doesn't blend with wild mobs of the same kind.$cmdhelp$),
    ($cmdhelp$hitall$cmdhelp$, ARRAY[$cmdhelp$tantrum$cmdhelp$]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$One swing at every hostile mob in your room.$cmdhelp$, $cmdhelp$hitall$cmdhelp$, false, $cmdhelp$One swing at every hostile mob in your room.$cmdhelp$, $cmdhelp$Costs 10 stamina. Damages each Mob in the room for half your damage. Mobs with no Health (test dummy) are skipped. The first surviving mob becomes your Fighting target if you weren't already fighting. Players are never targeted.$cmdhelp$),
    ($cmdhelp$hold$cmdhelp$, ARRAY[$cmdhelp$grab$cmdhelp$]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Hold a non-weapon item in your offhand.$cmdhelp$, $cmdhelp$hold <item>$cmdhelp$, false, $cmdhelp$Hold a non-weapon item in your offhand.$cmdhelp$, $cmdhelp$Equips an item in the Hold slot (lights, instruments, wands). Refused on items that don't go in Hold.$cmdhelp$),
    ($cmdhelp$holylight$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Toggle holy-light vision (admin/builder).$cmdhelp$, $cmdhelp$holylight$cmdhelp$, true, $cmdhelp$Toggle holy-light vision (admin/builder).$cmdhelp$, $cmdhelp$Sets HOLY_LIGHT. Renderer plumbing for invisibility and darkness is pending; the flag persists so it's live the moment those land.$cmdhelp$),
    ($cmdhelp$house$cmdhelp$, ARRAY[]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Inspect or enter your player house.$cmdhelp$, $cmdhelp$house [info|enter|guests|rooms]$cmdhelp$, false, $cmdhelp$Inspect or enter your player house.$cmdhelp$, $cmdhelp$Players who own a house can inspect its layout, guest list, room contents, or step inside via 'house enter'. 'house' (no arg) defaults to the info subcommand. Players without a house get a polite refusal — house creation isn't yet wired through the runtime.$cmdhelp$),
    ($cmdhelp$hrevoke$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Delete a player's house and all its rooms / items.$cmdhelp$, $cmdhelp$hrevoke <player>$cmdhelp$, true, $cmdhelp$Delete a player's house and all its rooms / items.$cmdhelp$, $cmdhelp$Implementor-only. Deletes the named character's PlayerHouse row; FK cascades remove all rooms, exits, placed items, and guest entries. The owner's in-memory 'HouseSummary' component remains until they reconnect — bounce them if they're online.$cmdhelp$),
    ($cmdhelp$idea$cmdhelp$, ARRAY[]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Suggest a feature / change to the staff.$cmdhelp$, $cmdhelp$idea <message>$cmdhelp$, false, $cmdhelp$Suggest a feature / change to the staff.$cmdhelp$, $cmdhelp$Same as 'bug' but tagged Idea. Same 'Reports' row shape; 'report list <kind>' filters.$cmdhelp$),
    ($cmdhelp$identify$cmdhelp$, ARRAY[$cmdhelp$id$cmdhelp$]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Magical analysis of a carried item.$cmdhelp$, $cmdhelp$identify <item>$cmdhelp$, false, $cmdhelp$Magical analysis of a carried item.$cmdhelp$, $cmdhelp$Reveals the item's type, weight, base value, wear slots, weapon dice (when applicable), bound abilities (scrolls/wands/staves), liquid state (drink containers), remaining charges, and any active effects on the item.$cmdhelp$),
    ($cmdhelp$idle$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Show online players sorted by idle time, longest first.$cmdhelp$, $cmdhelp$idle [<min-minutes>]$cmdhelp$, false, $cmdhelp$Show online players sorted by idle time, longest first.$cmdhelp$, $cmdhelp$Same population as 'who', but ordered by how long since each player last typed something. Players who just connected and haven't typed yet show as 'fresh'; anyone under a minute shows as 'active'. With a numeric arg, filters to players idle that many minutes or more — handy for spotting AFK staff or stuck sessions.$cmdhelp$),
    ($cmdhelp$iedit$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Edit one item instance online (Builder+).$cmdhelp$, $cmdhelp$iedit <item> [name|examine|keywords|charges <value|clear>]$cmdhelp$, true, $cmdhelp$Edit one item instance online (Builder+).$cmdhelp$, $cmdhelp$Edits the specific item you carry, wear or see in the room; the prototype is untouched. 'iedit <item>' shows the editable fields. 'iedit <item> name <text>' sets the short description, 'examine <text>' the examine text, 'keywords <w1 w2 ...>' the keyword list, 'charges <n>' (-1 = unlimited). 'clear' on name/examine/keywords restores the prototype's. Colour tags are allowed. Changes apply at once and save with the holder.$cmdhelp$),
    ($cmdhelp$ignore$cmdhelp$, ARRAY[]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Block tells / channel msgs from a player.$cmdhelp$, $cmdhelp$ignore [<name> | -<name> | clear]$cmdhelp$, false, $cmdhelp$Block tells / channel msgs from a player.$cmdhelp$, $cmdhelp$No arg: list current entries. '<name>': add. '-<name>': remove. 'clear': drop the whole list. Per-session today; persistence is a follow-up.$cmdhelp$),
    ($cmdhelp$in$cmdhelp$, ARRAY[]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Walk through an exit.$cmdhelp$, $cmdhelp$<direction>$cmdhelp$, false, $cmdhelp$Walk through an exit.$cmdhelp$, $cmdhelp$Moves you through the named exit if one is open. Standard directions: n/s/e/w/u/d/ne/nw/se/sw/in/out.$cmdhelp$),
    ($cmdhelp$inctime$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Force-advance the in-game clock.$cmdhelp$, $cmdhelp$inctime <hours>$cmdhelp$, true, $cmdhelp$Force-advance the in-game clock.$cmdhelp$, $cmdhelp$Coder+ (level 104+) only. Adds <hours> to 'MudClock.hour' modulo 24 — useful for testing day/night triggers and dawn/dusk weather transitions without waiting for real time.$cmdhelp$),
    ($cmdhelp$innate$cmdhelp$, ARRAY[]::text[], 'MAGIC'::"CommandCategory", $cmdhelp$List or use your race's innate abilities.$cmdhelp$, $cmdhelp$innate [<ability> [target]]$cmdhelp$, false, $cmdhelp$List or use your race's innate abilities.$cmdhelp$, $cmdhelp$Without arguments, reads the 'RaceAbilities' rows for your character's race and prints each ability's name, category (PRIMARY / SECONDARY / ...), starting bonus, and proficiency cap. 'innate <ability> [target]' uses one of the active ones, exactly as if you had typed its own command (cast, breathe, ...); only abilities your race grants can be used this way.$cmdhelp$),
    ($cmdhelp$inspect$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Pay a shopkeeper to identify a wares item or pet.$cmdhelp$, $cmdhelp$inspect [<#|item|pet>]$cmdhelp$, false, $cmdhelp$Pay a shopkeeper to identify a wares item or pet.$cmdhelp$, $cmdhelp$Legacy shop service. With no argument, lists the keeper's wares with their inspection fee (a tenth of the purchase price, minimum one copper). With an item number or name, pays the fee and shows that item's full stat block without buying it; a pet number or name shows the pet's stats. Staff inspect for free.$cmdhelp$),
    ($cmdhelp$insult$cmdhelp$, ARRAY[]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Hurl a random insult at someone in the room.$cmdhelp$, $cmdhelp$insult <target>$cmdhelp$, false, $cmdhelp$Hurl a random insult at someone in the room.$cmdhelp$, $cmdhelp$Picks a random insult and emits it to you, the target, and the rest of the room. Self-targeting leaves you feeling insulted at yourself.$cmdhelp$),
    ($cmdhelp$inventory$cmdhelp$, ARRAY[$cmdhelp$i$cmdhelp$, $cmdhelp$inv$cmdhelp$]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$List items you are carrying.$cmdhelp$, $cmdhelp$inventory [<filter>]$cmdhelp$, false, $cmdhelp$List items you are carrying.$cmdhelp$, $cmdhelp$Shows everything in your inventory by name. Use 'get' to pick items up and 'drop' to set them down. With a filter arg, only items whose name contains the substring (case-insensitive) are shown — useful for pruning a packed bag down to e.g. just potions.$cmdhelp$),
    ($cmdhelp$invite$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Send a group invite to another player.$cmdhelp$, $cmdhelp$invite <player>$cmdhelp$, false, $cmdhelp$Send a group invite to another player.$cmdhelp$, $cmdhelp$Target gets a pending 'GroupInvite'; they can 'accept' or 'decline'. Invites expire after 5 minutes. Players already following you (in your group) can't be re-invited.$cmdhelp$),
    ($cmdhelp$junk$cmdhelp$, ARRAY[$cmdhelp$trash$cmdhelp$]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Permanently destroy a carried item.$cmdhelp$, $cmdhelp$junk <item>$cmdhelp$, false, $cmdhelp$Permanently destroy a carried item.$cmdhelp$, $cmdhelp$The item is despawned; nothing is dropped on the floor and no coin is awarded. Refuses on equipped gear — 'remove' first.$cmdhelp$),
    ($cmdhelp$kick$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Kick your target, or the one you name (which starts a fight).$cmdhelp$, $cmdhelp$kick [<victim>]$cmdhelp$, false, $cmdhelp$Kick your target, or the one you name (which starts a fight).$cmdhelp$, $cmdhelp$Extra attack outside the normal combat-tick rhythm. Rolls weapon damage scaled by attack_power, then adds +4. With no name it hits your current target; with one it picks that fight.$cmdhelp$),
    ($cmdhelp$kill$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Engage a target in melee combat (staff slay it outright).$cmdhelp$, $cmdhelp$kill <target>$cmdhelp$, false, $cmdhelp$Engage a target in melee combat (staff slay it outright).$cmdhelp$, $cmdhelp$For mortals, identical to attack. Staff characters of level 101 and above (legacy LVL_GOD) slay a non-player target on the spot, with no kill credit, instead of entering combat.$cmdhelp$),
    ($cmdhelp$kneel$cmdhelp$, ARRAY[]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Kneel — lower-profile but still alert.$cmdhelp$, $cmdhelp$kneel$cmdhelp$, false, $cmdhelp$Kneel — lower-profile but still alert.$cmdhelp$, $cmdhelp$Changes your posture to kneeling. Ranks the same as sitting for ability gating, but regenerates like standing — useful for guards, prayer, or showing respect.$cmdhelp$),
    ($cmdhelp$last$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Show last-login info for a character.$cmdhelp$, $cmdhelp$last <player>$cmdhelp$, true, $cmdhelp$Show last-login info for a character.$cmdhelp$, $cmdhelp$Builder+. Looks up the character row by name and prints the last 'last_login' timestamp, level, race / class, and online-now status. Async DB call — output is delivered after the lookup returns.$cmdhelp$),
    ($cmdhelp$lastgossips$cmdhelp$, ARRAY[$cmdhelp$lastgos$cmdhelp$]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Replay recent gossip channel lines.$cmdhelp$, $cmdhelp$lastgossips [<n>]$cmdhelp$, false, $cmdhelp$Replay recent gossip channel lines.$cmdhelp$, $cmdhelp$Shows the last <n> gossip utterances (default 10, capped at 50). In-memory only — clears on server restart, like the legacy ring buffer.$cmdhelp$),
    ($cmdhelp$lastshouts$cmdhelp$, ARRAY[]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Replay recent shout channel lines.$cmdhelp$, $cmdhelp$lastshouts [<n>]$cmdhelp$, false, $cmdhelp$Replay recent shout channel lines.$cmdhelp$, $cmdhelp$Shows the last <n> shouts (default 10, capped at 50).$cmdhelp$),
    ($cmdhelp$lasttells$cmdhelp$, ARRAY[$cmdhelp$lt$cmdhelp$]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Show your bounded recent-tells history.$cmdhelp$, $cmdhelp$lasttells$cmdhelp$, false, $cmdhelp$Show your bounded recent-tells history.$cmdhelp$, $cmdhelp$Reads 'TellLog', hydrated at login from the 'tell_message' table. Each row shows the sender and how long ago the tell arrived.$cmdhelp$),
    ($cmdhelp$layhands$cmdhelp$, ARRAY[$cmdhelp$lay$cmdhelp$]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Holy heal — bigger than bandage, works in combat.$cmdhelp$, $cmdhelp$layhands [<target>]$cmdhelp$, false, $cmdhelp$Holy heal — bigger than bandage, works in combat.$cmdhelp$, $cmdhelp$Heals 30 HP at a cost of 12 stamina. Works while fighting (unlike 'bandage'). Refused on full-HP targets. Default target is yourself.$cmdhelp$),
    ($cmdhelp$leave$cmdhelp$, ARRAY[]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Exit your current vehicle / mount.$cmdhelp$, $cmdhelp$leave$cmdhelp$, false, $cmdhelp$Exit your current vehicle / mount.$cmdhelp$, $cmdhelp$Inverse of 'enter' for vehicles. Today the only in-vehicle state we model is mounted, so 'leave' is a synonym for 'dismount'. When boats / carriages land it'll cover those too.$cmdhelp$),
    ($cmdhelp$level$cmdhelp$, ARRAY[]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Your level and progress toward the next one.$cmdhelp$, $cmdhelp$level$cmdhelp$, false, $cmdhelp$Your level and progress toward the next one.$cmdhelp$, $cmdhelp$Shows your level, a progress bar and how much XP is left to the next level, scaled for your class. At the mortal cap with enough XP to reach level 100 you are marked with your class stars ('**') instead.$cmdhelp$),
    ($cmdhelp$levels$cmdhelp$, ARRAY[]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Show the experience needed for every level.$cmdhelp$, $cmdhelp$levels$cmdhelp$, false, $cmdhelp$Show the experience needed for every level.$cmdhelp$, $cmdhelp$Prints the experience your class needs to reach each level, and marks the level you are on. Use 'level' to see your own progress toward the next one.$cmdhelp$),
    ($cmdhelp$light$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Light a torch or lantern.$cmdhelp$, $cmdhelp$light <item>$cmdhelp$, false, $cmdhelp$Light a torch or lantern.$cmdhelp$, $cmdhelp$Lights a Light-type item you are carrying, holding or wearing. Wearing or holding a light does not light it. Refused on non-light items, items that are already lit, and burnt-out lights. Permanent lights are always lit.$cmdhelp$),
    ($cmdhelp$list$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Show what the shopkeeper here is selling.$cmdhelp$, $cmdhelp$list$cmdhelp$, false, $cmdhelp$Show what the shopkeeper here is selling.$cmdhelp$, $cmdhelp$Looks for a 'Shopkeeper'-tagged mob in your room, then prints the keeper's catalog with prices and stock. 'buy <#|name>' and 'sell <item>' land next.$cmdhelp$),
    ($cmdhelp$load$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Spawn a mob proto into your current room.$cmdhelp$, $cmdhelp$load <zone> <mob-id>$cmdhelp$, true, $cmdhelp$Spawn a mob proto into your current room.$cmdhelp$, $cmdhelp$Builder+. Same as 'summon' for count=1, kept as a separate verb for muscle-memory.$cmdhelp$),
    ($cmdhelp$loadobj$cmdhelp$, ARRAY[$cmdhelp$loado$cmdhelp$]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Spawn an object proto onto the floor.$cmdhelp$, $cmdhelp$loadobj <zone> <obj-id>$cmdhelp$, true, $cmdhelp$Spawn an object proto onto the floor.$cmdhelp$, $cmdhelp$Builder+. Materializes one instance of (zone, id) from 'ObjectPrototypes' Located on your current room.$cmdhelp$),
    ($cmdhelp$lock$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Lock a closed door using a key in your inventory.$cmdhelp$, $cmdhelp$lock <direction>$cmdhelp$, false, $cmdhelp$Lock a closed door using a key in your inventory.$cmdhelp$, $cmdhelp$Mirror of 'unlock': requires the exit to be closed (not already locked, not open) and to have a key requirement, and that you carry that key. On match, the door is locked.$cmdhelp$),
    ($cmdhelp$look$cmdhelp$, ARRAY[$cmdhelp$l$cmdhelp$]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Look at your surroundings.$cmdhelp$, $cmdhelp$look$cmdhelp$, false, $cmdhelp$Look at your surroundings.$cmdhelp$, $cmdhelp$Shows the current room's name, anyone or anything else present, and the available exits.$cmdhelp$),
    ($cmdhelp$lua$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Run a snippet of Lua code.$cmdhelp$, $cmdhelp$lua <code>$cmdhelp$, true, $cmdhelp$Run a snippet of Lua code.$cmdhelp$, $cmdhelp$Runs 'code' with 'actor' bound to your character. Same Lua API surface as triggers.$cmdhelp$),
    ($cmdhelp$lure$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Bait a mob into engaging you with a stinging hit.$cmdhelp$, $cmdhelp$lure <target>$cmdhelp$, false, $cmdhelp$Bait a mob into engaging you with a stinging hit.$cmdhelp$, $cmdhelp$Drains 4 stamina and dispatches the LURE skill at the named target. Effect is a level-scaling physical-damage application; combat starts via the normal damage→engage path. Same arg-resolution as 'backstab'.$cmdhelp$),
    ($cmdhelp$mail$cmdhelp$, ARRAY[]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Open a mail composition session to one player.$cmdhelp$, $cmdhelp$mail <character>$cmdhelp$, false, $cmdhelp$Open a mail composition session to one player.$cmdhelp$, $cmdhelp$Opens a multi-line composition session: first non-blank line is the subject, subsequent lines accumulate as body. Control verbs: '.send' ships the draft, '.abort' discards it, '.preview' shows what's queued, '.clear' wipes the draft.$cmdhelp$),
    ($cmdhelp$mailbox$cmdhelp$, ARRAY[$cmdhelp$check$cmdhelp$]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$List inbound mail in your account inbox.$cmdhelp$, $cmdhelp$mailbox$cmdhelp$, false, $cmdhelp$List inbound mail in your account inbox.$cmdhelp$, $cmdhelp$Newest first; unread messages have a '*' prefix. Use 'readmail <#>' to read by slot — that also marks the row read.$cmdhelp$),
    ($cmdhelp$meditate$cmdhelp$, ARRAY[$cmdhelp$med$cmdhelp$]::text[], 'MAGIC'::"CommandCategory", $cmdhelp$Focus to speed up spell memorization.$cmdhelp$, $cmdhelp$meditate$cmdhelp$, false, $cmdhelp$Focus to speed up spell memorization.$cmdhelp$, $cmdhelp$Doubles the rate at which 'memorize' slots refill. Requires resting / sitting / kneeling — standing or sleeping breaks focus, as does taking a step or being attacked. Re-running 'meditate' ends the trance.$cmdhelp$),
    ($cmdhelp$memorize$cmdhelp$, ARRAY[$cmdhelp$mem$cmdhelp$, $cmdhelp$pray$cmdhelp$]::text[], 'MAGIC'::"CommandCategory", $cmdhelp$(legacy alias) Show your spell-slot pool.$cmdhelp$, $cmdhelp$memorize$cmdhelp$, false, $cmdhelp$(legacy alias) Show your spell-slot pool.$cmdhelp$, $cmdhelp$FieryMUD uses a slot-pool model, not a Vance-style prepared-spell list. There's nothing to memorize ahead of time: at each level you have a fixed number of slots per circle (see 'slots' for your current capacity), and any spell you've trained ('study <spell>') can be cast while a slot of its circle is free. This command redirects to 'slots'.$cmdhelp$),
    ($cmdhelp$mlist$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$List mob prototypes in a zone or id range.$cmdhelp$, $cmdhelp$mlist [*|<zone> [[from] <id> [to] [<id>]]] [page <n>]$cmdhelp$, true, $cmdhelp$List mob prototypes in a zone or id range.$cmdhelp$, $cmdhelp$Builder+. Lists mob prototypes from the loaded catalog as '[zone:id] name', sorted by (zone, id). With no argument it lists your current zone; '*' lists every zone; '<zone>' lists that zone; '<zone> <first> <last>' (or '<zone>:<first> <zone>:<last>') narrows to an id span, and a missing <last> means 'to the end of the zone'. Long lists are paged 50 rows at a time: add 'page <n>'. Pair with 'mstat <zone> <id>' for a prototype's detail, or 'msearch' to search by name.$cmdhelp$),
    ($cmdhelp$mnum$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Find mob prototypes by keyword (zone:id).$cmdhelp$, $cmdhelp$mnum <keywords> [in <zone>]$cmdhelp$, true, $cmdhelp$Find mob prototypes by keyword (zone:id).$cmdhelp$, $cmdhelp$Builder+. Lists prototypes whose name or keywords start with every word you give, as 'zone:id name', sorted by id and capped at 100 rows. 'vnum' takes a type first (mobiles, objects, rooms, triggers, exits), 'mnum' / 'onum' / 'rnum' / 'tnum' are the same search for one type. Add 'in <zone>' to stay in one zone. Pair with 'vstat', 'rstat' or 'tstat', or jump with 'goto <zone>:<id>'.$cmdhelp$),
    ($cmdhelp$mob-ai$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Plain-English brief of a mob's behavior.$cmdhelp$, $cmdhelp$mob-ai <zone> <id> | <id> | <name>$cmdhelp$, true, $cmdhelp$Plain-English brief of a mob's behavior.$cmdhelp$, $cmdhelp$Builder+. Reads the mob proto and 'TriggerCatalog' attachments, then summarises in plain English: alignment-driven aggression, behaviors (sentinel, wimpy, etc.), and whether the mob is scripted. For the raw fields use 'mstat'; this is the form you want when explaining a mob to a designer.$cmdhelp$),
    ($cmdhelp$mortal$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Toggle playing under mortal rules (immortal only).$cmdhelp$, $cmdhelp$mortal$cmdhelp$, true, $cmdhelp$Toggle playing under mortal rules (immortal only).$cmdhelp$, $cmdhelp$While on, spell slots, gear restrictions, encumbrance, cast wind-up and post-cast lag apply to you as they do to a mortal, and you must actually know what you cast. Your commands and permissions are unchanged. Not saved: a fresh login starts with it off.$cmdhelp$),
    ($cmdhelp$motd$cmdhelp$, ARRAY[]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Show the message-of-the-day.$cmdhelp$, $cmdhelp$motd$cmdhelp$, false, $cmdhelp$Show the message-of-the-day.$cmdhelp$, $cmdhelp$Static welcome text for now — once a GameConfig 'motd' row lands, this will read from there.$cmdhelp$),
    ($cmdhelp$mount$cmdhelp$, ARRAY[]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Climb onto a mountable mob.$cmdhelp$, $cmdhelp$mount <mob>$cmdhelp$, false, $cmdhelp$Climb onto a mountable mob.$cmdhelp$, $cmdhelp$Target must be 'Mountable' (auto-applied to mobs whose keywords contain horse / steed / mount / donkey / mare). When you move, your mount comes with you. Refused on already-mounted you, on already-ridden mounts, or on mobs in combat.$cmdhelp$),
    ($cmdhelp$msearch$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Search mob prototypes by name, flags, level, race, size, ...$cmdhelp$, $cmdhelp$msearch <field> <query> [in <zone>]$cmdhelp$, true, $cmdhelp$Search mob prototypes by name, flags, level, race, size, ...$cmdhelp$, $cmdhelp$Builder+. 'msearch <field> <query> [in <zone>]' searches mob prototypes (legacy 'msearch'; same as 'vsearch mobiles'). Fields: name, short, long, desc, race, gender, role, level, alignment, flags (sentinel, wimpy, shopkeeper, aquatic, ...), effflags (permanent effects), size, lifeforce. Examples: 'msearch flags sentinel wimpy', 'msearch level 30..40 in 12', 'msearch race dragon', 'msearch lifeforce undead'. Numbers take 5, >5, <5, >=5, <=5, !5, 5..9 or the legacy 'gt 5' / 'bt 5 9'. Add 'in <zone>' to stay in one zone; at most 100 rows print.$cmdhelp$),
    ($cmdhelp$mstat$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Dump a mob PROTOTYPE (template, not a live mob).$cmdhelp$, $cmdhelp$mstat <zone> <id> | <id> | <name>$cmdhelp$, true, $cmdhelp$Dump a mob PROTOTYPE (template, not a live mob).$cmdhelp$, $cmdhelp$Builder+. Reads 'MobPrototypes' and prints the proto fields + linked behaviors / professions / abilities / triggers. Three target forms:
  mstat <zone> <id>   composite key
  mstat <id>          id in your current zone
  mstat <name>        substring against proto name

For a LIVE mob's per-instance state, use 'stat <name>' — stat reads every component on a live entity, mstat reads the static catalog row that produced it.$cmdhelp$),
    ($cmdhelp$music$cmdhelp$, ARRAY[]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Sing on the global music channel.$cmdhelp$, $cmdhelp$music <message>$cmdhelp$, false, $cmdhelp$Sing on the global music channel.$cmdhelp$, $cmdhelp$RP-flavored counterpart to 'gossip'. Same Deaf / ignore filtering. Convention: in-character song lyrics or melodic flavor.$cmdhelp$),
    ($cmdhelp$mute$cmdhelp$, ARRAY[$cmdhelp$squelch$cmdhelp$]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Toggle a player's silence on global channels.$cmdhelp$, $cmdhelp$mute <player>$cmdhelp$, true, $cmdhelp$Toggle a player's silence on global channels.$cmdhelp$, $cmdhelp$Builder+. Toggles 'PlayerFlag::Muted' on the target. Muted players can't use gossip / shout / music / clan / quest channels — 'say' and 'tell' are unaffected so they can still play. Re-running 'mute <name>' clears it.$cmdhelp$),
    ($cmdhelp$name_status$cmdhelp$, ARRAY[$cmdhelp$namestatus$cmdhelp$]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Check whether your character name is staff-approved.$cmdhelp$, $cmdhelp$name_status$cmdhelp$, false, $cmdhelp$Check whether your character name is staff-approved.$cmdhelp$, $cmdhelp$Reports the live name-approval gate state. Useful when chat channels refuse and you want to confirm that the gate (not an effect / freeze / ignore-list) is the cause. No-op besides the readout.$cmdhelp$),
    ($cmdhelp$nameitem$cmdhelp$, ARRAY[$cmdhelp$label$cmdhelp$]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Add a label of your own to an item you carry.$cmdhelp$, $cmdhelp$nameitem <item> <label> | nameitem <item> clear$cmdhelp$, false, $cmdhelp$Add a label of your own to an item you carry.$cmdhelp$, $cmdhelp$Labels an item you carry or wear, e.g. 'nameitem sack gems' turns "a cloth sack" into "a cloth sack (labeled 'gems')". The item keeps its own name; the label's words also work for targeting ('get ruby gems'). Labels are 3-40 characters; colour codes and unusual symbols are removed. 'nameitem sack clear' removes the label. Works on any item. Carried items are matched before worn ones.$cmdhelp$),
    ($cmdhelp$newbie$cmdhelp$, ARRAY[$cmdhelp$tutorial$cmdhelp$]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Show a short starter-pack of first goals.$cmdhelp$, $cmdhelp$newbie$cmdhelp$, false, $cmdhelp$Show a short starter-pack of first goals.$cmdhelp$, $cmdhelp$Lists the practical next steps for a new character: get oriented, equip gear, find a trainer, fight a safe mob, and recall back. Re-run any time you forget where you were — it's not state-dependent.$cmdhelp$),
    ($cmdhelp$news$cmdhelp$, ARRAY[]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Recent server news.$cmdhelp$, $cmdhelp$news$cmdhelp$, false, $cmdhelp$Recent server news.$cmdhelp$, $cmdhelp$Static for now; will read from a future news table.$cmdhelp$),
    ($cmdhelp$norepeat$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Don't echo your own say/tell/channel text back.$cmdhelp$, $cmdhelp$norepeat$cmdhelp$, false, $cmdhelp$Don't echo your own say/tell/channel text back.$cmdhelp$, $cmdhelp$Toggles NO_REPEAT. While on, say, tell, reply, whisper, ask, gsay and the global channels answer you with just "Ok." instead of repeating what you typed. Others see your message as usual.$cmdhelp$),
    ($cmdhelp$north$cmdhelp$, ARRAY[$cmdhelp$n$cmdhelp$]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Walk through an exit.$cmdhelp$, $cmdhelp$<direction>$cmdhelp$, false, $cmdhelp$Walk through an exit.$cmdhelp$, $cmdhelp$Moves you through the named exit if one is open. Standard directions: n/s/e/w/u/d/ne/nw/se/sw/in/out.$cmdhelp$),
    ($cmdhelp$northeast$cmdhelp$, ARRAY[$cmdhelp$ne$cmdhelp$]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Walk through an exit.$cmdhelp$, $cmdhelp$<direction>$cmdhelp$, false, $cmdhelp$Walk through an exit.$cmdhelp$, $cmdhelp$Moves you through the named exit if one is open. Standard directions: n/s/e/w/u/d/ne/nw/se/sw/in/out.$cmdhelp$),
    ($cmdhelp$northwest$cmdhelp$, ARRAY[$cmdhelp$nw$cmdhelp$]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Walk through an exit.$cmdhelp$, $cmdhelp$<direction>$cmdhelp$, false, $cmdhelp$Walk through an exit.$cmdhelp$, $cmdhelp$Moves you through the named exit if one is open. Standard directions: n/s/e/w/u/d/ne/nw/se/sw/in/out.$cmdhelp$),
    ($cmdhelp$nosummon$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Silently auto-decline incoming summon spells.$cmdhelp$, $cmdhelp$nosummon$cmdhelp$, false, $cmdhelp$Silently auto-decline incoming summon spells.$cmdhelp$, $cmdhelp$By default, when someone casts SUMMON on you, you get a 30-second 'accept' / 'decline' prompt. Setting NO_SUMMON short-circuits that — incoming summons are silently refused without prompting you, and the caster sees "X is not accepting summons." Use this when you want to AFK without summon-prompt interruptions. Run again to re-enable the prompt. PK-flagged players (see 'pk') bypass the prompt entirely — that's part of opting into PvP.$cmdhelp$),
    ($cmdhelp$notell$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Refuse incoming 'tell' messages.$cmdhelp$, $cmdhelp$notell$cmdhelp$, false, $cmdhelp$Refuse incoming 'tell' messages.$cmdhelp$, $cmdhelp$When set, other players' 'tell' to you is blocked with a message. Run again to allow tells.$cmdhelp$),
    ($cmdhelp$offer$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Ask a receptionist what it costs to store your belongings.$cmdhelp$, $cmdhelp$offer$cmdhelp$, false, $cmdhelp$Ask a receptionist what it costs to store your belongings.$cmdhelp$, $cmdhelp$Speak to a receptionist (or stand in an inn) to hear the terms. Your character and belongings are saved automatically and cost nothing to keep: 'quit' anywhere (or 'rent' at a receptionist) to save and leave. Inns additionally sell prepaid rest tiers; 'offer' lists them, 'rent <name>' books one.$cmdhelp$),
    ($cmdhelp$olist$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$List object prototypes in a zone or id range.$cmdhelp$, $cmdhelp$olist [*|<zone> [[from] <id> [to] [<id>]]] [page <n>]$cmdhelp$, true, $cmdhelp$List object prototypes in a zone or id range.$cmdhelp$, $cmdhelp$Builder+. Lists object prototypes from the loaded catalog as '[zone:id] name', sorted by (zone, id). With no argument it lists your current zone; '*' lists every zone; '<zone>' lists that zone; '<zone> <first> <last>' (or '<zone>:<first> <zone>:<last>') narrows to an id span, and a missing <last> means 'to the end of the zone'. Long lists are paged 50 rows at a time: add 'page <n>'. Pair with 'ostat <zone> <id>' for a prototype's detail, or 'osearch' to search by name.$cmdhelp$),
    ($cmdhelp$onum$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Find object prototypes by keyword (zone:id).$cmdhelp$, $cmdhelp$onum <keywords> [in <zone>]$cmdhelp$, true, $cmdhelp$Find object prototypes by keyword (zone:id).$cmdhelp$, $cmdhelp$Builder+. Lists prototypes whose name or keywords start with every word you give, as 'zone:id name', sorted by id and capped at 100 rows. 'vnum' takes a type first (mobiles, objects, rooms, triggers, exits), 'mnum' / 'onum' / 'rnum' / 'tnum' are the same search for one type. Add 'in <zone>' to stay in one zone. Pair with 'vstat', 'rstat' or 'tstat', or jump with 'goto <zone>:<id>'.$cmdhelp$),
    ($cmdhelp$open$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Open a closed door in the given direction.$cmdhelp$, $cmdhelp$open <direction>$cmdhelp$, false, $cmdhelp$Open a closed door in the given direction.$cmdhelp$, $cmdhelp$Refused if the exit is already open or locked. Locked doors need a key (use 'unlock').$cmdhelp$),
    ($cmdhelp$order$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Issue a command to one or all of your followers.$cmdhelp$, $cmdhelp$order <follower|all> <command>$cmdhelp$, false, $cmdhelp$Issue a command to one or all of your followers.$cmdhelp$, $cmdhelp$Forwards '<command>' to a named mob follower (must be in the same room and have 'Follower(you)' set), or 'all' for every same-room follower at once. The mob runs the command through the normal dispatcher under its own identity, so target lookups, costs, and triggers fire as if it had typed the line. Admin commands are off-limits to mobs.$cmdhelp$),
    ($cmdhelp$osearch$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Search object prototypes by name, type, wear or effect flags, level, ...$cmdhelp$, $cmdhelp$osearch <field> <query> [in <zone>]$cmdhelp$, true, $cmdhelp$Search object prototypes by name, type, wear or effect flags, level, ...$cmdhelp$, $cmdhelp$Builder+. 'osearch <field> <query> [in <zone>]' searches object prototypes (legacy 'osearch'; same as 'vsearch objects'). Fields: name, short, long, desc, type, wear, extraflags (glow, magic, nodrop, ...), effflags (effects the item grants, e.g. sanctuary), level, weight, cost, timer. Examples: 'osearch type weapon', 'osearch wear head neck', 'osearch effflags sanctuary in 30', 'osearch level 20..30', 'osearch cost gt 5000'. Numbers take 5, >5, <5, >=5, <=5, !5, 5..9 or the legacy 'gt 5' / 'bt 5 9'. Add 'in <zone>' to stay in one zone; at most 100 rows print.$cmdhelp$),
    ($cmdhelp$ostat$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Dump an object PROTOTYPE.$cmdhelp$, $cmdhelp$ostat <zone> <id> | <id> | <name>$cmdhelp$, true, $cmdhelp$Dump an object PROTOTYPE.$cmdhelp$, $cmdhelp$Builder+. Mirrors 'mstat' for objects: type, weight, wear flags, locks (!DROP / CURSED!!), armor, stat bonuses, effect flags, special-values per type. 'stat <object>' prints the same block for a live item. Same target forms — composite key, id in current zone, or substring against proto name.$cmdhelp$),
    ($cmdhelp$out$cmdhelp$, ARRAY[$cmdhelp$o$cmdhelp$]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Walk through an exit.$cmdhelp$, $cmdhelp$<direction>$cmdhelp$, false, $cmdhelp$Walk through an exit.$cmdhelp$, $cmdhelp$Moves you through the named exit if one is open. Standard directions: n/s/e/w/u/d/ne/nw/se/sw/in/out.$cmdhelp$),
    ($cmdhelp$page$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Beep a player with a message.$cmdhelp$, $cmdhelp$page <player|all> <message>$cmdhelp$, true, $cmdhelp$Beep a player with a message.$cmdhelp$, $cmdhelp$Builder+. Sends '*<you>* <message>' with two terminal bells to one player anywhere in the game. 'page all' reaches everyone and needs a level above 101.$cmdhelp$),
    ($cmdhelp$pain$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Cosmetic divine wrath flourish on a single player.$cmdhelp$, $cmdhelp$pain <player>$cmdhelp$, true, $cmdhelp$Cosmetic divine wrath flourish on a single player.$cmdhelp$, $cmdhelp$Builder+. Emits a roleplay-flavor pain line — no actual HP / stamina change. The target sees a personalized line; the room sees a third-person broadcast. Use to express divine displeasure during live events.$cmdhelp$),
    ($cmdhelp$palm$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Secretly hide a small item in your hand.$cmdhelp$, $cmdhelp$palm <item>$cmdhelp$, false, $cmdhelp$Secretly hide a small item in your hand.$cmdhelp$, $cmdhelp$Rogue skill. Conceals an item from your inventory from casual detection for a while; others may spot it with perception. Uses the PALM ability's proficiency and effect from the database.$cmdhelp$),
    ($cmdhelp$peace$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Stop all combat in your current room.$cmdhelp$, $cmdhelp$peace$cmdhelp$, true, $cmdhelp$Stop all combat in your current room.$cmdhelp$, $cmdhelp$Builder+. Removes the 'Fighting' component from every entity in your room — useful when a brawl gets out of hand or a Lua trigger spawned a hostile mob you'd rather not pile on. Each disengaged combatant gets a quiet "calm settles over the room" line; a room broadcast confirms the action.$cmdhelp$),
    ($cmdhelp$peck$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Drive your beak into a target (Avariel only).$cmdhelp$, $cmdhelp$peck <target>$cmdhelp$, false, $cmdhelp$Drive your beak into a target (Avariel only).$cmdhelp$, $cmdhelp$Race-gated to Avariel. Piercing strike — engages combat if not already fighting the target. Damage scales with level.$cmdhelp$),
    ($cmdhelp$perform$cmdhelp$, ARRAY[]::text[], 'MAGIC'::"CommandCategory", $cmdhelp$Perform a song from the catalog (bard).$cmdhelp$, $cmdhelp$perform <song> [target]$cmdhelp$, false, $cmdhelp$Perform a song from the catalog (bard).$cmdhelp$, $cmdhelp$Same shape as 'cast' but filters to abilityType = SONG. Stub: prints metadata and gates on KnownAbilities, no effect application yet.$cmdhelp$),
    ($cmdhelp$petition$cmdhelp$, ARRAY[]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Send to immortals — or, as immortal, reply privately.$cmdhelp$, $cmdhelp$petition <message>  |  petition <player> <message>$cmdhelp$, false, $cmdhelp$Send to immortals — or, as immortal, reply privately.$cmdhelp$, $cmdhelp$From a mortal: broadcasts the petition to every online Immortal+. From an immortal: if the first arg matches an online player name, reply to that player privately (the legacy 'ptell' form folded in). Mortals never see anyone else's petitions.$cmdhelp$),
    ($cmdhelp$pets$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$List the creatures following you.$cmdhelp$, $cmdhelp$pets$cmdhelp$, false, $cmdhelp$List the creatures following you.$cmdhelp$, $cmdhelp$Shows your pets, hirelings and charmed creatures, where each one is, and how healthy it looks. Use 'call' to bring them to you.$cmdhelp$),
    ($cmdhelp$pick$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Pick a locked door open with rogue tools.$cmdhelp$, $cmdhelp$pick <direction>$cmdhelp$, false, $cmdhelp$Pick a locked door open with rogue tools.$cmdhelp$, $cmdhelp$Skill check against your 'PICK_LOCK' proficiency. Refuses on unlocked exits, exits without a keyhole, and players who haven't trained pick lock. Costs 5 stamina whether you succeed or fail. On success the door flips Locked → Closed (same as 'unlock'); on failure you get a fumble line.$cmdhelp$),
    ($cmdhelp$pk$cmdhelp$, ARRAY[$cmdhelp$pkill$cmdhelp$]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Toggle player-kill participation.$cmdhelp$, $cmdhelp$pk [on|off]$cmdhelp$, false, $cmdhelp$Toggle player-kill participation.$cmdhelp$, $cmdhelp$Sets PK_ENABLED. Two players can fight each other only while BOTH have PK on. Turning it on works anywhere; you can turn it off only at your recall point, and not while fighting another player.$cmdhelp$),
    ($cmdhelp$play$cmdhelp$, ARRAY[]::text[], 'MAGIC'::"CommandCategory", $cmdhelp$Play an instrument you are holding.$cmdhelp$, $cmdhelp$play <instrument>$cmdhelp$, false, $cmdhelp$Play an instrument you are holding.$cmdhelp$, $cmdhelp$Plays a held instrument; magical instruments invoke their bound abilities and spend a charge when they land.$cmdhelp$),
    ($cmdhelp$pnote$cmdhelp$, ARRAY[$cmdhelp$playernote$cmdhelp$, $cmdhelp$note$cmdhelp$]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Read / append / clear staff notes on a character.$cmdhelp$, $cmdhelp$pnote <player> [<text> | clear]$cmdhelp$, true, $cmdhelp$Read / append / clear staff notes on a character.$cmdhelp$, $cmdhelp$Builder+. Without args after the name, prints the current staff notes. With text, appends a new line prefixed with the timestamp and your character name. 'clear' is Implementor-only and wipes the entire log.$cmdhelp$),
    ($cmdhelp$point$cmdhelp$, ARRAY[]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Point at someone, something, or a direction.$cmdhelp$, $cmdhelp$point <target>$cmdhelp$, false, $cmdhelp$Point at someone, something, or a direction.$cmdhelp$, $cmdhelp$Resolves <target> against (in order): a direction (n/s/e/w/u/d), an actor in your room (player or mob), or an item in your room or inventory. Pointing at a hidden actor reveals them — stealth doesn't survive being singled out.$cmdhelp$),
    ($cmdhelp$policies$cmdhelp$, ARRAY[$cmdhelp$rules$cmdhelp$, $cmdhelp$policy$cmdhelp$]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Server rules and code of conduct.$cmdhelp$, $cmdhelp$policies$cmdhelp$, false, $cmdhelp$Server rules and code of conduct.$cmdhelp$, $cmdhelp$Static for now. Aliases: 'rules', 'policy'.$cmdhelp$),
    ($cmdhelp$poofin$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Set your custom arrival message on goto / teleport.$cmdhelp$, $cmdhelp$poofin [<message>]$cmdhelp$, true, $cmdhelp$Set your custom arrival message on goto / teleport.$cmdhelp$, $cmdhelp$Builder+. Replaces the generic "$n appears with an ear-splitting bang." with your own line ('$n' stands for your name). Bare 'poofin' shows the current value; 'poofin clear' removes it.$cmdhelp$),
    ($cmdhelp$poofout$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Set your custom departure message on goto / teleport.$cmdhelp$, $cmdhelp$poofout [<message>]$cmdhelp$, true, $cmdhelp$Set your custom departure message on goto / teleport.$cmdhelp$, $cmdhelp$Builder+. Mirrors 'poofin'. Replaces the generic "$n disappears in a puff of smoke." departure line.$cmdhelp$),
    ($cmdhelp$post$cmdhelp$, ARRAY[]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Compose a new message on a board.$cmdhelp$, $cmdhelp$post <board-alias>$cmdhelp$, false, $cmdhelp$Compose a new message on a board.$cmdhelp$, $cmdhelp$Opens a multi-line composition session: first non-blank line is the subject, subsequent lines accumulate as body. '.send' ships, '.abort' cancels, '.preview' shows the draft. Locked boards refuse the open.$cmdhelp$),
    ($cmdhelp$pour$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Transfer liquid between containers, or empty.$cmdhelp$, $cmdhelp$pour <container> [target]$cmdhelp$, false, $cmdhelp$Transfer liquid between containers, or empty.$cmdhelp$, $cmdhelp$With no target, dumps the source's liquid on the ground. With a target container, transfers as much as the target can accept; refuses on liquid-type mismatch unless the target is empty (in which case the target adopts the source's liquid + poison flag).$cmdhelp$),
    ($cmdhelp$practice$cmdhelp$, ARRAY[$cmdhelp$prac$cmdhelp$]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$List trained abilities, or improve proficiency.$cmdhelp$, $cmdhelp$practice [<ability>]$cmdhelp$, false, $cmdhelp$List trained abilities, or improve proficiency.$cmdhelp$, $cmdhelp$Without an argument, renders KnownAbilities with proficiency 0-1000 and a tier label. With an ability name, raises that ability's proficiency by 5 (capped at the class's 'proficiency_cap' from 'ClassAbilities'). Persists across reconnect via 'CharacterAbilities'.$cmdhelp$),
    ($cmdhelp$prompt$cmdhelp$, ARRAY[$cmdhelp$display$cmdhelp$]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Show or change your status prompt template.$cmdhelp$, $cmdhelp$prompt [template]$cmdhelp$, false, $cmdhelp$Show or change your status prompt template.$cmdhelp$, $cmdhelp$With no argument, prints your current template. With a template, replaces it. Variables: %h current HP, %H max HP, %v current stamina, %V max stamina, %n your name, %r current room, %g on-hand wealth (copper), %t in-game hour (zero-padded), %s season, %d day/night, %% literal percent. Examples: prompt <%h/%H hp %v/%V st> prompt [%t %h/%H %d] $cmdhelp$),
    ($cmdhelp$pscan$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Scan every persisted character's inventory for an item.$cmdhelp$, $cmdhelp$pscan <substring>$cmdhelp$, true, $cmdhelp$Scan every persisted character's inventory for an item.$cmdhelp$, $cmdhelp$Builder+. Joins 'CharacterItems' × 'Characters' × 'Objects' against an item-name substring and prints one row per (player, item) hit. Async DB query — covers offline characters, not just online ones. Capped at 200 hits server-side.$cmdhelp$),
    ($cmdhelp$ptell$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Answer a player's petition.$cmdhelp$, $cmdhelp$ptell <player> <message>$cmdhelp$, true, $cmdhelp$Answer a player's petition.$cmdhelp$, $cmdhelp$Immortal+. Sends <message> privately to the petitioner and shows the other online immortals who answered whom. Refused for staff targets (use wiznet) and for a player who is writing a message.$cmdhelp$),
    ($cmdhelp$purge$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Despawn the named target — or every non-player in the room.$cmdhelp$, $cmdhelp$purge [target]$cmdhelp$, true, $cmdhelp$Despawn the named target — or every non-player in the room.$cmdhelp$, $cmdhelp$HeadBuilder+ (level 103+) only. With no arg, removes every mob / item in your current room. With a name, despawns that one entity.$cmdhelp$),
    ($cmdhelp$put$cmdhelp$, ARRAY[$cmdhelp$p$cmdhelp$]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Move a carried item into a container.$cmdhelp$, $cmdhelp$put <item> <container>$cmdhelp$, false, $cmdhelp$Move a carried item into a container.$cmdhelp$, $cmdhelp$Container can be a carried item or one in the current room. Equipped items must be 'remove'd first. Bystanders see the action.$cmdhelp$),
    ($cmdhelp$qaccept$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Accept a quest by composite id.$cmdhelp$, $cmdhelp$qaccept <zone> <quest-id>$cmdhelp$, false, $cmdhelp$Accept a quest by composite id.$cmdhelp$, $cmdhelp$Self-service quest acceptance. Validates level range, checks every required prerequisite, and refuses if you already have it in progress (or completed it once already on a non-repeatable quest).$cmdhelp$),
    ($cmdhelp$qcomplete$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Admin: force-complete an in-progress quest (coder+ pays rewards).$cmdhelp$, $cmdhelp$qcomplete <#>$cmdhelp$, true, $cmdhelp$Admin: force-complete an in-progress quest (coder+ pays rewards).$cmdhelp$, $cmdhelp$Slot number from the 'quests' in-progress section. Flips IN_PROGRESS -> COMPLETED, stamps completed_at and bumps completion_count. Coder rank and above also get the quest's unconditional rewards exactly as a real completion pays them (conditional and choice rewards stay behind 'qreward'); lower ranks complete it without rewards. Objectives and phases are not run. Audited.$cmdhelp$),
    ($cmdhelp$qecho$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Admin echo to the quest channel.$cmdhelp$, $cmdhelp$qecho <message>$cmdhelp$, true, $cmdhelp$Admin echo to the quest channel.$cmdhelp$, $cmdhelp$Builder+. Drops a flavor announcement onto the quest channel without quoting the speaker (e.g. "<msg>" rather than "X qsays, '<msg>'"). Useful for run-of-show quest narration.$cmdhelp$),
    ($cmdhelp$qgive$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Admin: assign a quest to another online player.$cmdhelp$, $cmdhelp$qgive <player> <zone> <quest-id>$cmdhelp$, true, $cmdhelp$Admin: assign a quest to another online player.$cmdhelp$, $cmdhelp$Same as 'qload' but targets a named online player instead of the caller. Target must be currently online (offline-character assignment is left for a future iteration).$cmdhelp$),
    ($cmdhelp$qload$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Admin: assign a quest to your character (testing).$cmdhelp$, $cmdhelp$qload <zone> <quest-id>$cmdhelp$, true, $cmdhelp$Admin: assign a quest to your character (testing).$cmdhelp$, $cmdhelp$Inserts a CharacterQuest row with status IN_PROGRESS for the caller's character. No-op if that quest is already assigned to you.$cmdhelp$),
    ($cmdhelp$qreset$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Admin: wipe a player's record of a quest.$cmdhelp$, $cmdhelp$qreset <player> <zone> <quest-id>$cmdhelp$, true, $cmdhelp$Admin: wipe a player's record of a quest.$cmdhelp$, $cmdhelp$Deletes the character's whole record of the quest: status, objective progress and quest variables, so it can be given or accepted from scratch ('qload', 'qgive' and 'qaccept' refuse while any record exists). Builders may reset their own character only; coder rank and above may reset anyone, including offline characters. Rewards already paid are not taken back. 'zone:id' is accepted in place of '<zone> <quest-id>'. Audited.$cmdhelp$),
    ($cmdhelp$qreward$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$List or claim a choice-group reward.$cmdhelp$, $cmdhelp$qreward [<zone> <quest-id> [<reward-id>]]$cmdhelp$, false, $cmdhelp$List or claim a choice-group reward.$cmdhelp$, $cmdhelp$With no arguments, lists every choice-reward group from your completed quests that you haven't claimed yet. With <zone> <quest-id>, lists choices for that quest. With all three args, claims the named reward (id from the listing). One pick per choice_group.$cmdhelp$),
    ($cmdhelp$qsay$cmdhelp$, ARRAY[]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Talk on the quest channel.$cmdhelp$, $cmdhelp$qsay <message>$cmdhelp$, false, $cmdhelp$Talk on the quest channel.$cmdhelp$, $cmdhelp$Visible to every online player not Deaf and not ignoring you. Conventionally used to coordinate quest progress with other questers. Same shape as 'gossip' — separate channel mostly for ear cleanliness.$cmdhelp$),
    ($cmdhelp$quaff$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Drink a potion from your inventory.$cmdhelp$, $cmdhelp$quaff <potion>$cmdhelp$, false, $cmdhelp$Drink a potion from your inventory.$cmdhelp$, $cmdhelp$Despawns the potion. Refused on non-potion items. Effect application (ConsumableEffects) is deferred.$cmdhelp$),
    ($cmdhelp$quest$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Join or leave the Quest event.$cmdhelp$, $cmdhelp$quest [on|off]$cmdhelp$, false, $cmdhelp$Join or leave the Quest event.$cmdhelp$, $cmdhelp$Toggles your QUEST flag, which marks you as taking part in staff-run quest events ('quest on' / 'quest off' set it explicitly). Use 'quests' to see your own quests.$cmdhelp$),
    ($cmdhelp$questinfo$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Show details for a single quest definition.$cmdhelp$, $cmdhelp$questinfo <zone> <id>$cmdhelp$, false, $cmdhelp$Show details for a single quest definition.$cmdhelp$, $cmdhelp$Reads the 'Quest' row for '(zone, id)' and prints name, level range, flags (repeatable / shareable / hidden / auto-accept), short description, and full description.$cmdhelp$),
    ($cmdhelp$quests$cmdhelp$, ARRAY[$cmdhelp$qstat$cmdhelp$, $cmdhelp$qlist$cmdhelp$, $cmdhelp$questlog$cmdhelp$]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$List your accepted quests (staff: or a player's).$cmdhelp$, $cmdhelp$quests [<player>]$cmdhelp$, false, $cmdhelp$List your accepted quests (staff: or a player's).$cmdhelp$, $cmdhelp$In-progress quests appear first with their short description; completed/abandoned quests follow with their final status. Each in-progress quest also shows its phases + objective progress (▶ for current, ✓ for done, [N/M] for showProgress). Immortal+ may add a player's name (online or offline) to see that player's quests, including each quest's stored quest variables. A player hidden from you by wizinvis cannot be looked up.$cmdhelp$),
    ($cmdhelp$quit$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Save your character and leave the game.$cmdhelp$, $cmdhelp$quit$cmdhelp$, false, $cmdhelp$Save your character and leave the game.$cmdhelp$, $cmdhelp$Saves your character, says goodbye and drops the connection. You can't quit while fighting (staff excepted) or while casting. The whole word is required; 'q', 'qu' and 'qui' only remind you of that.$cmdhelp$),
    ($cmdhelp$read$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Read the text on an item (book, sign, scroll).$cmdhelp$, $cmdhelp$read <item>$cmdhelp$, false, $cmdhelp$Read the text on an item (book, sign, scroll).$cmdhelp$, $cmdhelp$Finds an item by keyword on you or in the room and prints its description text. Refuses on mobs and players — use 'examine' for those.$cmdhelp$),
    ($cmdhelp$readmail$cmdhelp$, ARRAY[$cmdhelp$receive$cmdhelp$, $cmdhelp$getmail$cmdhelp$]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Read a single mail message by slot.$cmdhelp$, $cmdhelp$readmail <#>$cmdhelp$, false, $cmdhelp$Read a single mail message by slot.$cmdhelp$, $cmdhelp$Slot number is the '#' from 'mailbox'. Marks the row read on first read; subsequent re-reads are silent.$cmdhelp$),
    ($cmdhelp$recall$cmdhelp$, ARRAY[$cmdhelp$home$cmdhelp$]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Teleport to your recall point.$cmdhelp$, $cmdhelp$recall$cmdhelp$, false, $cmdhelp$Teleport to your recall point.$cmdhelp$, $cmdhelp$Move instantly to your saved recall room. If you haven't bound one yet you go to your race's start room — 'touch <touchstone>' in a sanctuary room to bind your recall there. Builders can use 'setrecall' from any room.$cmdhelp$),
    ($cmdhelp$recite$cmdhelp$, ARRAY[]::text[], 'MAGIC'::"CommandCategory", $cmdhelp$Read a magic scroll, casting its inscribed spells.$cmdhelp$, $cmdhelp$recite <scroll> [<target>]$cmdhelp$, false, $cmdhelp$Read a magic scroll, casting its inscribed spells.$cmdhelp$, $cmdhelp$Looks up the bound abilities via ObjectAbilities and dispatches each through the cast pipeline. Despawns the scroll regardless of outcome (single-use).$cmdhelp$),
    ($cmdhelp$reject_name$cmdhelp$, ARRAY[$cmdhelp$rejectname$cmdhelp$]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Force-rename a pending character and approve.$cmdhelp$, $cmdhelp$reject_name <character> <new-name>$cmdhelp$, true, $cmdhelp$Force-rename a pending character and approve.$cmdhelp$, $cmdhelp$Immortal+. Only for a character whose name is awaiting approval; an approved character is refused. Renames the named character to the staff-chosen replacement and flips name_approved to true (the new name is by definition staff-approved). Refuses while the target is online — the in-memory Named cache needs a fresh login to pick up the rename cleanly. A duplicate new-name surfaces as the Postgres unique-index error.$cmdhelp$),
    ($cmdhelp$release$cmdhelp$, ARRAY[]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$End the ghost cycle: restore HP, return to recall.$cmdhelp$, $cmdhelp$release$cmdhelp$, false, $cmdhelp$End the ghost cycle: restore HP, return to recall.$cmdhelp$, $cmdhelp$When you die, your spirit is left where you fell while your corpse drops at the death scene. 'release' returns you to your recall point at full HP. Refused when you aren't currently dead.$cmdhelp$),
    ($cmdhelp$reloadallzones$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Reload every zone's world data from the DB.$cmdhelp$, $cmdhelp$reloadallzones$cmdhelp$, true, $cmdhelp$Reload every zone's world data from the DB.$cmdhelp$, $cmdhelp$Coder+. Same as 'reloadzone' applied to every zone: rooms, prototypes and resets are re-read from the database; live instances are untouched.$cmdhelp$),
    ($cmdhelp$reloadzone$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Reload one zone's rooms, mobs, objects and resets from the DB.$cmdhelp$, $cmdhelp$reloadzone [<zone>]$cmdhelp$, true, $cmdhelp$Reload one zone's rooms, mobs, objects and resets from the DB.$cmdhelp$, $cmdhelp$Builder+. Re-reads the zone's room definitions (name, description, flags, exits, extra descriptions), the mob/object prototypes it owns, and its reset rows from the database, so edits made in the editor take effect without a restart. Live mobs and items are left alone; new prototypes apply to future spawns. Defaults to your current zone. Exit door states of reloaded rooms reset to their authored default; rooms deleted from the DB stay until restart.$cmdhelp$),
    ($cmdhelp$remove$cmdhelp$, ARRAY[$cmdhelp$rem$cmdhelp$]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Unequip an item, returning it to your inventory.$cmdhelp$, $cmdhelp$remove <item>$cmdhelp$, false, $cmdhelp$Unequip an item, returning it to your inventory.$cmdhelp$, $cmdhelp$The item must currently be equipped on you.$cmdhelp$),
    ($cmdhelp$rename$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Rename a character (offline-only).$cmdhelp$, $cmdhelp$rename <old> <new>$cmdhelp$, true, $cmdhelp$Rename a character (offline-only).$cmdhelp$, $cmdhelp$Implementor-only. Refuses while the target is online — the in-memory Named cache and the ConnRouter mappings would drift otherwise. The character_id is the FK across CharacterItems / CharacterAbilities / etc., so foreign-key relationships survive untouched. Conflicts on the new name surface as the unique-index error from Postgres.$cmdhelp$),
    ($cmdhelp$rend$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Tearing attack — damage plus bleed effect.$cmdhelp$, $cmdhelp$rend [<target>]$cmdhelp$, false, $cmdhelp$Tearing attack — damage plus bleed effect.$cmdhelp$, $cmdhelp$Costs 7 stamina, deals weapon damage, applies a 'bleed' EffectInstance for 30s. Default target is the current Fighting target. Refused if the target is already bleeding.$cmdhelp$),
    ($cmdhelp$rent$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Rent a room: save and leave at a receptionist, or book an inn rest.$cmdhelp$, $cmdhelp$rent [<tier-name>]$cmdhelp$, false, $cmdhelp$Rent a room: save and leave at a receptionist, or book an inn rest.$cmdhelp$, $cmdhelp$With a receptionist present, plain 'rent' stores your belongings and leaves the game exactly like 'quit', keeping any rest you have already booked. 'offer' lists the available inn tiers and their prices (so does 'rent' in an inn with no receptionist). 'rent <name>' books that tier and charges the fee in gold and queues an INN RestSource at the chosen tier; you'll see Refreshed regen and any Wake Effect attachments on your next XP gain after logging back in. Tiers 2 and 3 prompt for confirmation; reply 'y' to confirm or 'n' to abort. Fee is flat — pay once, return whenever.$cmdhelp$),
    ($cmdhelp$repair$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Have a shopkeeper repair or refuel an item.$cmdhelp$, $cmdhelp$repair <item>$cmdhelp$, false, $cmdhelp$Have a shopkeeper repair or refuel an item.$cmdhelp$, $cmdhelp$Refills a lantern or torch for 10 copper per missing game-hour of fuel. Other items have no durability and are reported as already in perfect condition.$cmdhelp$),
    ($cmdhelp$reply$cmdhelp$, ARRAY[]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Send a tell to whoever last told you.$cmdhelp$, $cmdhelp$reply <message>$cmdhelp$, false, $cmdhelp$Send a tell to whoever last told you.$cmdhelp$, $cmdhelp$Forwards through 'tell' so the LastTeller stamp lands on them too — start a back-and-forth without typing the name.$cmdhelp$),
    ($cmdhelp$report$cmdhelp$, ARRAY[$cmdhelp$rep$cmdhelp$]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Announce your HP/stamina to the room or one player.$cmdhelp$, $cmdhelp$report [<player>]$cmdhelp$, false, $cmdhelp$Announce your HP/stamina to the room or one player.$cmdhelp$, $cmdhelp$With no argument, says your hit and movement points to everyone in the room. 'report <player>' tells that player instead (only they see it, and the usual tell refusals apply). Use 'greport' to report to your whole group.$cmdhelp$),
    ($cmdhelp$reroll$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Reroll a player's six core stats (3d6 each).$cmdhelp$, $cmdhelp$reroll <player>$cmdhelp$, true, $cmdhelp$Reroll a player's six core stats (3d6 each).$cmdhelp$, $cmdhelp$Builder+ (level 101+) only. Wipes CoreStats and rolls 3d6 per axis (STR / DEX / CON / INT / WIS / CHA). Sends the new roll to the target so they can verify it.$cmdhelp$),
    ($cmdhelp$rescue$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Take an enemy's aggression onto yourself.$cmdhelp$, $cmdhelp$rescue <player>$cmdhelp$, false, $cmdhelp$Take an enemy's aggression onto yourself.$cmdhelp$, $cmdhelp$Find <player> in your room. Their attacker now targets you instead and you target them. The ally is freed from combat. Costs 6 stamina. Refused if you're already fighting and refused if your ally isn't being attacked.$cmdhelp$),
    ($cmdhelp$rest$cmdhelp$, ARRAY[$cmdhelp$recline$cmdhelp$]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Rest in place.$cmdhelp$, $cmdhelp$rest$cmdhelp$, false, $cmdhelp$Rest in place.$cmdhelp$, $cmdhelp$Changes your posture to resting. Posture sets how fast you recover: standing restores stamina only, sitting a little hit points as well, resting more, and sleeping the most.$cmdhelp$),
    ($cmdhelp$restore$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Refill a player's HP and stamina to max.$cmdhelp$, $cmdhelp$restore <player>$cmdhelp$, true, $cmdhelp$Refill a player's HP and stamina to max.$cmdhelp$, $cmdhelp$HeadBuilder+ (level 103+) only. No-op for offline players.$cmdhelp$),
    ($cmdhelp$retreat$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Flee combat in a specific direction.$cmdhelp$, $cmdhelp$retreat <direction>$cmdhelp$, false, $cmdhelp$Flee combat in a specific direction.$cmdhelp$, $cmdhelp$Like 'flee' but you choose where to go. Refused if the direction has no exit, the door's closed, or the target room is dangling.$cmdhelp$),
    ($cmdhelp$return$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$End a 'switch' session and return to your own body.$cmdhelp$, $cmdhelp$return$cmdhelp$, true, $cmdhelp$End a 'switch' session and return to your own body.$cmdhelp$, $cmdhelp$Builder+. Inverse of 'switch'. Always types as the puppeteer (not the mob) — the dispatcher keeps 'return' and 'switch' as escape hatches so a stuck switch can always be undone.$cmdhelp$),
    ($cmdhelp$revoke$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Take a command away from a character.$cmdhelp$, $cmdhelp$revoke <name> command <command> [level]$cmdhelp$, true, $cmdhelp$Take a command away from a character.$cmdhelp$, $cmdhelp$Coder+. Per-character command access. A grant lets a character use one command above their rank; a revoke takes a command away. Only online players strictly below your level, and only commands you can use yourself. 'grant <name>' lists a character's grants and revokes; 'grant <name> clear' drops the ones at or below your level. A mortal can only be granted commands on the grants.mortal_allowlist config row (empty by default), and never an admin command. Command groups and privilege flags do not exist on this server.$cmdhelp$),
    ($cmdhelp$richtest$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Render a color-tag sampler.$cmdhelp$, $cmdhelp$richtest$cmdhelp$, false, $cmdhelp$Render a color-tag sampler.$cmdhelp$, $cmdhelp$Prints a sampler of every color and modifier the XML-Lite renderer supports — handy for verifying your client's color depth and for debugging color-tag rendering.$cmdhelp$),
    ($cmdhelp$rlist$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$List rooms in a zone or id range.$cmdhelp$, $cmdhelp$rlist [*|<zone> [[from] <id> [to] [<id>]]] [page <n>]$cmdhelp$, true, $cmdhelp$List rooms in a zone or id range.$cmdhelp$, $cmdhelp$Builder+. Lists loaded rooms as '[zone:id] name', sorted by (zone, id). With no argument it lists your current zone; '*' lists every zone; '<zone>' lists that zone; '<zone> <first> <last>' (or '<zone>:<first> <zone>:<last>') narrows to an id span, and a missing <last> means 'to the end of the zone'. Long lists are paged 50 rows at a time: add 'page <n>'. Pair with 'rstat' for a room's detail, or 'rsearch' to search by name.$cmdhelp$),
    ($cmdhelp$rnum$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Find rooms by name keyword (zone:id).$cmdhelp$, $cmdhelp$rnum <keywords> [in <zone>]$cmdhelp$, true, $cmdhelp$Find rooms by name keyword (zone:id).$cmdhelp$, $cmdhelp$Builder+. Lists prototypes whose name or keywords start with every word you give, as 'zone:id name', sorted by id and capped at 100 rows. 'vnum' takes a type first (mobiles, objects, rooms, triggers, exits), 'mnum' / 'onum' / 'rnum' / 'tnum' are the same search for one type. Add 'in <zone>' to stay in one zone. Pair with 'vstat', 'rstat' or 'tstat', or jump with 'goto <zone>:<id>'.$cmdhelp$),
    ($cmdhelp$roar$cmdhelp$, ARRAY[$cmdhelp$howl$cmdhelp$]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Terrify everyone in the room into running.$cmdhelp$, $cmdhelp$roar$cmdhelp$, false, $cmdhelp$Terrify everyone in the room into running.$cmdhelp$, $cmdhelp$Costs 8 stamina. Also deals the Roar skill's damage to each enemy in the room. Each enemy that fails its saving throw panics: it flees, trips over its own feet, or (if asleep) may be jolted awake. Aware and no-summon mobs, and mobs immune to fear, ignore it. Group members are not affected.$cmdhelp$),
    ($cmdhelp$roles$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Show your account role and permissions.$cmdhelp$, $cmdhelp$roles$cmdhelp$, false, $cmdhelp$Show your account role and permissions.$cmdhelp$, $cmdhelp$Diagnostic: prints the role and any extra permissions attached to your account.$cmdhelp$),
    ($cmdhelp$roundhouse$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Powerful kick — 1.5x damage on your current target.$cmdhelp$, $cmdhelp$roundhouse$cmdhelp$, false, $cmdhelp$Powerful kick — 1.5x damage on your current target.$cmdhelp$, $cmdhelp$Costs 7 stamina. Heavier kick than the basic 'kick' skill (which adds +4); pure damage multiplier. Requires you to be fighting someone.$cmdhelp$),
    ($cmdhelp$rpain$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Cosmetic divine pain across the realm.$cmdhelp$, $cmdhelp$rpain [<message>]$cmdhelp$, true, $cmdhelp$Cosmetic divine pain across the realm.$cmdhelp$, $cmdhelp$HeadBuilder+ (level 103+) only. Same as 'pain' but reaches every online player. Pure flavor — no stat change. Optional <message> overrides the default line. Players see your line; the caster sees a confirmation count.$cmdhelp$),
    ($cmdhelp$rrestore$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Heal every online player + strip every effect.$cmdhelp$, $cmdhelp$rrestore [<message>]$cmdhelp$, true, $cmdhelp$Heal every online player + strip every effect.$cmdhelp$, $cmdhelp$Immortal+ (level 100+) only. Restores HP / stamina to max and clears every active EffectInstance for every online player. Optional <message> overrides the default flavor line. The realm-wide counterpart to 'restore'.$cmdhelp$),
    ($cmdhelp$rsearch$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Search rooms by name, description, sector or room flags.$cmdhelp$, $cmdhelp$rsearch <field> <query> [in <zone>]$cmdhelp$, true, $cmdhelp$Search rooms by name, description, sector or room flags.$cmdhelp$, $cmdhelp$Builder+. 'rsearch <field> <query> [in <zone>]' searches rooms (legacy 'rsearch'; same as 'vsearch rooms'). Fields: name, desc, sector (city, forest, water, ...), flags (peaceful, nomagic, norecall, nosummon, noteleport, deathtrap, indoors, soundproof, arena, guildhall, nomobs, notracking, noportals, noscanning, inn). Examples: 'rsearch flags deathtrap', 'rsearch sector forest in 30', 'rsearch flags nomagic peaceful'. Add 'in <zone>' to stay in one zone; at most 100 rows print.$cmdhelp$),
    ($cmdhelp$rstat$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Dump a room's ECS state (live entity, not catalog).$cmdhelp$, $cmdhelp$rstat [<zone> <id> | <id>]$cmdhelp$, true, $cmdhelp$Dump a room's ECS state (live entity, not catalog).$cmdhelp$, $cmdhelp$Builder+. With no arg, inspects your current room. <id> alone looks up the room in your current zone. Composite <zone> <id> works too.$cmdhelp$),
    ($cmdhelp$save$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Force a checkpoint of your character to the database.$cmdhelp$, $cmdhelp$save$cmdhelp$, false, $cmdhelp$Force a checkpoint of your character to the database.$cmdhelp$, $cmdhelp$Persists hp / stamina / xp / inventory / location / flags / prompt / hunger / thirst / drunk / known abilities / spell-slot cooldowns / ability cooldowns back to the schema. The same path runs automatically on disconnect and on graceful shutdown — 'save' lets you force it right now without logging out, useful before a risky encounter or when the network feels unstable.$cmdhelp$),
    ($cmdhelp$savezone$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$No-op: world data is saved by the editor.$cmdhelp$, $cmdhelp$savezone [<zone>]$cmdhelp$, true, $cmdhelp$No-op: world data is saved by the editor.$cmdhelp$, $cmdhelp$Builder+. The C++ server wrote zone files to disk. Here the database is the source of truth and the editor writes it, so there is nothing to save; use 'reloadzone' to pull editor changes into the world.$cmdhelp$),
    ($cmdhelp$say$cmdhelp$, ARRAY[$cmdhelp$'$cmdhelp$]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Speak to everyone in the room.$cmdhelp$, $cmdhelp$say <message>$cmdhelp$, false, $cmdhelp$Speak to everyone in the room.$cmdhelp$, $cmdhelp$Visible to every player in your current room. Triggers SPEECH-flagged Lua bodies on mobs / objects in the room.$cmdhelp$),
    ($cmdhelp$scan$cmdhelp$, ARRAY[]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Peek at the adjacent rooms one step away.$cmdhelp$, $cmdhelp$scan$cmdhelp$, false, $cmdhelp$Peek at the adjacent rooms one step away.$cmdhelp$, $cmdhelp$Walks each unblocked exit and lists every mob / player you'd see in those rooms, with a distance label and posture (std/sit/fly/slp). Default range is one room; staff scan up to three. Closed or hidden doors stop the walk in that direction. Useful for spotting threats / hosts before walking in.$cmdhelp$),
    ($cmdhelp$score$cmdhelp$, ARRAY[$cmdhelp$sc$cmdhelp$]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Display your character's stats.$cmdhelp$, $cmdhelp$score$cmdhelp$, false, $cmdhelp$Display your character's stats.$cmdhelp$, $cmdhelp$Shows HP, stamina, six core attributes, the modern combat triple (Acc / Eva / Atk / Armor%), alignment, posture, location, recall point, and your current combat target when fighting. Spell-circle slots are surfaced separately via 'slots'; full effect durations via 'effects'; XP / next-level gains via 'level'.$cmdhelp$),
    ($cmdhelp$scribe$cmdhelp$, ARRAY[]::text[], 'MAGIC'::"CommandCategory", $cmdhelp$Scribe a known spell onto a blank scroll.$cmdhelp$, $cmdhelp$scribe '<spell name>'$cmdhelp$, false, $cmdhelp$Scribe a known spell onto a blank scroll.$cmdhelp$, $cmdhelp$You must be sitting, out of combat, carrying a scroll, and know the spell at 50% proficiency or better.$cmdhelp$),
    ($cmdhelp$scripterrors$cmdhelp$, ARRAY[$cmdhelp$scripterr$cmdhelp$]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Show recent trigger fire failures.$cmdhelp$, $cmdhelp$scripterrors [<n>]$cmdhelp$, true, $cmdhelp$Show recent trigger fire failures.$cmdhelp$, $cmdhelp$Builder+. Prints the in-memory 'ScriptErrorLog' ring (most-recent first). Default 'n=20'.$cmdhelp$),
    ($cmdhelp$search$cmdhelp$, ARRAY[]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Search the area for hidden objects, exits and hiding characters.$cmdhelp$, $cmdhelp$search [<keyword>]$cmdhelp$, false, $cmdhelp$Search the area for hidden objects, exits and hiding characters.$cmdhelp$, $cmdhelp$Refuses while fighting. Hidden objects come first: 'search' checks the ones lying in the room, 'search <container>' the ones inside it. Your perception cuts each one's hiding by a random amount, and whatever is left within your perception is found (staff find them all); finding something ends the search. Otherwise each hidden exit you haven't found is checked in turn: naming its keyword ('search monolith') always finds it, otherwise your Intelligence is rolled against 0-200. The first exit found is revealed (staff always find one). A search leaves you busy for half a combat round. Reveals are per-character and session-scoped — a fresh login starts back at zero known hidden exits, matching the legacy contract until a persistent table for revealed exits lands. Pair with 'exits' afterward to confirm what surfaced. When no exit turns up, you look for hiding characters outside your group instead: your perception cuts each one's hiding by a random amount, and whoever is left within your perception is found.$cmdhelp$),
    ($cmdhelp$sell$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Sell a carried item to the shopkeeper here.$cmdhelp$, $cmdhelp$sell <item>$cmdhelp$, false, $cmdhelp$Sell a carried item to the shopkeeper here.$cmdhelp$, $cmdhelp$Pays 'proto.cost * sell_profit' rounded (never more than the item's cost) for a carried item the keeper trades in. Equipped items are refused ('remove' first). A keeper with no 'ShopAccepts' rules buys nothing.$cmdhelp$),
    ($cmdhelp$send$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Send raw text to a player's connection.$cmdhelp$, $cmdhelp$send <player> <text>$cmdhelp$, true, $cmdhelp$Send raw text to a player's connection.$cmdhelp$, $cmdhelp$Builder+ (level 101+) only. Skips the rendering pipeline entirely — bytes go straight to the descriptor. Used to surface diagnostic output that already carries ANSI escapes.$cmdhelp$),
    ($cmdhelp$set$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Mutate a player field directly.$cmdhelp$, $cmdhelp$set <player> <field> <value>  |  set fields$cmdhelp$, true, $cmdhelp$Mutate a player field directly.$cmdhelp$, $cmdhelp$Builder+ (level 101+) only. Run 'set fields' to list every writable field with its aliases. 'stat <player>' dumps the full read-only component state — pair the two when poking at a character.$cmdhelp$),
    ($cmdhelp$setrecall$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Bind your recall point to the current room (admin).$cmdhelp$, $cmdhelp$setrecall$cmdhelp$, true, $cmdhelp$Bind your recall point to the current room (admin).$cmdhelp$, $cmdhelp$Builder+. Saves the room you're standing in as your recall destination. Persists across logins. Mortals reset their recall via a touchstone item (see 'touch <object>').$cmdhelp$),
    ($cmdhelp$setweather$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Override a zone's weather.$cmdhelp$, $cmdhelp$setweather <zone> <kind>$cmdhelp$, true, $cmdhelp$Override a zone's weather.$cmdhelp$, $cmdhelp$Builder+. Forces a precip kind in the zone's 'WeatherCatalog' entry until the next natural weather tick rolls a new value.$cmdhelp$),
    ($cmdhelp$shout$cmdhelp$, ARRAY[$cmdhelp$sh$cmdhelp$]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Shout to every online player.$cmdhelp$, $cmdhelp$shout <message>$cmdhelp$, false, $cmdhelp$Shout to every online player.$cmdhelp$, $cmdhelp$Higher-volume cousin of 'say' (which is room-only). Same Deaf / ignore filtering as 'gossip'.$cmdhelp$),
    ($cmdhelp$show$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Dump runtime catalogs / counts.$cmdhelp$, $cmdhelp$show <category>$cmdhelp$, true, $cmdhelp$Dump runtime catalogs / counts.$cmdhelp$, $cmdhelp$Builder+. Categories include 'audit', 'effects', 'weather', 'triggers', 'tickrate'. See in-source for the full list.$cmdhelp$),
    ($cmdhelp$showids$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Toggle showing (zone, id) on entities you can see.$cmdhelp$, $cmdhelp$showids$cmdhelp$, true, $cmdhelp$Toggle showing (zone, id) on entities you can see.$cmdhelp$, $cmdhelp$Sets SHOW_IDS. Look/inventory renderers that want to surface coordinates check the flag.$cmdhelp$),
    ($cmdhelp$shutdown$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Gracefully shut the server down (saves all players).$cmdhelp$, $cmdhelp$shutdown <now|cancel|seconds> [reason]$cmdhelp$, true, $cmdhelp$Gracefully shut the server down (saves all players).$cmdhelp$, $cmdhelp$Coder+. 'shutdown now' stops immediately; 'shutdown 60 maintenance' announces and counts down 60 seconds; 'shutdown cancel' aborts a pending countdown. Every online player is saved before the process exits; the process manager restarts it.$cmdhelp$),
    ($cmdhelp$sip$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Sip 1 unit from a drink container.$cmdhelp$, $cmdhelp$sip <container>$cmdhelp$, false, $cmdhelp$Sip 1 unit from a drink container.$cmdhelp$, $cmdhelp$Lighter than 'drink' (4 units). Same refusal on empty containers; same poison handling.$cmdhelp$),
    ($cmdhelp$sit$cmdhelp$, ARRAY[]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Sit down.$cmdhelp$, $cmdhelp$sit$cmdhelp$, false, $cmdhelp$Sit down.$cmdhelp$, $cmdhelp$Changes your posture to sitting.$cmdhelp$),
    ($cmdhelp$skills$cmdhelp$, ARRAY[$cmdhelp$sk$cmdhelp$]::text[], 'MAGIC'::"CommandCategory", $cmdhelp$List skills you know (or the full catalog).$cmdhelp$, $cmdhelp$skills [all] [filter]$cmdhelp$, false, $cmdhelp$List skills you know (or the full catalog).$cmdhelp$, $cmdhelp$Like 'spells' but filtered to kind=Skill. Default shows only what you've learned; 'skills all' dumps the full catalog. Optional substring filter applies to either scope.$cmdhelp$),
    ($cmdhelp$skillset$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Set a player's proficiency in a single ability.$cmdhelp$, $cmdhelp$skillset <player> <ability> <proficiency>$cmdhelp$, true, $cmdhelp$Set a player's proficiency in a single ability.$cmdhelp$, $cmdhelp$Builder+. Writes the row in the target's KnownAbilities. Inserts a new entry when the ability isn't already learned. Proficiency is 0..=1000 (legacy convention). Multi-word abilities work as written or quoted: skillset bob 'sphere of healing' 1000.$cmdhelp$),
    ($cmdhelp$slay$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Kill a target instantly, ignoring HP / armor.$cmdhelp$, $cmdhelp$slay <player|mob>$cmdhelp$, true, $cmdhelp$Kill a target instantly, ignoring HP / armor.$cmdhelp$, $cmdhelp$Implementor-only. Same death pipeline as combat — corpses, loot drops, triggers all fire normally.$cmdhelp$),
    ($cmdhelp$sleep$cmdhelp$, ARRAY[]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Lie down and sleep.$cmdhelp$, $cmdhelp$sleep$cmdhelp$, false, $cmdhelp$Lie down and sleep.$cmdhelp$, $cmdhelp$Changes your posture to sleeping. Wake with 'wake', 'stand', 'sit', or 'rest'.$cmdhelp$),
    ($cmdhelp$slist$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$List every ability of a given kind, or all kinds.$cmdhelp$, $cmdhelp$slist [spell|chant|song|skill]$cmdhelp$, true, $cmdhelp$List every ability of a given kind, or all kinds.$cmdhelp$, $cmdhelp$Builder+. Pages through 'AbilityCatalog', sorted alphabetically. With no arg, prints every ability grouped by kind. With a kind label, narrows the list. Pair with 'astat <name>' for per-ability detail.$cmdhelp$),
    ($cmdhelp$slots$cmdhelp$, ARRAY[]::text[], 'MAGIC'::"CommandCategory", $cmdhelp$Show your spell-slot pool and any in-flight cooldowns.$cmdhelp$, $cmdhelp$slots$cmdhelp$, false, $cmdhelp$Show your spell-slot pool and any in-flight cooldowns.$cmdhelp$, $cmdhelp$Pooled slot model (legacy): each circle has 'class+level' slots; casting consumes a slot and queues its recovery. Slots recover one at a time, in the order you cast: the next slot's timer starts only once the one ahead of it is back. They recover on their own under Sleeping / Resting / Sitting postures (faster while Meditating). Format 'Circle N: free/max  (recovering: 12s, 30s)'. Cooldowns persist across disconnect.$cmdhelp$),
    ($cmdhelp$sneak$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Move silently — keep your hiding as you walk.$cmdhelp$, $cmdhelp$sneak$cmdhelp$, false, $cmdhelp$Move silently — keep your hiding as you walk.$cmdhelp$, $cmdhelp$Drains 3 stamina and dispatches the SNEAK skill via the data path. Spawns a 'sneak' status effect that wears 'hide' down only slowly as you move, so a sneaking, hidden character passes observers whose perception is below their hiding unseen and unheard. Sneaking alone hides nothing: 'hide' first.$cmdhelp$),
    ($cmdhelp$snoop$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Mirror another player's output to your screen.$cmdhelp$, $cmdhelp$snoop [<player>]$cmdhelp$, true, $cmdhelp$Mirror another player's output to your screen.$cmdhelp$, $cmdhelp$Builder+. With a player name, starts mirroring their output (every line they receive prints to you with a dim '%' prefix). With no arg, stops the current snoop. Refuses snooping yourself, an equal-or-higher level account, or a player who's already being snooped — one snooper per target. Re-snooping a different target rewires cleanly.$cmdhelp$),
    ($cmdhelp$snum$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Print the catalog id for an ability by name.$cmdhelp$, $cmdhelp$snum <name>$cmdhelp$, true, $cmdhelp$Print the catalog id for an ability by name.$cmdhelp$, $cmdhelp$Builder+. Case-insensitive whole-name match. For substring search use 'ssearch'. The id surfaces on 'varset' / 'skillset' / formula bindings.$cmdhelp$),
    ($cmdhelp$socials$cmdhelp$, ARRAY[]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$List every available social verb.$cmdhelp$, $cmdhelp$socials$cmdhelp$, false, $cmdhelp$List every available social verb.$cmdhelp$, $cmdhelp$Sorted alphabetically, columnar layout. Use any listed verb on its own (or with a target) to fire the matching social — 'nod', 'shrug', 'smile alice', etc.$cmdhelp$),
    ($cmdhelp$songs$cmdhelp$, ARRAY[]::text[], 'MAGIC'::"CommandCategory", $cmdhelp$List bardic songs you know (or the full catalog).$cmdhelp$, $cmdhelp$songs [all] [filter]$cmdhelp$, false, $cmdhelp$List bardic songs you know (or the full catalog).$cmdhelp$, $cmdhelp$Like 'spells' but filtered to kind=Song. Default shows only songs you've learned; 'songs all' dumps the catalog. Use 'perform <song>' to invoke.$cmdhelp$),
    ($cmdhelp$south$cmdhelp$, ARRAY[$cmdhelp$s$cmdhelp$]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Walk through an exit.$cmdhelp$, $cmdhelp$<direction>$cmdhelp$, false, $cmdhelp$Walk through an exit.$cmdhelp$, $cmdhelp$Moves you through the named exit if one is open. Standard directions: n/s/e/w/u/d/ne/nw/se/sw/in/out.$cmdhelp$),
    ($cmdhelp$southeast$cmdhelp$, ARRAY[$cmdhelp$se$cmdhelp$]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Walk through an exit.$cmdhelp$, $cmdhelp$<direction>$cmdhelp$, false, $cmdhelp$Walk through an exit.$cmdhelp$, $cmdhelp$Moves you through the named exit if one is open. Standard directions: n/s/e/w/u/d/ne/nw/se/sw/in/out.$cmdhelp$),
    ($cmdhelp$southwest$cmdhelp$, ARRAY[$cmdhelp$sw$cmdhelp$]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Walk through an exit.$cmdhelp$, $cmdhelp$<direction>$cmdhelp$, false, $cmdhelp$Walk through an exit.$cmdhelp$, $cmdhelp$Moves you through the named exit if one is open. Standard directions: n/s/e/w/u/d/ne/nw/se/sw/in/out.$cmdhelp$),
    ($cmdhelp$spells$cmdhelp$, ARRAY[$cmdhelp$abilities$cmdhelp$, $cmdhelp$abil$cmdhelp$]::text[], 'MAGIC'::"CommandCategory", $cmdhelp$List spells you know, grouped by circle.$cmdhelp$, $cmdhelp$spells [<circle>|<lo>-<hi>] [filter] | spells all [filter]$cmdhelp$, false, $cmdhelp$List spells you know, grouped by circle.$cmdhelp$, $cmdhelp$By default shows the spells you've learned grouped by your class's spell circle (1 = lowest). Numeric args filter by circle: 'spells 3' shows circle 3, 'spells 1-2' shows circles 1 through 2. A trailing word filters by name, sphere, or damage type — 'spells 2-3 fire' or 'spells dam'. Add 'all' to dump the full spell catalog (handy for builders); the cross-class catalog has no circle grouping.$cmdhelp$),
    ($cmdhelp$split$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Divide coin evenly among same-room group members.$cmdhelp$, $cmdhelp$split <amount>$cmdhelp$, false, $cmdhelp$Divide coin evenly among same-room group members.$cmdhelp$, $cmdhelp$Pulls '<amount>' from your wealth and splits it evenly across every group member in your room (including you). Remainder stays with the splitter. Refuses if you're not grouped, the only group member here, or carrying less than 'amount'. Coin amount is in copper; use 'wealth' to check yours.$cmdhelp$),
    ($cmdhelp$springleap$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Out-of-combat leaping kick — 1.5x damage opener.$cmdhelp$, $cmdhelp$springleap <target>$cmdhelp$, false, $cmdhelp$Out-of-combat leaping kick — 1.5x damage opener.$cmdhelp$, $cmdhelp$Deals 1.5x your damage on the opening swing and engages the target. Refused if you're already fighting or if the target is already in combat.$cmdhelp$),
    ($cmdhelp$ssearch$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Find abilities by name substring.$cmdhelp$, $cmdhelp$ssearch <substring>$cmdhelp$, true, $cmdhelp$Find abilities by name substring.$cmdhelp$, $cmdhelp$Builder+. Case-insensitive substring against the ability's plain name. Renders '(id) name (kind)' per match, capped at 50.$cmdhelp$),
    ($cmdhelp$sstat$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Dump a shop's metadata.$cmdhelp$, $cmdhelp$sstat <zone> <id> | <id>$cmdhelp$, true, $cmdhelp$Dump a shop's metadata.$cmdhelp$, $cmdhelp$Builder+. Reads 'ShopCatalog' for keeper, accept rules, items offered, pet roster. <id> alone defaults to your current zone.$cmdhelp$),
    ($cmdhelp$stand$cmdhelp$, ARRAY[]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Get to your feet.$cmdhelp$, $cmdhelp$stand$cmdhelp$, false, $cmdhelp$Get to your feet.$cmdhelp$, $cmdhelp$Changes your posture to standing.$cmdhelp$),
    ($cmdhelp$stat$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Dump a LIVE entity's per-instance component state.$cmdhelp$, $cmdhelp$stat <name>$cmdhelp$, true, $cmdhelp$Dump a LIVE entity's per-instance component state.$cmdhelp$, $cmdhelp$Builder+. Reads every component on the named live entity (player, mob, or item by name in your room) and prints a structured dump. Items print the same block as 'ostat' plus their instance state. 
Note the difference from mstat: stat shows what the entity actually has right now (e.g. current HP, active effects, stored vars); mstat / ostat show the catalog template the entity was spawned from.$cmdhelp$),
    ($cmdhelp$stay$cmdhelp$, ARRAY[]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Stay where you are.$cmdhelp$, $cmdhelp$stay [<direction>]$cmdhelp$, false, $cmdhelp$Stay where you are.$cmdhelp$, $cmdhelp$Does nothing but say so. With the Misdirection spell on you, 'stay <direction>' acts out leaving that way without going anywhere. See 'help misdirection'.$cmdhelp$),
    ($cmdhelp$steal$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Pickpocket from a target.$cmdhelp$, $cmdhelp$steal <item|coins> <target>$cmdhelp$, false, $cmdhelp$Pickpocket from a target.$cmdhelp$, $cmdhelp$Gated on the Steal skill (the classes that teach it, Thief and Bard in the legacy data). Refused while fighting, against yourself, against a Shopkeeper, and against staff. On failure the target notices and re-aggros on you. Pass 'coins' / 'gold' to grab a chunk of their coin instead of an item.$cmdhelp$),
    ($cmdhelp$stomp$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Knock the target prone (Sitting posture).$cmdhelp$, $cmdhelp$stomp [<target>]$cmdhelp$, false, $cmdhelp$Knock the target prone (Sitting posture).$cmdhelp$, $cmdhelp$Costs 6 stamina, deals half your damage, sets the target's posture to Sitting. Default target is your current Fighting target. Refused on already-prone targets.$cmdhelp$),
    ($cmdhelp$stow$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Quickly sheathe your wielded weapon.$cmdhelp$, $cmdhelp$stow$cmdhelp$, false, $cmdhelp$Quickly sheathe your wielded weapon.$cmdhelp$, $cmdhelp$Moves the weapon in your wield slot into your inventory without the fuss of 'remove'.$cmdhelp$),
    ($cmdhelp$study$cmdhelp$, ARRAY[]::text[], 'MAGIC'::"CommandCategory", $cmdhelp$Permanently learn a spell from your class list.$cmdhelp$, $cmdhelp$study <spell>$cmdhelp$, false, $cmdhelp$Permanently learn a spell from your class list.$cmdhelp$, $cmdhelp$Adds the spell to your 'KnownAbilities' at the minimum proficiency tier ('known=true', proficiency=1). Refuses unknown abilities, already-known spells, or off-class spells. Persists across reconnect via 'CharacterAbilities'.$cmdhelp$),
    ($cmdhelp$style$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Choose a UI style for info commands like score.$cmdhelp$, $cmdhelp$style [fancy | standard | minimal]$cmdhelp$, false, $cmdhelp$Choose a UI style for info commands like score.$cmdhelp$, $cmdhelp$Three tiers: fancy (ASCII-art borders), standard (the default — clean indented lines), and minimal (a single dense line, useful in narrow viewports). With no argument, shows the current style. Currently only score honors this; more commands will follow.$cmdhelp$),
    ($cmdhelp$subclass$cmdhelp$, ARRAY[]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$List or choose a subclass specialization.$cmdhelp$, $cmdhelp$subclass [specialization]$cmdhelp$, false, $cmdhelp$List or choose a subclass specialization.$cmdhelp$, $cmdhelp$With no argument, lists the subclasses available to your class. With a name (or unique prefix), specializes into that subclass. Requires level 20 (the 'character.subclass_min_level' config) and is permanent once chosen.$cmdhelp$),
    ($cmdhelp$summon$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Spawn one or more mob proto instances at your location.$cmdhelp$, $cmdhelp$summon <mob proto> [<count>]$cmdhelp$, true, $cmdhelp$Spawn one or more mob proto instances at your location.$cmdhelp$, $cmdhelp$Builder+. Reads the (zone, id) MobProto and spawns 'count' (default 1) instances Located on your room.$cmdhelp$),
    ($cmdhelp$summonmount$cmdhelp$, ARRAY[$cmdhelp$summon-mount$cmdhelp$]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Conjure a mount (Paladin / Anti-Paladin only).$cmdhelp$, $cmdhelp$summonmount$cmdhelp$, false, $cmdhelp$Conjure a mount (Paladin / Anti-Paladin only).$cmdhelp$, $cmdhelp$Gated on the Summon Mount skill (Paladin and Anti-Paladin from level 15 in the legacy data); refused indoors, while fighting, or when you already have a mount following you. Spawns the first matching mountable proto as a Follower in your current room.$cmdhelp$),
    ($cmdhelp$sweep$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Sweeping kick — knock every standing mob in room prone.$cmdhelp$, $cmdhelp$sweep$cmdhelp$, false, $cmdhelp$Sweeping kick — knock every standing mob in room prone.$cmdhelp$, $cmdhelp$Costs 12 stamina. Deals 1/4 damage to every Standing Mob in the room and sets each to Sitting. Players never targeted.$cmdhelp$),
    ($cmdhelp$switch$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Take control of a mob in your current room.$cmdhelp$, $cmdhelp$switch <mob>$cmdhelp$, true, $cmdhelp$Take control of a mob in your current room.$cmdhelp$, $cmdhelp$Builder+. Future commands you type dispatch against the mob instead of yourself; output the mob would receive forwards to your connection. Useful for testing triggers from inside a mob and for running RP-as-NPC. 'return' ends the switch.$cmdhelp$),
    ($cmdhelp$syslog$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Show recent server log lines or subscribe to live errors.$cmdhelp$, $cmdhelp$syslog [<n> [<filter>] | watch [warn|error|off]]$cmdhelp$, true, $cmdhelp$Show recent server log lines or subscribe to live errors.$cmdhelp$, $cmdhelp$Builder+. Two modes:
  syslog                 — last 30 entries from the in-memory ring (newest at the bottom).
  syslog <n> [<filter>]  — last n entries (1-500), optionally filtered by level ('WARN', 'ERROR') or a substring matched against target / message.
  syslog watch           — subscribe to live WARN+ events; each new line lands on your prompt as it fires. Same as 'syslog watch warn'.
  syslog watch error     — subscribe but raise the floor to ERROR-only.
  syslog watch off       — unsubscribe. Disconnect also clears the subscription.$cmdhelp$),
    ($cmdhelp$tame$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Befriend an animal mob into following you.$cmdhelp$, $cmdhelp$tame <target>$cmdhelp$, false, $cmdhelp$Befriend an animal mob into following you.$cmdhelp$, $cmdhelp$Drains 4 stamina and dispatches the TAME skill at the named target. The schema's 'charmed' status effect spawns on the mob; the runtime also installs 'Follower(you)' so existing pet-handling treats it as your follower. Mob charm persists until dismiss or the mob dies — animal-control checks against the will save aren't modeled yet, so v1 always succeeds at the schema-formula amount.$cmdhelp$),
    ($cmdhelp$tap$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Tap a staff to invoke its bound abilities.$cmdhelp$, $cmdhelp$tap <staff> [<target>]$cmdhelp$, false, $cmdhelp$Tap a staff to invoke its bound abilities.$cmdhelp$, $cmdhelp$Same charge mechanic as wave but for STAFF items. Useful for buff staves and AOE-style staff effects.$cmdhelp$),
    ($cmdhelp$taste$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Identify a liquid without drinking it.$cmdhelp$, $cmdhelp$taste <container>$cmdhelp$, false, $cmdhelp$Identify a liquid without drinking it.$cmdhelp$, $cmdhelp$Reveals the liquid name; on poisoned containers, adds an off-taste hint. No consumption.$cmdhelp$),
    ($cmdhelp$taunt$cmdhelp$, ARRAY[$cmdhelp$provoke$cmdhelp$]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Pull a mob's aggro onto yourself (tank tool).$cmdhelp$, $cmdhelp$taunt <target>$cmdhelp$, false, $cmdhelp$Pull a mob's aggro onto yourself (tank tool).$cmdhelp$, $cmdhelp$Forces the target to focus its attacks on you, regardless of who else it was engaging. Also pushes you to the front of the target's grudge list so it re-engages you first when its current target falls. Costs stamina but no damage — paired with a healer, this lets a tank hold the front line while the dps works behind them.$cmdhelp$),
    ($cmdhelp$teleport$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Send a player or mob to a room, or to wherever a target is.$cmdhelp$, $cmdhelp$teleport <player | mob> <zone> <room> | <zone:id> | <id> | <target>$cmdhelp$, true, $cmdhelp$Send a player or mob to a room, or to wherever a target is.$cmdhelp$, $cmdhelp$Builder+. Inverse of 'transfer' (which pulls them to you) and 'goto' (which moves you). The subject is a player or mob by name, 'N.name' or '<zone>:<id>' (a spawned mob instance). The destination is a room ('<zone> <id>', '<zone>:<id>', or a bare '<id>' in your zone) or any visible player, mob or object lying in a room: 'teleport bob 30:12', 'teleport 30:5 3.guard'. You cannot teleport a player of equal or higher level.$cmdhelp$),
    ($cmdhelp$tell$cmdhelp$, ARRAY[$cmdhelp$t$cmdhelp$]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Send a private message to one online player.$cmdhelp$, $cmdhelp$tell <player> <message>$cmdhelp$, false, $cmdhelp$Send a private message to one online player.$cmdhelp$, $cmdhelp$Reaches one player by name. Refused if the target is offline, has set their 'notell' flag, or is ignoring you. Stamped on the receiver as their most-recent teller for 'reply' and appended to their bounded 'lasttells' log + the persistent 'tell_message' table.$cmdhelp$),
    ($cmdhelp$throatcut$cmdhelp$, ARRAY[]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Out-of-combat assassination — 2.5x damage opener.$cmdhelp$, $cmdhelp$throatcut <target>$cmdhelp$, false, $cmdhelp$Out-of-combat assassination — 2.5x damage opener.$cmdhelp$, $cmdhelp$Like backstab but heavier: 2.5x your damage on the opening swing. Costs 8 stamina. Same engagement rules — refused if you or target are already in combat.$cmdhelp$),
    ($cmdhelp$time$cmdhelp$, ARRAY[]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Show server uptime and the game clock.$cmdhelp$, $cmdhelp$time$cmdhelp$, false, $cmdhelp$Show server uptime and the game clock.$cmdhelp$, $cmdhelp$Real-world time, how long the server has been running, and the in-game date and hour. Staff also see the current world tick.$cmdhelp$),
    ($cmdhelp$title$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Show or change the epithet shown after your name.$cmdhelp$, $cmdhelp$title [<new title> | clear]$cmdhelp$, false, $cmdhelp$Show or change the epithet shown after your name.$cmdhelp$, $cmdhelp$With no argument, prints your current title. With a new title, sets it (max 60 chars). With 'clear' (or 'none' / '-'), removes it. Persists on disconnect.$cmdhelp$),
    ($cmdhelp$tlist$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$List the triggers defined in a zone.$cmdhelp$, $cmdhelp$tlist [<zone>]$cmdhelp$, true, $cmdhelp$List the triggers defined in a zone.$cmdhelp$, $cmdhelp$Builder+. Lists every trigger in the catalog whose id is in the zone (default: your current zone) with its attach type, event flags and attachment counts.$cmdhelp$),
    ($cmdhelp$tnum$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Find triggers by name keyword (zone:id).$cmdhelp$, $cmdhelp$tnum <keywords> [in <zone>]$cmdhelp$, true, $cmdhelp$Find triggers by name keyword (zone:id).$cmdhelp$, $cmdhelp$Builder+. Lists prototypes whose name or keywords start with every word you give, as 'zone:id name', sorted by id and capped at 100 rows. 'vnum' takes a type first (mobiles, objects, rooms, triggers, exits), 'mnum' / 'onum' / 'rnum' / 'tnum' are the same search for one type. Add 'in <zone>' to stay in one zone. Pair with 'vstat', 'rstat' or 'tstat', or jump with 'goto <zone>:<id>'.$cmdhelp$),
    ($cmdhelp$toggle$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$List your toggles, or flip one on or off.$cmdhelp$, $cmdhelp$toggle [<flag>]$cmdhelp$, false, $cmdhelp$List your toggles, or flip one on or off.$cmdhelp$, $cmdhelp$With no argument, lists every toggle with its ON/OFF state. 'toggle <name>' flips one: names are matched like command abbreviations ('toggle auto' reaches the first AutoXxx in the list) and don't need underscores ('toggle showdicerolls', 'toggle dice', 'toggle show_dice_rolls' all work). 'toggle columns <n>' sets the text wrap width (see 'columns').$cmdhelp$),
    ($cmdhelp$touch$cmdhelp$, ARRAY[]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Touch an object — touchstones bind your recall.$cmdhelp$, $cmdhelp$touch <object>$cmdhelp$, false, $cmdhelp$Touch an object — touchstones bind your recall.$cmdhelp$, $cmdhelp$Looks up the named keyword in your inventory or the room. If the object's prototype 'ObjectType' is 'Touchstone', your recall point binds to the room you're standing in. Other object types just refuse — touch is currently a recall-only verb.$cmdhelp$),
    ($cmdhelp$trace$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Drill into a captured scripterror entry.$cmdhelp$, $cmdhelp$trace <N>$cmdhelp$, true, $cmdhelp$Drill into a captured scripterror entry.$cmdhelp$, $cmdhelp$Builder+. Looks up entry #N from 'scripterrors' (1 = most recent) and prints the full trigger body alongside the captured error message — so the builder doesn't have to chase (zone, id) → tstat after every failure. The body shown is the *current* catalog row; if the trigger was edited after the failure that text may not match what actually ran.$cmdhelp$),
    ($cmdhelp$track$cmdhelp$, ARRAY[$cmdhelp$hunt$cmdhelp$]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Find the direction toward a named target.$cmdhelp$, $cmdhelp$track <target>$cmdhelp$, false, $cmdhelp$Find the direction toward a named target.$cmdhelp$, $cmdhelp$BFS through open exits up to 50 rooms looking for a mob or player matching the name. Reports the direction and distance. Closed or locked doors block the scan. No perception check yet — hidden targets are tracked the same as visible ones.$cmdhelp$),
    ($cmdhelp$train$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Spend a practice point to bump a CoreStat by 1.$cmdhelp$, $cmdhelp$train [<stat>]$cmdhelp$, false, $cmdhelp$Spend a practice point to bump a CoreStat by 1.$cmdhelp$, $cmdhelp$With no arg, lists your current six stats and available practice points. With 'train <stat>', spends 1 point from 'SkillPoints' to raise the named stat (str/dex/con/int/wis/cha) by 1. Refuses on stats already at 18 (the trainable cap), and on no points available. Persists across reconnect.$cmdhelp$),
    ($cmdhelp$transfer$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Pull an online player or a mob to your current room.$cmdhelp$, $cmdhelp$transfer <player | mob | all>$cmdhelp$, true, $cmdhelp$Pull an online player or a mob to your current room.$cmdhelp$, $cmdhelp$Builder+ command. The target is a player or mob you can see, by name or keyword; 'N.name' picks the Nth match and '<zone>:<id>' (or 'N.<zone>:<id>') picks a spawned instance of that mob prototype. Moves it to wherever you are (ending any fight it is in). You cannot transfer a player of higher level than you. 'transfer all' (level 102+) pulls every online player of lower level than you.$cmdhelp$),
    ($cmdhelp$treload$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Reload the trigger catalog from the database.$cmdhelp$, $cmdhelp$treload$cmdhelp$, true, $cmdhelp$Reload the trigger catalog from the database.$cmdhelp$, $cmdhelp$Builder+. Re-queries the Triggers + attachment tables, atomically swaps the live 'TriggerCatalog' resource, and re-stamps every Room's 'AttachedTriggers'. Mob and object instances keep their current bindings — next respawn picks up catalog edits naturally. Mirrors the '/api/admin/triggers/reload' endpoint so builders can iterate without round-tripping through MCP. Routed through the async dispatcher; the sync stub only fires on dispatcher misconfig.$cmdhelp$),
    ($cmdhelp$trigattach$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Bolt a trigger onto a live entity without reloading.$cmdhelp$, $cmdhelp$trigattach <target> <zone> <id>$cmdhelp$, true, $cmdhelp$Bolt a trigger onto a live entity without reloading.$cmdhelp$, $cmdhelp$Builder+. Mutates 'AttachedTriggers' on the target so a trigger fires for it on the next relevant event. Doesn't touch the DB — survives only this session. Use for builder iteration; persist via muditor when the trigger is ready. <target> is 'here' (room), 'me' / 'self', or a name in the current room.$cmdhelp$),
    ($cmdhelp$trigdetach$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Remove a runtime trigger attachment.$cmdhelp$, $cmdhelp$trigdetach <target> <zone> <id>$cmdhelp$, true, $cmdhelp$Remove a runtime trigger attachment.$cmdhelp$, $cmdhelp$Builder+. Inverse of 'trigattach'. Removes the matching (zone, id) entry from the target's 'AttachedTriggers'. Silent no-op if no match.$cmdhelp$),
    ($cmdhelp$triggers$cmdhelp$, ARRAY[$cmdhelp$trigs$cmdhelp$]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Inspect attached triggers on entities or by id.$cmdhelp$, $cmdhelp$triggers [here | <name> | <zone> <id> | full]$cmdhelp$, true, $cmdhelp$Inspect attached triggers on entities or by id.$cmdhelp$, $cmdhelp$Builder+. Forms:
  triggers                — list attachments on every entity in the current room.
  triggers here           — same as bare form.
  triggers <name>         — list attachments on a specific mob/item by name.
  triggers <zone> <id>    — look up a trigger by catalog id (alias of 'tstat').
  triggers full [<name>]  — include the trigger body inline alongside each attachment.$cmdhelp$),
    ($cmdhelp$trighistory$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Show recent trigger fires for an entity.$cmdhelp$, $cmdhelp$trighistory [<target>] [<n>]$cmdhelp$, true, $cmdhelp$Show recent trigger fires for an entity.$cmdhelp$, $cmdhelp$Builder+. Filters the in-memory trigger fire log to fires whose listener was <target> ('here' / 'me' / 'self' / a name in the current room). With no <target>, shows the last <n> fires across all entities. <n> defaults to 20, capped at 200.$cmdhelp$),
    ($cmdhelp$tripup$cmdhelp$, ARRAY[$cmdhelp$trip$cmdhelp$]::text[], 'COMBAT'::"CommandCategory", $cmdhelp$Trip target into Resting posture (lighter than stomp).$cmdhelp$, $cmdhelp$tripup [<target>]$cmdhelp$, false, $cmdhelp$Trip target into Resting posture (lighter than stomp).$cmdhelp$, $cmdhelp$Costs 5 stamina, deals 1/4 your damage, sets the target to Resting. Like stomp but cheaper and leaves them slightly less prone.$cmdhelp$),
    ($cmdhelp$trophy$cmdhelp$, ARRAY[]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Show your recent kills (and the XP penalty band).$cmdhelp$, $cmdhelp$trophy [<player>]$cmdhelp$, false, $cmdhelp$Show your recent kills (and the XP penalty band).$cmdhelp$, $cmdhelp$Lists your most recent ~21 kill targets and the accumulated kill count per target. Re-killing targets you've farmed scales XP down — the color band on each row hints at how steep the penalty is. With a player name (Builder+), shows their trophy instead of yours.$cmdhelp$),
    ($cmdhelp$tsearch$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Search triggers by name, type, argument, script text or attachment.$cmdhelp$, $cmdhelp$tsearch <field> <query> [in <zone>]$cmdhelp$, true, $cmdhelp$Search triggers by name, type, argument, script text or attachment.$cmdhelp$, $cmdhelp$Builder+. Search one table by a field. Run it with only a type (or 'esearch' / 'tsearch' with nothing) to list the fields. Text fields match a substring; 'name' fields match whole-word prefixes of the name and keywords. Number fields take 5, >5, <5, >=5, <=5, !5 or 5..9 (an inclusive range). Add 'in <zone>' at the end to stay in one zone. Flag fields (wear, extraflags, effflags, flags, type, size, sector, ...) take one or more flag names, abbreviations allowed, and match when every one is present. Output is capped at 100 rows. Shops, zones, reset commands and skills are not searchable here.$cmdhelp$),
    ($cmdhelp$tstat$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Dump a trigger's metadata.$cmdhelp$, $cmdhelp$tstat <zone> <id> | <id>$cmdhelp$, true, $cmdhelp$Dump a trigger's metadata.$cmdhelp$, $cmdhelp$Builder+. Reads 'TriggerCatalog' and prints flags, body, fire stats. <id> alone defaults to current zone.$cmdhelp$),
    ($cmdhelp$typo$cmdhelp$, ARRAY[]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Report a typo / wording issue.$cmdhelp$, $cmdhelp$typo <message>$cmdhelp$, false, $cmdhelp$Report a typo / wording issue.$cmdhelp$, $cmdhelp$Same as 'bug' but tagged Typo. Useful for builders when reviewing room descriptions.$cmdhelp$),
    ($cmdhelp$unaffect$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Strip every active effect from a target.$cmdhelp$, $cmdhelp$unaffect <target>$cmdhelp$, true, $cmdhelp$Strip every active effect from a target.$cmdhelp$, $cmdhelp$Builder+. Despawns every 'EffectInstance' whose 'AppliedTo' is the target. Reverses any modifier deltas via the standard expiry path so stat bumps walk back cleanly. <target> is a name in the current room.$cmdhelp$),
    ($cmdhelp$unalias$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Remove a defined alias.$cmdhelp$, $cmdhelp$unalias <name>$cmdhelp$, false, $cmdhelp$Remove a defined alias.$cmdhelp$, $cmdhelp$Drops the named alias from your list. No-op if no alias by that name exists.$cmdhelp$),
    ($cmdhelp$unban$cmdhelp$, ARRAY[$cmdhelp$pardon$cmdhelp$]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Lift the active ban on a player's account.$cmdhelp$, $cmdhelp$unban <player>$cmdhelp$, true, $cmdhelp$Lift the active ban on a player's account.$cmdhelp$, $cmdhelp$Implementor-only. Inverse of 'ban'. Doesn't delete the row — flips active=false and stamps unbanned_at / unbanned_by for the audit trail.$cmdhelp$),
    ($cmdhelp$unfollow$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Stop following whoever you were following.$cmdhelp$, $cmdhelp$unfollow$cmdhelp$, false, $cmdhelp$Stop following whoever you were following.$cmdhelp$, $cmdhelp$No-op if you weren't following anyone.$cmdhelp$),
    ($cmdhelp$ungrant$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Remove a grant or revoke from a character.$cmdhelp$, $cmdhelp$ungrant <name> command <command>$cmdhelp$, true, $cmdhelp$Remove a grant or revoke from a character.$cmdhelp$, $cmdhelp$Coder+. Per-character command access. A grant lets a character use one command above their rank; a revoke takes a command away. Only online players strictly below your level, and only commands you can use yourself. 'grant <name>' lists a character's grants and revokes; 'grant <name> clear' drops the ones at or below your level. A mortal can only be granted commands on the grants.mortal_allowlist config row (empty by default), and never an admin command. Command groups and privilege flags do not exist on this server.$cmdhelp$),
    ($cmdhelp$unignore$cmdhelp$, ARRAY[]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Remove a name from your ignore list.$cmdhelp$, $cmdhelp$unignore <name>$cmdhelp$, false, $cmdhelp$Remove a name from your ignore list.$cmdhelp$, $cmdhelp$Equivalent to 'ignore -<name>'. No-op if the name isn't currently being ignored.$cmdhelp$),
    ($cmdhelp$unlock$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Unlock a locked door using a key in your inventory.$cmdhelp$, $cmdhelp$unlock <direction>$cmdhelp$, false, $cmdhelp$Unlock a locked door using a key in your inventory.$cmdhelp$, $cmdhelp$Searches your carried items for a keyword that matches the exit's required key. On match, the door is unlocked (state Closed); use 'open' to then walk through. Refused if the exit isn't locked or you have no matching key.$cmdhelp$),
    ($cmdhelp$up$cmdhelp$, ARRAY[$cmdhelp$u$cmdhelp$]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Walk through an exit.$cmdhelp$, $cmdhelp$<direction>$cmdhelp$, false, $cmdhelp$Walk through an exit.$cmdhelp$, $cmdhelp$Moves you through the named exit if one is open. Standard directions: n/s/e/w/u/d/ne/nw/se/sw/in/out.$cmdhelp$),
    ($cmdhelp$uptime$cmdhelp$, ARRAY[]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Show how long the server has been running.$cmdhelp$, $cmdhelp$uptime$cmdhelp$, false, $cmdhelp$Show how long the server has been running.$cmdhelp$, $cmdhelp$Time since the server booted.$cmdhelp$),
    ($cmdhelp$use$cmdhelp$, ARRAY[]::text[], 'MAGIC'::"CommandCategory", $cmdhelp$Use a wand or staff you are holding.$cmdhelp$, $cmdhelp$use <wand|staff> [<target>]$cmdhelp$, false, $cmdhelp$Use a wand or staff you are holding.$cmdhelp$, $cmdhelp$Wands are pointed at a target (or waved when the spell needs none); staves are tapped on the ground. Each use spends a charge only when the magic lands. The item must be held, and not too powerful for you.$cmdhelp$),
    ($cmdhelp$users$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$List connected players with level, room, idle and online time.$cmdhelp$, $cmdhelp$users$cmdhelp$, true, $cmdhelp$List connected players with level, room, idle and online time.$cmdhelp$, $cmdhelp$Immortal+. One row per online player: name, role, level, current room, idle time and time online. (Peer addresses are not tracked by the runtime yet.)$cmdhelp$),
    ($cmdhelp$validate_scripts$cmdhelp$, ARRAY[$cmdhelp$vscripts$cmdhelp$]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Compile-check every loaded Lua trigger.$cmdhelp$, $cmdhelp$validate_scripts [zone <id>]$cmdhelp$, true, $cmdhelp$Compile-check every loaded Lua trigger.$cmdhelp$, $cmdhelp$Builder+. Syntax-checks each trigger body in the catalog without running it and lists the failures. 'validate_scripts zone <id>' limits the pass to one zone. Also available as GET /api/admin/triggers/validate.$cmdhelp$),
    ($cmdhelp$value$cmdhelp$, ARRAY[$cmdhelp$appraise$cmdhelp$, $cmdhelp$val$cmdhelp$]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Show an item's catalog value in coin.$cmdhelp$, $cmdhelp$value <item>$cmdhelp$, false, $cmdhelp$Show an item's catalog value in coin.$cmdhelp$, $cmdhelp$Searches your inventory and the room for the named item, then prints its base value (the schema's 'Objects.cost') split into denominations. Shops will pay some fraction of this on sell once that lands.$cmdhelp$),
    ($cmdhelp$varclear$cmdhelp$, ARRAY[$cmdhelp$varunset$cmdhelp$]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Clear one script variable, or wipe the whole map.$cmdhelp$, $cmdhelp$varclear <target> [<key>]$cmdhelp$, true, $cmdhelp$Clear one script variable, or wipe the whole map.$cmdhelp$, $cmdhelp$Builder+. With <key>, removes that single entry. Without, wipes every variable on the target. <target> resolves the same way as 'varset' / 'varlist'.$cmdhelp$),
    ($cmdhelp$varlist$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$List script variables on an entity.$cmdhelp$, $cmdhelp$varlist [<target>]$cmdhelp$, true, $cmdhelp$List script variables on an entity.$cmdhelp$, $cmdhelp$Builder+. <target> defaults to 'here' (current room). Renders the entity's 'ScriptVars' map sorted by key. Empty maps print a contained 'no script vars' note.$cmdhelp$),
    ($cmdhelp$varset$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Set a script variable on an entity (Lua-side state).$cmdhelp$, $cmdhelp$varset <target> <key> <value...>$cmdhelp$, true, $cmdhelp$Set a script variable on an entity (Lua-side state).$cmdhelp$, $cmdhelp$Builder+. <target> is 'here' (current room), 'me' (caller), or a mob/item name in the current room. Stores into the entity's 'ScriptVars' map; reads back via 'varlist'. Lua trigger bodies will (once the binding lands) see the same map via 'actor:varget(name)'.$cmdhelp$),
    ($cmdhelp$version$cmdhelp$, ARRAY[]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Show server build identity.$cmdhelp$, $cmdhelp$version$cmdhelp$, false, $cmdhelp$Show server build identity.$cmdhelp$, $cmdhelp$Crate name, version, and the rustc/profile combo the binary was built with. For ops/debug; players will rarely care.$cmdhelp$),
    ($cmdhelp$viewchar$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$View an offline character's gear and stats.$cmdhelp$, $cmdhelp$viewchar <name>$cmdhelp$, true, $cmdhelp$View an offline character's gear and stats.$cmdhelp$, $cmdhelp$Builder+. Async DB load — pulls the Characters row + every CharacterItems row (resolved through the in-memory ObjectPrototypes for names) and prints what they're wearing / carrying. Replaces the legacy 'linkload' use case.$cmdhelp$),
    ($cmdhelp$visible$cmdhelp$, ARRAY[$cmdhelp$vis$cmdhelp$]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Stop hiding.$cmdhelp$, $cmdhelp$visible$cmdhelp$, false, $cmdhelp$Stop hiding.$cmdhelp$, $cmdhelp$Drops your hiding: back to normal visibility.$cmdhelp$),
    ($cmdhelp$visit$cmdhelp$, ARRAY[]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Step into another player's house — guest list required.$cmdhelp$, $cmdhelp$visit <player>$cmdhelp$, false, $cmdhelp$Step into another player's house — guest list required.$cmdhelp$, $cmdhelp$Refuses unless the named owner has added you as a guest via 'house guest add <you>'. Synthesizes the house's ECS rooms on first call (cached in HousingIndex), then warps you to the foyer. Async: the multi-table guest-list + room fetch runs off the world tick.$cmdhelp$),
    ($cmdhelp$vitem$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$List object prototypes by type.$cmdhelp$, $cmdhelp$vitem <type>$cmdhelp$, true, $cmdhelp$List object prototypes by type.$cmdhelp$, $cmdhelp$Builder+. Filters 'ObjectPrototypes' by 'ObjectType' (Weapon, Armor, Container, Light, Scroll, Wand, …). Case-insensitive. Capped at 50 hits with overflow footer; pair with 'ostat' to inspect any one.$cmdhelp$),
    ($cmdhelp$vnum$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Find prototypes by keyword and print their zone:id.$cmdhelp$, $cmdhelp$vnum <mobiles|objects|rooms|triggers|exits> <keywords> [in <zone>]$cmdhelp$, true, $cmdhelp$Find prototypes by keyword and print their zone:id.$cmdhelp$, $cmdhelp$Builder+. Lists prototypes whose name or keywords start with every word you give, as 'zone:id name', sorted by id and capped at 100 rows. 'vnum' takes a type first (mobiles, objects, rooms, triggers, exits), 'mnum' / 'onum' / 'rnum' / 'tnum' are the same search for one type. Add 'in <zone>' to stay in one zone. Pair with 'vstat', 'rstat' or 'tstat', or jump with 'goto <zone>:<id>'.$cmdhelp$),
    ($cmdhelp$vsearch$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Search prototypes, triggers or exits by a chosen field.$cmdhelp$, $cmdhelp$vsearch <mobiles|objects|rooms|triggers|exits> <field> <query> [in <zone>]$cmdhelp$, true, $cmdhelp$Search prototypes, triggers or exits by a chosen field.$cmdhelp$, $cmdhelp$Builder+. Search one table by a field. Run it with only a type (or 'esearch' / 'tsearch' with nothing) to list the fields. Text fields match a substring; 'name' fields match whole-word prefixes of the name and keywords. Number fields take 5, >5, <5, >=5, <=5, !5 or 5..9 (an inclusive range). Add 'in <zone>' at the end to stay in one zone. Flag fields (wear, extraflags, effflags, flags, type, size, sector, ...) take one or more flag names, abbreviations allowed, and match when every one is present. Output is capped at 100 rows. Shops, zones, reset commands and skills are not searchable here.$cmdhelp$),
    ($cmdhelp$vstat$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Show a mob or object prototype's stats without spawning it.$cmdhelp$, $cmdhelp$vstat <mob|obj> <zone> <id> | <zone>:<id> | <id>$cmdhelp$, true, $cmdhelp$Show a mob or object prototype's stats without spawning it.$cmdhelp$, $cmdhelp$Builder+. Prints the same detail as 'mstat' (mob) or 'ostat' (object) for a prototype by id. Nothing is loaded into the world. The id is '<zone> <id>', '<zone>:<id>' as 'vnum' prints it, or a bare '<id>' in your current zone. Unlike mstat / ostat, a name is not accepted: find ids with 'vnum' first.$cmdhelp$),
    ($cmdhelp$vwear$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$List object prototypes by wear-slot.$cmdhelp$, $cmdhelp$vwear <slot>$cmdhelp$, true, $cmdhelp$List object prototypes by wear-slot.$cmdhelp$, $cmdhelp$Builder+. Filters 'ObjectPrototypes' whose 'wear_flags' contain the named slot (Head, Body, Mainhand, etc.). Case-insensitive; matches the 'WearFlag' enum names from the schema.$cmdhelp$),
    ($cmdhelp$wake$cmdhelp$, ARRAY[]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Wake yourself, or rouse a sleeping companion.$cmdhelp$, $cmdhelp$wake [target]$cmdhelp$, false, $cmdhelp$Wake yourself, or rouse a sleeping companion.$cmdhelp$, $cmdhelp$With no argument, brings you out of sleep to standing. With a target, finds a sleeping player or mob in the room and stands them up; everyone in the room sees it.$cmdhelp$),
    ($cmdhelp$walk$cmdhelp$, ARRAY[$cmdhelp$land$cmdhelp$]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Come down to the ground (stop flying).$cmdhelp$, $cmdhelp$land$cmdhelp$, false, $cmdhelp$Come down to the ground (stop flying).$cmdhelp$, $cmdhelp$Ends flight (also available as 'walk'). On solid ground you simply touch down. In an air room you have nothing to stand on, so landing there means falling through the down exits until you hit something solid, and the landing hurts (a long drop hurts more; Feather Fall and the Safefall skill soften it). Flight also ends on its own when the fly spell or item that grants it runs out, or when you pick up more than about 95% of what you can carry. You need a source of flight (the fly spell, a winged form or a worn item) to 'fly' in the first place. No-op when you are already on foot.$cmdhelp$),
    ($cmdhelp$wealth$cmdhelp$, ARRAY[$cmdhelp$gold$cmdhelp$, $cmdhelp$money$cmdhelp$, $cmdhelp$coins$cmdhelp$, $cmdhelp$wallet$cmdhelp$]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Show your on-hand coin in platinum/gold/silver/copper.$cmdhelp$, $cmdhelp$wealth$cmdhelp$, false, $cmdhelp$Show your on-hand coin in platinum/gold/silver/copper.$cmdhelp$, $cmdhelp$Prints the current coin total split across the four denominations (1 platinum = 10 gold = 100 silver = 1000 copper). Use 'balance' for bank-stored coin.$cmdhelp$),
    ($cmdhelp$wear$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Equip a wearable item from your inventory.$cmdhelp$, $cmdhelp$wear <item>$cmdhelp$, false, $cmdhelp$Equip a wearable item from your inventory.$cmdhelp$, $cmdhelp$The item must have a wear-slot, and that slot must be free. Use 'remove' to take something off first.$cmdhelp$),
    ($cmdhelp$weather$cmdhelp$, ARRAY[]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Atmospheric flavor for your zone's climate.$cmdhelp$, $cmdhelp$weather$cmdhelp$, false, $cmdhelp$Atmospheric flavor for your zone's climate.$cmdhelp$, $cmdhelp$Renders a single line based on your current zone's 'Climate' and the in-game time of day. Rule-of-thumb only — no per-tick weather simulation yet, so the same input produces the same output.$cmdhelp$),
    ($cmdhelp$west$cmdhelp$, ARRAY[$cmdhelp$w$cmdhelp$]::text[], 'MOVEMENT'::"CommandCategory", $cmdhelp$Walk through an exit.$cmdhelp$, $cmdhelp$<direction>$cmdhelp$, false, $cmdhelp$Walk through an exit.$cmdhelp$, $cmdhelp$Moves you through the named exit if one is open. Standard directions: n/s/e/w/u/d/ne/nw/se/sw/in/out.$cmdhelp$),
    ($cmdhelp$where$cmdhelp$, ARRAY[]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Show your location, a named player's location, or list all online.$cmdhelp$, $cmdhelp$where [<name> | corpse | all]$cmdhelp$, false, $cmdhelp$Show your location, a named player's location, or list all online.$cmdhelp$, $cmdhelp$With no argument, prints your own current room (name, zone, id). With a player name, prints that online player's current room. 'where corpse' tells you where your own corpse lies and which way to go. 'where all' (Builder+ only) lists every online player and where they are.

Immortal+: 'where <name>' also searches live mobs (M lines: [zone:id] name - room) and objects (O lines, including carried, worn and contained ones) whose name or keywords match.$cmdhelp$),
    ($cmdhelp$whisper$cmdhelp$, ARRAY[]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Quietly say something to one person in the room.$cmdhelp$, $cmdhelp$whisper <target> <message>$cmdhelp$, false, $cmdhelp$Quietly say something to one person in the room.$cmdhelp$, $cmdhelp$Both you and the target see the full text. Other players in the room see that you whispered to them but not what.$cmdhelp$),
    ($cmdhelp$who$cmdhelp$, ARRAY[]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$List players currently online.$cmdhelp$, $cmdhelp$who [<min-level> [<max-level>]] | who clan <abbrev>$cmdhelp$, false, $cmdhelp$List players currently online.$cmdhelp$, $cmdhelp$With no args, shows every connected player. With one numeric arg, filters to players at that level or higher. With two numeric args, filters to the inclusive level range. 'who clan <abbrev>' filters to players in the named clan (case-insensitive match against the '[ABBR]' tag shown alongside each name).$cmdhelp$),
    ($cmdhelp$whoami$cmdhelp$, ARRAY[]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Print your character's name, level, race, and class.$cmdhelp$, $cmdhelp$whoami$cmdhelp$, false, $cmdhelp$Print your character's name, level, race, and class.$cmdhelp$, $cmdhelp$One-line answer to "which character am I logged in as?" — handy after a long session or when a script needs to confirm identity. Pair with 'score' for the full sheet.$cmdhelp$),
    ($cmdhelp$wield$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Wield a weapon (shortcut for wear into the Wield slot).$cmdhelp$, $cmdhelp$wield <item>$cmdhelp$, false, $cmdhelp$Wield a weapon (shortcut for wear into the Wield slot).$cmdhelp$, $cmdhelp$Equivalent to wear, but only succeeds for items that go into the wield slot.$cmdhelp$),
    ($cmdhelp$wimpy$cmdhelp$, ARRAY[]::text[], 'SYSTEM'::"CommandCategory", $cmdhelp$Set the HP percentage at which combat auto-flees you.$cmdhelp$, $cmdhelp$wimpy [pct|off]$cmdhelp$, false, $cmdhelp$Set the HP percentage at which combat auto-flees you.$cmdhelp$, $cmdhelp$'wimpy 30' enables wimpy mode and panics you out of combat when your HP drops below 30% of max. 'wimpy off' (or 'wimpy 0') clears it. With no argument, prints the current setting. Default threshold when no number was set is 25%.$cmdhelp$),
    ($cmdhelp$withdraw$cmdhelp$, ARRAY[$cmdhelp$with$cmdhelp$]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Move coin from the bank to on-hand wealth.$cmdhelp$, $cmdhelp$withdraw <amount> [copper|silver|gold|platinum] | withdraw all$cmdhelp$, false, $cmdhelp$Move coin from the bank to on-hand wealth.$cmdhelp$, $cmdhelp$A bare number is copper ('withdraw 50' is 50 copper); add a unit for more ('withdraw 2 silver'). Refuses if your bank balance can't cover the amount. Inverse of 'deposit'.$cmdhelp$),
    ($cmdhelp$wizhelp$cmdhelp$, ARRAY[$cmdhelp$whelp$cmdhelp$]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$List admin commands or show details on a specific one.$cmdhelp$, $cmdhelp$wizhelp [command]$cmdhelp$, true, $cmdhelp$List admin commands or show details on a specific one.$cmdhelp$, $cmdhelp$Builder+ counterpart of 'help'. With no arguments, lists every admin command you can run. With an argument, shows the usage and details for that command — same shape as 'help', but scoped to admin tools so the player help stays uncluttered.$cmdhelp$),
    ($cmdhelp$wizinvis$cmdhelp$, ARRAY[$cmdhelp$invis$cmdhelp$]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Become invisible to lower-level players.$cmdhelp$, $cmdhelp$wizinvis [<level> | off]$cmdhelp$, true, $cmdhelp$Become invisible to lower-level players.$cmdhelp$, $cmdhelp$Builder+. With no arg, toggles invis at your own level. 'wizinvis <level>' sets to that exact level (capped at your own). 'wizinvis off' clears it. Players whose level is below yours (or below the explicit level) won't see you in 'who' / 'look' / 'scan' listings.$cmdhelp$),
    ($cmdhelp$wizlist$cmdhelp$, ARRAY[]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$List the staff of the game.$cmdhelp$, $cmdhelp$wizlist$cmdhelp$, false, $cmdhelp$List the staff of the game.$cmdhelp$, $cmdhelp$Shows the immortals who run the game, grouped by rank. A '*' marks staff who are online right now.$cmdhelp$),
    ($cmdhelp$wizlock$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Lock the mud to staff-only logins.$cmdhelp$, $cmdhelp$wizlock [on|off]$cmdhelp$, true, $cmdhelp$Lock the mud to staff-only logins.$cmdhelp$, $cmdhelp$Builder+. With no arg, prints the current state. 'wizlock on' blocks non-staff (UserRole < Builder) from completing login; 'wizlock off' clears the gate. Reset to off on every server restart so a forgotten lock doesn't outlive the deploy.$cmdhelp$),
    ($cmdhelp$wiznet$cmdhelp$, ARRAY[$cmdhelp$;$cmdhelp$]::text[], 'COMMUNICATION'::"CommandCategory", $cmdhelp$Chat on the staff-only wiznet channel.$cmdhelp$, $cmdhelp$wiznet <message>$cmdhelp$, true, $cmdhelp$Chat on the staff-only wiznet channel.$cmdhelp$, $cmdhelp$Immortal+. Sent to every online staff member (Immortal or higher). Players never see wiznet traffic. Convention: out-of-character coordination between staff during play.$cmdhelp$),
    ($cmdhelp$world$cmdhelp$, ARRAY[$cmdhelp$stats$cmdhelp$]::text[], 'INFORMATION'::"CommandCategory", $cmdhelp$Live entity counts: zones, rooms, mobs, items, players.$cmdhelp$, $cmdhelp$world$cmdhelp$, false, $cmdhelp$Live entity counts: zones, rooms, mobs, items, players.$cmdhelp$, $cmdhelp$Snapshot of the world state right now: how many zones and rooms loaded, how many live mobs and items spawned, how many players online, uptime (plus the server tick for staff), and active effect-instance count. Aliases 'users' and 'stats' mirror 'world' since the player count and per-system load are the most-asked pieces.$cmdhelp$),
    ($cmdhelp$write$cmdhelp$, ARRAY[]::text[], 'OBJECT'::"CommandCategory", $cmdhelp$Write a message on a note or paper.$cmdhelp$, $cmdhelp$write <object> <message>$cmdhelp$, false, $cmdhelp$Write a message on a note or paper.$cmdhelp$, $cmdhelp$Writes the message onto a note-type object you carry or that lies in the room, replacing whatever was there. Anyone can then 'read' it.$cmdhelp$),
    ($cmdhelp$zlist$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$List every loaded zone (id + name).$cmdhelp$, $cmdhelp$zlist$cmdhelp$, true, $cmdhelp$List every loaded zone (id + name).$cmdhelp$, $cmdhelp$Builder+. Sorted by zone id. Use 'znum <name>' to look up the id of a zone you only know by name, or 'zsearch <substring>' for a fuzzy match.$cmdhelp$),
    ($cmdhelp$znum$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Print the zone id whose name exactly matches.$cmdhelp$, $cmdhelp$znum <name>$cmdhelp$, true, $cmdhelp$Print the zone id whose name exactly matches.$cmdhelp$, $cmdhelp$Builder+. Case-insensitive whole-name match. For substring search use 'zsearch'.$cmdhelp$),
    ($cmdhelp$zreset$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Despawn reset-spawned mobs/objects so respawn refills the zone.$cmdhelp$, $cmdhelp$zreset [<zone_id>]$cmdhelp$, true, $cmdhelp$Despawn reset-spawned mobs/objects so respawn refills the zone.$cmdhelp$, $cmdhelp$Builder+. With no arg, resets your current zone. Despawns every mob and object that came from a 'MobResets' / 'ObjectResets' row in the named zone. The next respawn tick (~6s) refills the gaps. Admin-summoned / loadobj'd entities are preserved (no 'FromMobReset' / 'FromObjectReset' marker).$cmdhelp$),
    ($cmdhelp$zsearch$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Find zones by name substring.$cmdhelp$, $cmdhelp$zsearch <substring>$cmdhelp$, true, $cmdhelp$Find zones by name substring.$cmdhelp$, $cmdhelp$Builder+. Case-insensitive substring against the zone's 'Named'. Capped at 50 hits.$cmdhelp$),
    ($cmdhelp$zstat$cmdhelp$, ARRAY[]::text[], 'ADMIN'::"CommandCategory", $cmdhelp$Dump ECS state of a zone.$cmdhelp$, $cmdhelp$zstat [<zone_id>]$cmdhelp$, true, $cmdhelp$Dump ECS state of a zone.$cmdhelp$, $cmdhelp$Builder+. With no arg, inspects the zone you're in. Prints zone metadata + entity / mob / item counts.$cmdhelp$)
) AS v(name, aliases, category, description, usage, immortal_only, help_summary, help_text)
ON CONFLICT ("name") DO UPDATE SET
    "help_summary" = CASE WHEN COALESCE("Command"."help_summary", '') = ''
        THEN EXCLUDED."help_summary" ELSE "Command"."help_summary" END,
    "help_text" = CASE WHEN COALESCE("Command"."help_text", '') = ''
        THEN EXCLUDED."help_text" ELSE "Command"."help_text" END;

COMMIT;
